import { AIProvider, AIProviderConfig, AIRequest, AIResponse, AIModel, DockerfileFixResponse, KubernetesFixResponse, JenkinsfileFixResponse, LogInvestigationResponse, DependencyFixResponse, GitHubCodeFixResponse } from './types';
import { BaseAIProvider } from './base';
import { AppsScriptProvider } from './providers/apps-script';
import { config } from '../config';
import { prisma } from '../database';

export class AIService {
  private providers: Map<string, AIProvider> = new Map();
  private defaultProvider: string = 'apps_script';
  private initialized = false;

  async initialize(): Promise<void> {
    if (this.initialized) return;

    // Load provider configs from database
    const settings = await prisma.settings.findFirst();
    const providerType = settings?.aiProvider || 'apps_script';

    // Initialize Apps Script provider (default)
    const appsScriptProvider = new AppsScriptProvider();
    await appsScriptProvider.initialize({
      endpoint: settings?.aiAppsScriptUrl || config.AI_APPS_SCRIPT_URL,
      apiKey: settings?.aiOpenaiKey // Reusing field for API key
    });
    this.providers.set('apps_script', appsScriptProvider);

    // Initialize other providers if configured
    if (settings?.aiOpenaiKey) {
      // OpenAI provider would be initialized here
