18	
19	async function bootstrap() {
20	  const app = Fastify({
21	    logger: config.NODE_ENV === 'development' ? {
22	      transport: {
23	        target: 'pino-pretty',
24	        options: { colorize: true, translateTime: 'HH:MM:ss Z', ignore: 'pid,hostname' }
25	      }
26	    } : true
27	  }).withTypeProvider<ZodTypeProvider>();
28	
29	  // Security plugins
30	  await app.register(fastifyHelmet, {
31	    contentSecurityPolicy: {
32	      directives: {
33	        defaultSrc: ["'self'"],
34	        scriptSrc: ["'self'", "'unsafe-inline'"],
35	        styleSrc: ["'self'", "'unsafe-inline'"],
36	        imgSrc: ["'self'", 'data:', 'https:'],
37	        connectSrc: ["'self'", 'ws:', 'wss:']
38	      }
39	    }
40	  });
41	
42	  await app.register(fastifyCors, {
43	    origin: config.CORS_ORIGIN,
44	    credentials: true,
45	    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']
46	  });
47	
48	  await app.register(fastifyRateLimit, {
49	    max: config.RATE_LIMIT_MAX,
50	    timeWindow: config.RATE_LIMIT_WINDOW,
51	    keyGenerator: (req) => req.ip
52	  });
53	
54	  // Auth plugin
55	  await app.register(fastifyJwt, {
56	    secret: config.JWT_SECRET,
57	    sign: { expiresIn: config.JWT_EXPIRES_IN },
58	    verify: { algorithms: ['HS256'] }
59	  });
60	
61	  app.decorate('authenticate', async (request: any, reply: any) => {
62	    try {
63	      await request.jwtVerify();
64	    } catch (err) {
65	      reply.code(401).send({ success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid or expired token', statusCode: 401 } });
66	    }
67	  });
68	
69	  // Multipart for file uploads
70	  await app.register(fastifyMultipart, {
71	    limits: {
72	      fileSize: config.MAX_FILE_SIZE,
73	      files: 10
74	    }
75	  });
76	
77	  // WebSocket for real-time updates
78	  await app.register(fastifyWebsocket);
79	  initializeWebSocket(app);
80	
81	  // Health check
82	  app.get('/health', async () => ({
83	    status: 'ok',
84	    timestamp: new Date().toISOString(),
85	    version: config.APP_VERSION
86	  }));
87	
88	  // Register all routes
89	  await registerRoutes(app);
90	
91	  // Error handler
92	  app.setErrorHandler((error, request, reply) => {
93	    logger.error({ err: error, url: request.url }, 'Request error');
94	
95	    if (error.validation) {
96	      return reply.code(400).send({
97	        success: false,
98	        error: {
99	          code: 'VALIDATION_ERROR',
100	          message: 'Invalid request data',
101	          details: error.validation,
102	          statusCode: 400
103	        }
104	      });
105	    }
106	
107	    const statusCode = error.statusCode || 500;
108	    reply.code(statusCode).send({
109	      success: false,
110	      error: {
111	        code: error.code || 'INTERNAL_ERROR',
112	        message: error.message || 'Internal server error',
113	        statusCode
114	      }
115	    });
116	  });
117	
118	  // 404 handler
119	  app.setNotFoundHandler((request, reply) => {
120	    reply.code(404).send({
121	      success: false,
122	      error: { code: 'NOT_FOUND', message: `Route ${request.method} ${request.url} not found`, statusCode: 404 }
123	    });
124	  });
125	
126	  // Graceful shutdown
127	  const shutdown = async (signal: string) => {
128	    logger.info({ signal }, 'Shutting down...');
129	    await shutdownQueue();
130	    await app.close();
131	    await prisma.$disconnect();
132	    process.exit(0);
133	  };
134	
135	  process.on('SIGTERM', () => shutdown('SIGTERM'));
136	  process.on('SIGINT', () => shutdown('SIGINT'));
137	
138	  try {
139	    // Initialize database
140	    await prisma.$connect();
141	    logger.info('Database connected');
142	
143	    // Initialize job queue
144	    await initializeQueue();
145	    logger.info('Job queue initialized');
146	
147	    // Start server
148	    await app.listen({ port: config.PORT, host: config.HOST });
149	    logger.info(`Server running on http://${config.HOST}:${config.PORT}`);
150	  } catch (err) {
151	    logger.error(err, 'Failed to start server');
152	    process.exit(1);
153	  }
154	}
155	
