    const valid = await verifyPassword(currentPassword, user.passwordHash);
    if (!valid) {
      return reply.code(401).send({ success: false, error: { code: 'INVALID_PASSWORD', message: 'Current password is incorrect', statusCode: 401 } });
    }

    const passwordHash = await hashPassword(newPassword);
    await prisma.user.update({ where: { id: userId }, data: { passwordHash } });

    await auditLog(request, 'PASSWORD_CHANGED', 'user', userId);

    return { success: true, message: 'Password changed successfully' };
  });

  // OAuth routes (placeholder - would redirect to provider)
  app.get('/github', async (request, reply) => {
    // In production, redirect to GitHub OAuth
    return reply.redirect('/login?error=oauth_not_configured');
  });

  app.get('/gitlab', async (request, reply) => {
    return reply.redirect('/login?error=oauth_not_configured');
  });

  app.get('/bitbucket', async (request, reply) => {
    return reply.redirect('/login?error=oauth_not_configured');
  });
}

