import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanRepoSchema = z.object({
  repoUrl: z.string().url(),
  branch: z.string().optional().default('main'),
  manifestPath: z.string().optional()
});

const scanManifestSchema = z.object({
  manifest: z.string().min(1),
  format: z.enum(['package-json', 'pom-xml', 'requirements-txt', 'go-mod', 'cargo-toml', 'composer-json', 'gemfile']).optional(),
  targetName: z.string().optional()
});

const remediateSchema = z.object({
  scanId: z.string().uuid(),
  packageName: z.string(),
  currentVersion: z.string()
});

const exportSbomSchema = z.object({
  scanId: z.string().uuid(),
  format: z.enum(['cyclonedx', 'spdx']).optional().default('cyclonedx')
});

export async function dependenciesRoutes(app: FastifyInstance) {
  // Scan repository for dependencies
  app.post('/scan-repo', {
    preHandler: [app.authenticate],
    schema: { body: scanRepoSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { repoUrl, branch, manifestPath } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'dependency',
        status: 'pending',
        targetType: 'git_repo',
        targetValue: repoUrl,
        targetMeta: { branch, manifestPath },
        userId
      }
    });

    const job = await createJob('dependency_scan', {
      scanId: scan.id,
      repoUrl,
      branch,
      manifestPath
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'DEPENDENCY_SCAN_REPO_STARTED', 'scan', scan.id, { repoUrl, branch });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Scan uploaded manifest
  app.post('/scan-manifest', {
    preHandler: [app.authenticate],
    schema: { body: scanManifestSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { manifest, format, targetName } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'dependency',
        status: 'pending',
        targetType: 'manifest',
        targetValue: targetName || 'manifest',
        targetMeta: { manifest, format },
        userId
      }
    });

    const job = await createJob('dependency_scan', {
      scanId: scan.id,
      manifest,
      format
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'DEPENDENCY_SCAN_MANIFEST_STARTED', 'scan', scan.id, { targetName, format });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // AI Remediation
  app.post('/remediate', {
    preHandler: [app.authenticate],
    schema: { body: remediateSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, packageName, currentVersion } = request.body;

    const scan = await prisma.scan.findUnique({ where: { id: scanId } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('dependency_fix', {
      scanId,
      packageName,
      currentVersion
    }, userId);

    await auditLog(request, 'DEPENDENCY_REMEDIATE_STARTED', 'scan', scanId, { packageName, currentVersion });
    return { success: true, data: { jobId: job.id } };
  });

  // Export SBOM
  app.post('/export-sbom', {
    preHandler: [app.authenticate],
    schema: { body: exportSbomSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, format } = request.body;

    const scan = await prisma.scan.findUnique({ where: { id: scanId } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('sbom_generation', {
      scanId,
      format
    }, userId);

    await auditLog(request, 'SBOM_EXPORT_STARTED', 'scan', scanId, { format });
    return { success: true, data: { jobId: job.id } };
  });

  // Get SBOM
  app.get('/scan/:id/sbom', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan.targetMeta };
  });
}

