import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { auditLog } from '../../shared/utils/audit';

const listSchema = z.object({
  page: z.number().optional().default(1),
  pageSize: z.number().optional().default(20),
  status: z.array(z.enum(['queued', 'running', 'analyzing', 'fixing', 'completed', 'failed', 'cancelled'])).optional(),
  type: z.array(z.string()).optional()
});

export async function jobsRoutes(app: FastifyInstance) {
  // List jobs
  app.get('/', {
    preHandler: [app.authenticate],
    schema: { querystring: listSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { page, pageSize, status, type } = request.query as any;

    const where: any = { userId };
    if (status?.length) where.status = { in: status };
    if (type?.length) where.type = { in: type };

    const [jobs, total] = await Promise.all([
      prisma.job.findMany({
        where,
        orderBy: { createdAt: 'desc' },
        take: pageSize,
        skip: (page - 1) * pageSize,
        include: { scan: { select: { id: true, name: true, type: true } } }
      }),
      prisma.job.count({ where })
    ]);

    return {
      success: true,
      data: {
        jobs,
        total,
        totalPages: Math.ceil(total / pageSize),
        page,
        pageSize
      }
    };
  });

  // Get job details
  app.get('/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const job = await prisma.job.findUnique({
      where: { id },
      include: { scan: true }
    });

    if (!job || job.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Job not found', statusCode: 404 } });
    }

    return { success: true, data: job };
  });

  // Cancel job
  app.post('/:id/cancel', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

