import { Queue, Worker, Job, QueueEvents } from 'bullmq';
import { config } from '../config';
import { prisma } from '../database';
import { aiService } from '../ai';
import { logger } from '../utils/logger';
import { JobType, JobStatus } from '@devsecops/shared/types';

interface JobData {
  type: JobType;
  input: Record<string, unknown>;
  userId: string;
  scanId?: string;
}

const queue = new Queue<JobData>('devsecops-jobs', {
  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
  defaultJobOptions: {
    removeOnComplete: 100,
    removeOnFail: 50,
    attempts: 3,
    backoff: { type: 'exponential', delay: 5000 },
    timeout: config.JOB_TIMEOUT
  }
});

const queueEvents = new QueueEvents('devsecops-jobs', {
  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') }
});

queueEvents.on('completed', async ({ jobId, returnvalue }) => {
  await updateJobStatus(jobId, 'completed', 100, 'Completed', returnvalue as any);
});

queueEvents.on('failed', async ({ jobId, failedReason }) => {
  await updateJobStatus(jobId, 'failed', 0, 'Failed', undefined, failedReason);
});

queueEvents.on('progress', async ({ jobId, data }) => {
  if (data && typeof data === 'object' && 'progress' in data) {
    await updateJobProgress(jobId, data.progress as number, data.currentStep as string);
  }
});

export async function initializeQueue(): Promise<void> {
  // Create workers for each job type
  const worker = new Worker<JobData>(
    'devsecops-jobs',
    async (job) => await processJob(job),
    {
      connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
      concurrency: config.QUEUE_CONCURRENCY
    }
  );

  worker.on('error', (err) => logger.error({ err }, 'Queue worker error'));
  logger.info('Job queue workers started');
}

export async function shutdownQueue(): Promise<void> {
  await queue.close();
  await queueEvents.close();
}

export async function createJob(data: JobData, priority: 'low' | 'normal' | 'high' = 'normal'): Promise<string> {
  const job = await queue.add(data.type, data, {
    priority: priority === 'high' ? 10 : priority === 'low' ? 1 : 5
  });
  return job.id!;
}

export async function getJobStatus(jobId: string): Promise<any> {
  const job = await queue.getJob(jobId);
  if (!job) return null;

  const state = await job.getState();
  const progress = job.progress;

  return {
    id: job.id,
    type: job.name,
    status: state,
    progress: typeof progress === 'number' ? progress : 0,
    data: job.data,
    returnvalue: job.returnvalue,
    failedReason: job.failedReason,
    createdAt: new Date(job.timestamp).toISOString(),
    processedAt: job.processedOn ? new Date(job.processedOn).toISOString() : null,
    finishedAt: job.finishedOn ? new Date(job.finishedOn).toISOString() : null
  };
}

export async function cancelJob(jobId: string): Promise<boolean> {
  const job = await queue.getJob(jobId);
  if (job) {
    await job.remove();
    await updateJobStatus(jobId, 'cancelled', 0, 'Cancelled');
    return true;
  }
  return false;
}

async function updateJobStatus(
  jobId: string,
  status: JobStatus,
  progress: number,
  currentStep: string,
  output?: any,
  error?: string
): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: {
      status,
      progress,
      currentStep,
      output,
      error,
      completedAt: ['completed', 'failed', 'cancelled'].includes(status) ? new Date() : null
    }
  });
}

async function updateJobProgress(jobId: string, progress: number, currentStep: string): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: { progress, currentStep }
  });
}

async function processJob(job: Job<JobData>): Promise<any> {
  const { type, input, userId, scanId } = job.data;

  await prisma.job.update({
    where: { id: job.id },
    data: { status: 'running', startedAt: new Date() }
  });

  try {
    let result: any;

    switch (type) {
      case 'dockerfile_scan':
        result = await processDockerfileScan(input, job);
        break;
      case 'dockerfile_fix':
        result = await processDockerfileFix(input, job);
        break;
      case 'docker_image_scan':
        result = await processDockerImageScan(input, job);
        break;
      case 'docker_image_fix':
        result = await processDockerImageFix(input, job);
        break;
      case 'kubernetes_scan':
        result = await processKubernetesScan(input, job);
        break;
      case 'kubernetes_fix':
        result = await processKubernetesFix(input, job);
        break;
      case 'kubernetes_generate':
        result = await processKubernetesGenerate(input, job);
        break;
      case 'jenkinsfile_scan':
        result = await processJenkinsfileScan(input, job);
        break;
      case 'jenkinsfile_fix':
        result = await processJenkinsfileFix(input, job);
        break;
      case 'jenkinsfile_generate':
        result = await processJenkinsfileGenerate(input, job);
        break;
      case 'github_repo_scan':
        result = await processGitHubRepoScan(input, job);
        break;
      case 'log_investigation':
        result = await processLogInvestigation(input, job);
        break;
      case 'dependency_scan':
        result = await processDependencyScan(input, job);
        break;
      case 'dependency_fix':
        result = await processDependencyFix(input, job);
        break;
      case 'sbom_generation':
        result = await processSBOMGeneration(input, job);
        break;
      default:
        throw new Error(`Unknown job type: ${type}`);
    }

    // Create scan record if applicable
    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: {
          status: 'completed',
          summary: result.summary,
          completedAt: new Date()
        }
      });
    }

    return result;
  } catch (error) {
    logger.error({ err: error, jobId: job.id, type }, 'Job processing failed');

    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: { status: 'failed', completedAt: new Date() }
      });
    }

    throw error;
  }
}

// Job processors (implementations will be in separate modules)
async function processDockerfileScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Parsing Dockerfile' });
  // Implementation in dockerfile module
  return { summary: { totalFindings: 0, critical: 0, high: 0, medium: 0, low: 0, info: 0 } };
}

async function processDockerfileFix(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing issues' });
  // Implementation in dockerfile module
  return { fixedDockerfile: input.content, changes: [] };
}

async function processDockerImageScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Pulling image metadata' });
  // Implementation in docker module
  return { summary: { totalFindings: 0, critical: 0, high: 0, medium: 0, low: 0, info: 0 } };
}

async function processDockerImageFix(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing vulnerabilities' });
  // Implementation in docker module
  return { fixedDockerfile: '', beforeVulnerabilities: [], afterVulnerabilities: [] };
}

async function processKubernetesScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Parsing YAML' });
  // Implementation in kubernetes module
  return { summary: { totalFindings: 0, critical: 0, high: 0, medium: 0, low: 0, info: 0 } };
}

async function processKubernetesFix(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing issues' });
  // Implementation in kubernetes module
  return { fixedYaml: input.content, changes: [] };
}

async function processKubernetesGenerate(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Generating YAML' });
  // Implementation in kubernetes module
  return { yaml: '' };
}

async function processJenkinsfileScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Parsing Jenkinsfile' });
  // Implementation in jenkins module
  return { summary: { totalFindings: 0, critical: 0, high: 0, medium: 0, low: 0, info: 0 } };
}

async function processJenkinsfileFix(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing issues' });
  // Implementation in jenkins module
  return { fixedJenkinsfile: input.content, changes: [] };
}

async function processJenkinsfileGenerate(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Generating Jenkinsfile' });
  // Implementation in jenkins module
  return { jenkinsfile: '' };
}

async function processGitHubRepoScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Cloning repository' });
  // Implementation in github module
  return { summary: { totalFindings: 0, critical: 0, high: 0, medium: 0, low: 0, info: 0 } };
}

async function processLogInvestigation(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Loading log entries' });
  // Implementation in logs module
  return { rootCause: '', evidence: [], timeline: [] };
}

async function processDependencyScan(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing manifests' });
  // Implementation in dependencies module
  return { summary: { totalDependencies: 0, vulnerabilities: { critical: 0, high: 0, medium: 0, low: 0 }, outdated: 0 } };
}

async function processDependencyFix(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Analyzing dependency' });
  // Implementation in dependencies module
  return { updatedManifest: '', changes: [] };
}

async function processSBOMGeneration(input: any, job: Job): Promise<any> {
  await job.updateProgress({ progress: 10, currentStep: 'Generating SBOM' });
  // Implementation in dependencies module
  return { sbom: { packages: [], relationships: [], metadata: {} } };
}

