import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  yaml: z.string().min(1),
  targetName: z.string().optional(),
  tools: z.array(z.enum(['kubeconform', 'kubeval', 'checkov'])).optional().default(['kubeconform'])
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findings: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    code: z.string().optional(),
    ruleId: z.string().optional(),
    remediation: z.any().optional()
  })).optional()
});

const generateSchema = z.object({
  type: z.enum(['deployment', 'service', 'ingress', 'configmap', 'secret', 'pvc', 'cronjob']),
  name: z.string(),
  namespace: z.string().optional().default('default'),
  image: z.string().optional(),
  replicas: z.number().optional().default(1),
  ports: z.array(z.object({ port: z.number(), targetPort: z.number().optional() })).optional(),
  env: z.array(z.object({ name: z.string(), value: z.string() })).optional(),
  resources: z.object({
    limits: z.object({ cpu: z.string().optional(), memory: z.string().optional() }).optional(),
    requests: z.object({ cpu: z.string().optional(), memory: z.string().optional() }).optional()
  }).optional()
});

export async function kubernetesRoutes(app: FastifyInstance) {
  // Scan Kubernetes YAML
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { yaml, targetName, tools } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'kubernetes',
        status: 'pending',
        targetType: 'kubernetes_yaml',
        targetValue: targetName || 'kubernetes.yaml',
        targetMeta: { yaml, tools },
        userId
      }
    });

    const job = await createJob('kubernetes_scan', {
      scanId: scan.id,
      yaml,
      tools
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'KUBERNETES_SCAN_STARTED', 'scan', scan.id, { targetName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Fix Kubernetes YAML
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findings } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('kubernetes_fix', {
      scanId,
      yaml: (scan.targetMeta as any)?.yaml || '',
      findings: findings || scan.findings
    }, userId);

    await auditLog(request, 'KUBERNETES_FIX_STARTED', 'scan', scanId);
    return { success: true, data: { jobId: job.id } };
  });

  // Generate Kubernetes YAML
  app.post('/generate', {
    preHandler: [app.authenticate],
    schema: { body: generateSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { type, name, namespace, image, replicas, ports, env, resources } = request.body;

    const job = await createJob('kubernetes_generate', {
      type,
      name,
      namespace,
      image,
      replicas,
      ports,
      env,
      resources
    }, userId);

    await auditLog(request, 'KUBERNETES_GENERATE_STARTED', 'job', job.id, { type, name });
    return { success: true, data: { jobId: job.id } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });
}

