import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const connectSchema = z.object({
  token: z.string().min(1),
  org: z.string().optional()
});

const scanSchema = z.object({
  repoUrl: z.string().url(),
  branch: z.string().optional().default('main'),
  scanTypes: z.array(z.enum(['vulnerabilities', 'secrets', 'dependencies', 'code'])).optional().default(['vulnerabilities', 'secrets', 'dependencies', 'code'])
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findingId: z.string(),
  branch: z.string().optional().default('main'),
  fixType: z.enum(['patch', 'upgrade', 'config'])
});

const createPrSchema = z.object({
  repoId: z.string(),
  branch: z.string(),
  title: z.string(),
  body: z.string().optional(),
  changes: z.array(z.object({
    file: z.string(),
    content: z.string()
  }))
});

export async function githubRoutes(app: FastifyInstance) {
  // Connect GitHub
  app.post('/connect', {
    preHandler: [app.authenticate],
    schema: { body: connectSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { token, org } = request.body;

    // In production, validate token with GitHub API and fetch user/org info
    // For now, create a mock repository entry
    const repo = await prisma.gitHubRepository.create({
      data: {
        userId,
        githubId: Date.now(),
        name: org || 'connected-repo',
        fullName: `${org || 'user'}/connected-repo`,
        url: `https://github.com/${org || 'user'}/connected-repo`,
        cloneUrl: `https://github.com/${org || 'user'}/connected-repo.git`,
        defaultBranch: 'main'
      }
    });

    await auditLog(request, 'GITHUB_CONNECTED', 'github_repo', repo.id, { org });

    return { success: true, data: { connected: true, repo } };
  });

  // Scan GitHub repository
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { repoUrl, branch, scanTypes } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'github_repo',
        status: 'pending',
        targetType: 'github_repo',
        targetValue: repoUrl,
        targetMeta: { branch, scanTypes },
        userId
      }
    });

    const job = await createJob('github_repo_scan', {
      scanId: scan.id,
      repoUrl,
      branch,
      scanTypes
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'GITHUB_SCAN_STARTED', 'scan', scan.id, { repoUrl, branch, scanTypes });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Get scan status
  app.get('/scan/:id/status', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    // If scan has a job, get job status
    let jobStatus = 'pending';
    let progress = 0;
    if (scan.jobId) {
      const job = await prisma.job.findUnique({ where: { id: scan.jobId } });
      if (job) {
        jobStatus = job.status;
        progress = job.progress;
      }
    }

    return { success: true, data: { status: jobStatus, progress } };
  });

  // Get scan results
  app.get('/scan/:id/results', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // Fix finding
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findingId, branch, fixType } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: { where: { id: findingId } } }
    });

    if (!scan || scan.userId !== userId || scan.findings.length === 0) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Finding not found', statusCode: 404 } });
    }

    const finding = scan.findings[0];
    const job = await createJob('github_code_scan', {
      scanId,
      findingId,
      branch,
      fixType,
      finding: {
        id: finding.id,
        type: finding.type,
        severity: finding.severity,
        title: finding.title,
        description: finding.description,
        file: finding.file,
        line: finding.line,
        code: finding.code,
        ruleId: finding.ruleId
      }
    }, userId);

    await auditLog(request, 'GITHUB_FIX_STARTED', 'finding', findingId);
    return { success: true, data: { jobId: job.id } };
  });

  // Create PR
  app.post('/create-pr', {
    preHandler: [app.authenticate],
    schema: { body: createPrSchema }
  }, async (request, reply) => {
    // In production, use GitHub API to create PR
    const { repoId, branch, title, body, changes } = request.body;

    await auditLog(request, 'GITHUB_PR_CREATED', 'github_repo', repoId, { branch, title });

    return {
      success: true,
      data: {
        prUrl: `https://github.com/repo/pull/123`,
        prNumber: 123
      }
    };
  });

  // List connected repos
  app.get('/repos', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const repos = await prisma.gitHubRepository.findMany({
      where: { userId },
      orderBy: { connectedAt: 'desc' }
    });
    return { success: true, data: repos };
  });
}

