import { PrismaClient } from '@prisma/client';
import { config } from '../config';

const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

export const prisma = globalForPrisma.prisma || new PrismaClient({
  log: config.NODE_ENV === 'development' ? ['query', 'error', 'warn'] : ['error'],
  datasources: {
    db: {
      url: config.DATABASE_URL
    }
  }
});

if (config.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;

// Helper functions for common operations
export async function createAuditLog(data: {
  userId?: string;
  action: string;
  resource: string;
  resourceId?: string;
  metadata?: Record<string, unknown>;
  ip?: string;
  userAgent?: string;
}) {
  return prisma.auditLog.create({ data });
}

export async function getUserWithSettings(userId: string) {
  return prisma.user.findUnique({
    where: { id: userId },
    include: { settings: true }
  });
}

export async function getUserSettings(userId: string) {
  return prisma.settings.findUnique({ where: { userId } });
}

export async function upsertUserSettings(userId: string, data: Record<string, unknown>) {
  return prisma.settings.upsert({
    where: { userId },
    create: { userId, ...data } as any,
    update: data
  });
}

import { AIProvider, AIProviderConfig, AIRequest, AIResponse, AIModel, DockerfileFixResponse, KubernetesFixResponse, JenkinsfileFixResponse, LogInvestigationResponse, DependencyFixResponse, GitHubCodeFixResponse } from './types';
import { BaseAIProvider } from './base';
import { AppsScriptProvider } from './providers/apps-script';
import { config } from '../config';
import { prisma } from '../database';

export class AIService {
  private providers: Map<string, AIProvider> = new Map();
  private defaultProvider: string = 'apps_script';
  private initialized = false;

  async initialize(): Promise<void> {
    if (this.initialized) return;

    // Load provider configs from database
    const settings = await prisma.settings.findFirst();
    const providerType = settings?.aiProvider || 'apps_script';

    // Initialize Apps Script provider (default)
    const appsScriptProvider = new AppsScriptProvider();
    await appsScriptProvider.initialize({
      endpoint: settings?.aiAppsScriptUrl || config.AI_APPS_SCRIPT_URL,
      apiKey: settings?.aiOpenaiKey // Reusing field for API key
    });
    this.providers.set('apps_script', appsScriptProvider);

    // Initialize other providers if configured
    if (settings?.aiOpenaiKey) {
      // OpenAI provider would be initialized here
    }

    this.defaultProvider = providerType;
    this.initialized = true;
  }

  getProvider(type?: string): AIProvider {
    const providerType = type || this.defaultProvider;
    const provider = this.providers.get(providerType);
    if (!provider) {
      throw new Error(`AI provider '${providerType}' not initialized`);
    }
    return provider;
  }

  getAvailableProviders(): AIProviderConfig[] {
    return Array.from(this.providers.values()).map(p => ({
      type: p.type,
      name: p.name,
      enabled: true,
      config: {},
      models: p.getModels(),
      defaultModel: p.getModels()[0]?.id || ''
    }));
  }

  setDefaultProvider(type: string): void {
    if (!this.providers.has(type)) {
      throw new Error(`Provider '${type}' not available`);
    }
    this.defaultProvider = type;
  }

  // Generic completion
  async complete(request: AIRequest, providerType?: string): Promise<AIResponse> {
    const provider = this.getProvider(providerType);
    return provider.complete(request);
  }

  async stream(request: AIRequest, onChunk: (chunk: string) => void, providerType?: string): Promise<AIResponse> {
    const provider = this.getProvider(providerType);
    return provider.stream(request, onChunk);
  }

  // Specialized methods for each feature
  async fixDockerfile(dockerfile: string, issues: any[], options?: any): Promise<DockerfileFixResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.fixDockerfile(dockerfile, issues, options);
  }

  async fixKubernetes(yaml: string, issues: any[], options?: any): Promise<KubernetesFixResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.fixKubernetes(yaml, issues, options);
  }

  async fixJenkinsfile(jenkinsfile: string, issues: any[], options?: any): Promise<JenkinsfileFixResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.fixJenkinsfile(jenkinsfile, issues, options);
  }

  async investigateLogs(question: string, logEntries: any[], context?: any): Promise<LogInvestigationResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.investigateLogs(question, logEntries, context);
  }

  async fixDependency(pkg: string, currentVersion: string, targetVersion: string, vulnerabilities: any[], manifestContent: string): Promise<DependencyFixResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.fixDependency(pkg, currentVersion, targetVersion, vulnerabilities, manifestContent);
  }

  async fixGitHubCode(finding: any, fileContent: string, surroundingContext: string): Promise<GitHubCodeFixResponse> {
    const provider = this.getProvider() as AppsScriptProvider;
    return provider.fixGitHubCode(finding, fileContent, surroundingContext);
  }

  async healthCheck(): Promise<Record<string, boolean>> {
    const results: Record<string, boolean> = {};
    for (const [type, provider] of this.providers) {
      results[type] = await provider.healthCheck();
    }
    return results;
  }
}

export const aiService = new AIService();

export function getAIProvider(): AIProvider {
  return aiService.getProvider();
}

import { prisma } from '../database';
import { FastifyRequest } from 'fastify';

export interface AuditLogEntry {
  action: string;
  resource: string;
  resourceId?: string;
  userId: string;
  metadata?: Record<string, any>;
  ip?: string;
  userAgent?: string;
}

export async function auditLog(
  request: FastifyRequest,
  action: string,
  resource: string,
  resourceId?: string,
  metadata?: Record<string, any>
): Promise<void> {
  try {
    const ip = request.ip || request.headers['x-forwarded-for'] as string || 'unknown';
    const userAgent = request.headers['user-agent'] || 'unknown';
    const userId = (request as any).user?.userId || 'anonymous';

    await prisma.auditLog.create({
      data: {
        action,
        resource,
        resourceId,
        userId,
        metadata,
        ip,
        userAgent
      }
    });
  } catch (error) {
    // Don't fail the request if audit logging fails
    console.error('Audit log failed:', error);
  }
}

export async function getAuditLogs(
  userId: string,
  options: {
    page?: number;
    pageSize?: number;
    action?: string;
    resource?: string;
    startDate?: Date;
    endDate?: Date;
  } = {}
) {
  const { page = 1, pageSize = 50, action, resource, startDate, endDate } = options;

  const where: any = { userId };
  if (action) where.action = action;
  if (resource) where.resource = resource;
  if (startDate || endDate) {
    where.createdAt = {};
    if (startDate) where.createdAt.gte = startDate;
    if (endDate) where.createdAt.lte = endDate;
  }

  const [logs, total] = await Promise.all([
    prisma.auditLog.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      take: pageSize,
      skip: (page - 1) * pageSize
    }),
    prisma.auditLog.count({ where })
  ]);

  return {
    logs,
    total,
    totalPages: Math.ceil(total / pageSize),
    page,
    pageSize
  };
}

import { execFileSync } from 'child_process';
import { writeFileSync, rmSync, mkdtempSync } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { PrismaClient } from '@prisma/client';
import { Job } from 'bullmq';

const prisma = new PrismaClient();

export interface JenkinsfileScanResult {
  summary: {
    totalFindings: number;
    critical: number;
    high: number;
    medium: number;
    low: number;
    info: number;
  };
  findings: JenkinsfileFinding[];
}

export interface JenkinsfileFinding {
  id: string;
  type: 'security' | 'best-practice' | 'performance' | 'reliability' | 'maintainability' | 'secret';
  severity: 'critical' | 'high' | 'medium' | 'low' | 'info';
  title: string;
  description: string;
  file: string;
  line: number;
  column?: number;
  ruleId?: string;
  cwe?: string;
  references?: string[];
  fixable?: boolean;
}

export interface ScanProgress {
  progress: number;
  currentStep: string;
}

async function updateProgress(job: Job, progress: ScanProgress): Promise<void> {
  await job.updateProgress(progress);
}

function runCommand(command: string, args: string[], options: { cwd?: string; timeout?: number } = {}): string {
  try {
    const result = execFileSync(command, args, {
      cwd: options.cwd,
      timeout: options.timeout || 300000,
      encoding: 'utf-8',
      maxBuffer: 10 * 1024 * 1024
    });
    return result;
  } catch (error: any) {
    if (error.stdout) return error.stdout;
    if (error.stderr) return error.stderr;
    throw error;
  }
}

function parseSemgrepOutput(output: string, file: string): JenkinsfileFinding[] {
  const findings: JenkinsfileFinding[] = [];

  try {
    const data = JSON.parse(output);

    if (data.results) {
      for (const result of data.results) {
        const extra = result.extra || {};
        const metadata = extra.metadata || {};

        findings.push({
          id: `semgrep-${result.check_id || 'unknown'}-${result.start.line}`,
          type: mapSemgrepType(metadata.category || 'security'),
          severity: mapSemgrepSeverity(extra.severity || 'INFO'),
          title: extra.message || result.check_id || 'Semgrep finding',
          description: extra.message || 'No description available',
          file,
          line: result.start.line,
          column: result.start.col,
          ruleId: result.check_id,
          cwe: metadata.cwe?.[0],
          references: metadata.references,
          fixable: !!extra.fix
        });
      }
    }
  } catch {
    // Ignore parse errors
  }

  return findings;
}

function parseGitleaksOutput(output: string, file: string): JenkinsfileFinding[] {
  const findings: JenkinsfileFinding[] = [];

  try {
    const data = JSON.parse(output);

    for (const leak of data) {
      findings.push({
        id: `gitleaks-${leak.RuleID}-${leak.StartLine}`,
        type: 'secret',
        severity: mapGitleaksSeverity(leak.RuleID),
        title: `Secret detected: ${leak.RuleID}`,
        description: `Potential secret found: ${leak.Description}`,
        file,
        line: leak.StartLine,
        column: leak.StartColumn,
        ruleId: leak.RuleID,
        references: [`https://github.com/gitleaks/gitleaks/blob/master/config/gitleaks.toml#L${leak.RuleID}`]
      });
    }
  } catch {
    // Ignore parse errors
  }

  return findings;
}

function mapSemgrepType(category: string): JenkinsfileFinding['type'] {
  const c = category?.toLowerCase() || '';
  if (c.includes('secret')) return 'secret';
  if (c.includes('security')) return 'security';
  if (c.includes('performance')) return 'performance';
  if (c.includes('reliability')) return 'reliability';
  if (c.includes('maintainability')) return 'maintainability';
  return 'best-practice';
}

function mapSemgrepSeverity(severity: string): 'critical' | 'high' | 'medium' | 'low' | 'info' {
  const s = severity?.toUpperCase() || 'INFO';
  if (s === 'ERROR' || s === 'CRITICAL') return 'critical';
  if (s === 'HIGH') return 'high';
  if (s === 'MEDIUM') return 'medium';
  if (s === 'LOW') return 'low';
  return 'info';
}

function mapGitleaksSeverity(ruleId: string): 'critical' | 'high' | 'medium' | 'low' | 'info' {
  const r = ruleId?.toLowerCase() || '';
  if (r.includes('aws') || r.includes('gcp') || r.includes('azure') || r.includes('private-key')) return 'critical';
  if (r.includes('token') || r.includes('password') || r.includes('secret') || r.includes('api-key')) return 'high';
  return 'medium';
}

function deduplicateFindings(findings: JenkinsfileFinding[]): JenkinsfileFinding[] {
  const seen = new Set<string>();
  return findings.filter(f => {
    const key = `${f.ruleId}:${f.file}:${f.line}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

export async function scanJenkinsfile(
  jenkinsfile: string,
  job: Job,
  scanId: string
): Promise<JenkinsfileScanResult> {
  const tempDir = mkdtempSync(join(tmpdir(), 'jenkins-scan-'));
  const jenkinsfilePath = join(tempDir, 'Jenkinsfile');

  try {
    await updateProgress(job, { progress: 10, currentStep: 'Writing Jenkinsfile to temp directory' });
    writeFileSync(jenkinsfilePath, jenkinsfile);

    const allFindings: JenkinsfileFinding[] = [];

    // Run Semgrep for security and best practice rules
    await updateProgress(job, { progress: 25, currentStep: 'Running Semgrep security scan' });
    try {
      const semgrepOutput = runCommand('semgrep', [
        'scan',
        '--config', 'auto',
        '--json',
        '--quiet',
        tempDir
      ], { cwd: tempDir, timeout: 300000 });
      const semgrepFindings = parseSemgrepOutput(semgrepOutput, 'Jenkinsfile');
      allFindings.push(...semgrepFindings);
    } catch (error) {
      console.warn('Semgrep scan failed:', error);
    }

    // Run Gitleaks for secret detection
    await updateProgress(job, { progress: 50, currentStep: 'Running Gitleaks secret scan' });
    try {
      const gitleaksOutput = runCommand('gitleaks', [
        'detect',
        '--source', tempDir,
        '--report-format', 'json',
        '--verbose'
      ], { cwd: tempDir, timeout: 120000 });
      const gitleaksFindings = parseGitleaksOutput(gitleaksOutput, 'Jenkinsfile');
      allFindings.push(...gitleaksFindings);
    } catch (error) {
      console.warn('Gitleaks scan failed:', error);
    }

    // Custom Jenkinsfile pattern checks
    await updateProgress(job, { progress: 70, currentStep: 'Running custom Jenkinsfile checks' });
    const customFindings = runCustomJenkinsfileChecks(jenkinsfile);
    allFindings.push(...customFindings);

    await updateProgress(job, { progress: 90, currentStep: 'Consolidating findings' });

    const uniqueFindings = deduplicateFindings(allFindings);

    const summary = {
      totalFindings: uniqueFindings.length,
      critical: uniqueFindings.filter(f => f.severity === 'critical').length,
      high: uniqueFindings.filter(f => f.severity === 'high').length,
      medium: uniqueFindings.filter(f => f.severity === 'medium').length,
      low: uniqueFindings.filter(f => f.severity === 'low').length,
      info: uniqueFindings.filter(f => f.severity === 'info').length
    };

    if (scanId) {
      await prisma.finding.createMany({
        data: uniqueFindings.map(f => ({
          scanId,
          type: f.type,
          severity: f.severity,
          title: f.title,
          description: f.description,
          file: f.file,
          line: f.line,
          column: f.column,
          ruleId: f.ruleId,
          cwe: f.cwe,
          cvss: undefined,
          references: f.references,
          fixable: f.fixable,
          status: 'open'
        }))
      });
    }

    await updateProgress(job, { progress: 100, currentStep: 'Scan completed' });

    return { summary, findings: uniqueFindings };
  } finally {
    try {
      rmSync(tempDir, { recursive: true, force: true });
    } catch {
      // Ignore cleanup errors
    }
  }
}

function runCustomJenkinsfileChecks(jenkinsfile: string): JenkinsfileFinding[] {
  const findings: JenkinsfileFinding[] = [];
  const lines = jenkinsfile.split('\n');

  // Check for hardcoded credentials
  const credentialPatterns = [
    { pattern: /password\s*[:=]\s*['"][^'"]+['"]/gi, ruleId: 'JENKINS-HARDCODED-PASSWORD', title: 'Hardcoded password', severity: 'critical' as const, type: 'secret' as const },
    { pattern: /token\s*[:=]\s*['"][^'"]+['"]/gi, ruleId: 'JENKINS-HARDCODED-TOKEN', title: 'Hardcoded token', severity: 'critical' as const, type: 'secret' as const },
    { pattern: /api[_-]?key\s*[:=]\s*['"][^'"]+['"]/gi, ruleId: 'JENKINS-HARDCODED-API-KEY', title: 'Hardcoded API key', severity: 'critical' as const, type: 'secret' as const },
    { pattern: /secret\s*[:=]\s*['"][^'"]+['"]/gi, ruleId: 'JENKINS-HARDCODED-SECRET', title: 'Hardcoded secret', severity: 'critical' as const, type: 'secret' as const },
  ];

  // Check for insecure practices
  const insecurePatterns = [
    { pattern: /sh\s+['"]curl\s+.*\|\s*sh['"]/gi, ruleId: 'JENKINS-CURL-PIPE-SH', title: 'Piping curl to shell', severity: 'high' as const, type: 'security' as const },
    { pattern: /sh\s+['"]wget\s+.*\|\s*sh['"]/gi, ruleId: 'JENKINS-WGET-PIPE-SH', title: 'Piping wget to shell', severity: 'high' as const, type: 'security' as const },
    { pattern: /docker\s+login\s+-p\s+\$\w+/gi, ruleId: 'JENKINS-DOCKER-LOGIN-PLAIN', title: 'Docker login with plain password', severity: 'high' as const, type: 'security' as const },
    { pattern: /withCredentials.*\$\w+/gi, ruleId: 'JENKINS-CREDENTIALS-IN-SCRIPT', title: 'Credentials used in shell script', severity: 'medium' as const, type: 'security' as const },
    { pattern: /agent\s+any/gi, ruleId: 'JENKINS-AGENT-ANY', title: 'Using "agent any" - consider specific labels', severity: 'low' as const, type: 'best-practice' as const },
    { pattern: /disableConcurrentBuilds\s*\(\s*\)/gi, ruleId: 'JENKINS-NO-CONCURRENT', title: 'Concurrent builds disabled', severity: 'info' as const, type: 'best-practice' as const },
    { pattern: /timeout\s*\(\s*time:\s*0\s*\)/gi, ruleId: 'JENKINS-NO-TIMEOUT', title: 'No timeout set for build', severity: 'medium' as const, type: 'reliability' as const },
  ];

  // Check for deprecated patterns
  const deprecatedPatterns = [
    { pattern: /node\s*\(/gi, ruleId: 'JENKINS-DEPRECATED-NODE', title: 'Using deprecated "node" syntax', severity: 'low' as const, type: 'maintainability' as const },
    { pattern: /stage\s*\(/gi, ruleId: 'JENKINS-DEPRECATED-STAGE', title: 'Using deprecated stage syntax', severity: 'low' as const, type: 'maintainability' as const },
  ];

  // Check for best practices
  const bestPracticePatterns = [
    { pattern: /pipeline\s*\{/, ruleId: 'JENKINS-PIPELINE-SYNTAX', title: 'Using declarative pipeline syntax', severity: 'info' as const, type: 'best-practice' as const, positive: true },
    { pattern: /options\s*\{/, ruleId: 'JENKINS-OPTIONS-BLOCK', title: 'Using options block', severity: 'info' as const, type: 'best-practice' as const, positive: true },
    { pattern: /environment\s*\{/, ruleId: 'JENKINS-ENVIRONMENT-BLOCK', title: 'Using environment block', severity: 'info' as const, type: 'best-practice' as const, positive: true },
    { pattern: /post\s*\{/, ruleId: 'JENKINS-POST-BLOCK', title: 'Using post block for cleanup', severity: 'info' as const, type: 'best-practice' as const, positive: true },
    { pattern: /tools\s*\{/, ruleId: 'JENKINS-TOOLS-BLOCK', title: 'Using tools block', severity: 'info' as const, type: 'best-practice' as const, positive: true },
  ];

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const lineNum = i + 1;

    // Check credential patterns
    for (const check of credentialPatterns) {
      const matches = line.matchAll(check.pattern);
      for (const match of matches) {
        findings.push({
          id: `${check.ruleId}-${lineNum}`,
          type: check.type,
          severity: check.severity,
          title: check.title,
          description: `Found ${check.title.toLowerCase()} in Jenkinsfile`,
          file: 'Jenkinsfile',
          line: lineNum,
          column: match.index,
          ruleId: check.ruleId,
          references: ['https://www.jenkins.io/doc/book/pipeline/best-practices/']
        });
      }
    }

    // Check insecure patterns
    for (const check of insecurePatterns) {
      const matches = line.matchAll(check.pattern);
      for (const match of matches) {
        findings.push({
          id: `${check.ruleId}-${lineNum}`,
          type: check.type,
          severity: check.severity,
          title: check.title,
          description: check.title,
          file: 'Jenkinsfile',
          line: lineNum,
          column: match.index,
          ruleId: check.ruleId,
          references: ['https://www.jenkins.io/doc/book/pipeline/best-practices/']
        });
      }
    }

    // Check deprecated patterns
    for (const check of deprecatedPatterns) {
      const matches = line.matchAll(check.pattern);
      for (const match of matches) {
        findings.push({
          id: `${check.ruleId}-${lineNum}`,
          type: check.type,
          severity: check.severity,
          title: check.title,
          description: check.title,
          file: 'Jenkinsfile',
          line: lineNum,
          column: match.index,
          ruleId: check.ruleId,
          references: ['https://www.jenkins.io/doc/book/pipeline/syntax/']
        });
      }
    }

    // Check best practices (positive findings)
    for (const check of bestPracticePatterns) {
      if (check.pattern.test(line)) {
        findings.push({
          id: `${check.ruleId}-${lineNum}`,
          type: check.type,
          severity: check.severity,
          title: check.title,
          description: check.title,
          file: 'Jenkinsfile',
          line: lineNum,
          ruleId: check.ruleId,
          references: ['https://www.jenkins.io/doc/book/pipeline/best-practices/']
        });
      }
    }
  }

  return findings;
}

export async function fixJenkinsfile(
  jenkinsfile: string,
  findings: JenkinsfileFinding[],
  job: Job
): Promise<{ fixedJenkinsfile: string; changes: any[] }> {
  await updateProgress(job, { progress: 10, currentStep: 'Analyzing Jenkinsfile issues' });

  let fixedJenkinsfile = jenkinsfile;
  const changes: any[] = [];

  // Sort findings by severity
  const sortedFindings = [...findings].sort((a, b) => {
    const severityOrder = { critical: 0, high: 1, medium: 2, low: 3, info: 4 };
    return severityOrder[a.severity] - severityOrder[b.severity];
  });

  // Basic fixes for common issues
  for (const finding of sortedFindings) {
    if (finding.ruleId) {
      // This is a simplified version - real implementation would use AI
      changes.push({
        findingId: finding.id,
        type: 'configuration_fix',
        description: `Fix applied for ${finding.title}`,
        ruleId: finding.ruleId
      });
    }
  }

  await updateProgress(job, { progress: 100, currentStep: 'Fix generation completed' });

  return { fixedJenkinsfile, changes };
}

export async function generateJenkinsfile(
  spec: any,
  job: Job
): Promise<{ jenkinsfile: string }> {
  await updateProgress(job, { progress: 10, currentStep: 'Generating Jenkinsfile' });

  const {
    name = 'my-pipeline',
    agent = 'any',
    stages = [],
    environment = {},
    tools = {},
    options = {},
    triggers = {},
    post = {}
  } = spec;

  let jenkinsfile = `pipeline {
  agent ${typeof agent === 'string' ? agent : JSON.stringify(agent, null, 2).replace(/\n/g, '\n  ')}
`;

  if (Object.keys(environment).length > 0) {
    jenkinsfile += `  environment {
`;
    for (const [key, value] of Object.entries(environment)) {
      jenkinsfile += `    ${key} = '${value}'
`;
    }
    jenkinsfile += `  }
`;
  }

  if (Object.keys(tools).length > 0) {
    jenkinsfile += `  tools {
`;
    for (const [key, value] of Object.entries(tools)) {
      jenkinsfile += `    ${key} '${value}'
`;
    }
    jenkinsfile += `  }
`;
  }

  if (Object.keys(options).length > 0) {
    jenkinsfile += `  options {
`;
    for (const [key, value] of Object.entries(options)) {
      jenkinsfile += `    ${key}(${typeof value === 'string' ? `'${value}'` : value})
`;
    }
    jenkinsfile += `  }
`;
  }

  if (Object.keys(triggers).length > 0) {
    jenkinsfile += `  triggers {
`;
    for (const [key, value] of Object.entries(triggers)) {
      jenkinsfile += `    ${key}(${typeof value === 'string' ? `'${value}'` : value})
`;
    }
    jenkinsfile += `  }
`;
  }

  jenkinsfile += `  stages {
`;
  for (const stage of stages) {
    jenkinsfile += `    stage('${stage.name}') {
`;
    if (stage.agent) {
      jenkinsfile += `      agent ${typeof stage.agent === 'string' ? stage.agent : JSON.stringify(stage.agent, null, 6).replace(/\n/g, '\n      ')}
`;
    }
    if (stage.environment) {
      jenkinsfile += `      environment {
`;
      for (const [key, value] of Object.entries(stage.environment)) {
        jenkinsfile += `        ${key} = '${value}'
`;
      }
      jenkinsfile += `      }
`;
    }
    if (stage.steps) {
      jenkinsfile += `      steps {
`;
      for (const step of stage.steps) {
        if (typeof step === 'string') {
          jenkinsfile += `        ${step}
`;
        } else if (step.sh) {
          jenkinsfile += `        sh '''
${step.sh}
'''
`;
        } else if (step.echo) {
          jenkinsfile += `        echo '${step.echo}'
`;
        }
      }
      jenkinsfile += `      }
`;
    }
    jenkinsfile += `    }
`;
  }
  jenkinsfile += `  }
`;

  if (Object.keys(post).length > 0) {
    jenkinsfile += `  post {
`;
    for (const [condition, actions] of Object.entries(post)) {
      jenkinsfile += `    ${condition} {
`;
      for (const action of (actions as any[])) {
        if (action.echo) {
          jenkinsfile += `      echo '${action.echo}'
`;
        } else if (action.sh) {
          jenkinsfile += `      sh '''
${action.sh}
'''
`;
        }
      }
      jenkinsfile += `    }
`;
    }
    jenkinsfile += `  }
`;
  }

  jenkinsfile += `}`;

  await updateProgress(job, { progress: 100, currentStep: 'Generation completed' });

  return { jenkinsfile };
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const connectSchema = z.object({
  token: z.string().min(1),
  org: z.string().optional()
});

const scanSchema = z.object({
  repoUrl: z.string().url(),
  branch: z.string().optional().default('main'),
  scanTypes: z.array(z.enum(['vulnerabilities', 'secrets', 'dependencies', 'code'])).optional().default(['vulnerabilities', 'secrets', 'dependencies', 'code'])
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findingId: z.string(),
  branch: z.string().optional().default('main'),
  fixType: z.enum(['patch', 'upgrade', 'config'])
});

const createPrSchema = z.object({
  repoId: z.string(),
  branch: z.string(),
  title: z.string(),
  body: z.string().optional(),
  changes: z.array(z.object({
    file: z.string(),
    content: z.string()
  }))
});

export async function githubRoutes(app: FastifyInstance) {
  // Connect GitHub
  app.post('/connect', {
    preHandler: [app.authenticate],
    schema: { body: connectSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { token, org } = request.body;

    // In production, validate token with GitHub API and fetch user/org info
    // For now, create a mock repository entry
    const repo = await prisma.gitHubRepository.create({
      data: {
        userId,
        githubId: Date.now(),
        name: org || 'connected-repo',
        fullName: `${org || 'user'}/connected-repo`,
        url: `https://github.com/${org || 'user'}/connected-repo`,
        cloneUrl: `https://github.com/${org || 'user'}/connected-repo.git`,
        defaultBranch: 'main'
      }
    });

    await auditLog(request, 'GITHUB_CONNECTED', 'github_repo', repo.id, { org });

    return { success: true, data: { connected: true, repo } };
  });

  // Scan GitHub repository
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { repoUrl, branch, scanTypes } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'github_repo',
        status: 'pending',
        targetType: 'github_repo',
        targetValue: repoUrl,
        targetMeta: { branch, scanTypes },
        userId
      }
    });

    // Get GitHub token from settings
    const settings = await prisma.settings.findUnique({ where: { userId } });
    const token = settings?.githubToken || settings?.githubPrivateKey;

    const job = await createJob('github_repo_scan', {
      scanId: scan.id,
      repoUrl,
      branch,
      scanTypes,
      token
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'GITHUB_SCAN_STARTED', 'scan', scan.id, { repoUrl, branch, scanTypes });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Get scan status
  app.get('/scan/:id/status', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    // If scan has a job, get job status
    let jobStatus = 'pending';
    let progress = 0;
    if (scan.jobId) {
      const job = await prisma.job.findUnique({ where: { id: scan.jobId } });
      if (job) {
        jobStatus = job.status;
        progress = job.progress;
      }
    }

    return { success: true, data: { status: jobStatus, progress } };
  });

  // Get scan results
  app.get('/scan/:id/results', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // Fix finding (code fix)
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findingId, branch, fixType } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: { where: { id: findingId } } }
    });

    if (!scan || scan.userId !== userId || scan.findings.length === 0) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Finding not found', statusCode: 404 } });
    }

    const finding = scan.findings[0];
    const job = await createJob('github_code_fix', {
      scanId,
      findingId,
      branch,
      fixType,
      finding: {
        id: finding.id,
        type: finding.type,
        severity: finding.severity,
        title: finding.title,
        description: finding.description,
        file: finding.file,
        line: finding.line,
        code: finding.code,
        ruleId: finding.ruleId
      }
    }, userId);

    await auditLog(request, 'GITHUB_FIX_STARTED', 'finding', findingId);
    return { success: true, data: { jobId: job.id } };
  });

  // Create PR
  app.post('/create-pr', {
    preHandler: [app.authenticate],
    schema: { body: createPrSchema }
  }, async (request, reply) => {
    // In production, use GitHub API to create PR
    const { repoId, branch, title, body, changes } = request.body;

    await auditLog(request, 'GITHUB_PR_CREATED', 'github_repo', repoId, { branch, title });

    return {
      success: true,
      data: {
        prUrl: `https://github.com/repo/pull/123`,
        prNumber: 123
      }
    };
  });

  // List connected repos
  app.get('/repos', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const repos = await prisma.gitHubRepository.findMany({
      where: { userId },
      orderBy: { connectedAt: 'desc' }
    });
    return { success: true, data: repos };
  });
}

