import { config } from '../config';
import { prisma } from '../database';
import { logger } from './logger';
import { FastifyRequest, FastifyReply } from 'fastify';

export interface JWTPayload {
  sub: string;
  email: string;
  role: string;
  iat: number;
  exp: number;
}

export async function hashPassword(password: string): Promise<string> {
  const bcrypt = await import('bcryptjs');
  return bcrypt.hash(password, config.BCRYPT_ROUNDS);
}

export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  const bcrypt = await import('bcryptjs');
  return bcrypt.compare(password, hash);
}

export async function verifyToken(token: string): Promise<JWTPayload> {
  const jwt = await import('jsonwebtoken');
  return jwt.verify(token, config.JWT_SECRET) as JWTPayload;
}

export function generateTokens(user: { id: string; email: string; role: string }): { accessToken: string; refreshToken: string } {
  const jwt = require('jsonwebtoken');
  const accessToken = jwt.sign(
    { sub: user.id, email: user.email, role: user.role },
    config.JWT_SECRET,
    { expiresIn: config.JWT_EXPIRES_IN }
  );
  const refreshToken = jwt.sign(
    { sub: user.id, type: 'refresh' },
    config.JWT_SECRET,
    { expiresIn: config.JWT_REFRESH_EXPIRES_IN }
  );
  return { accessToken, refreshToken };
}

export async function authenticateRequest(request: FastifyRequest): Promise<JWTPayload | null> {
  try {
    const authHeader = request.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return null;
    }
    const token = authHeader.slice(7);
    return await verifyToken(token);
  } catch {
    return null;
  }
}

export async function getCurrentUser(request: FastifyRequest) {
  const payload = await authenticateRequest(request);
  if (!payload) return null;

  const user = await prisma.user.findUnique({
    where: { id: payload.sub },
    select: {
      id: true,
      email: true,
      name: true,
      avatarUrl: true,
      role: true,
      theme: true,
      sidebarCollapsed: true,
      language: true,
      emailNotifications: true,
      inAppNotifications: true,
      notifyScanComplete: true,
      notifyScanFailed: true,
      notifyVulnFound: true,
      notifyJobChange: true,
      createdAt: true,
      lastLoginAt: true
    }
  });

  return user;
}

export function requireAuth(request: FastifyRequest, reply: FastifyReply) {
  return async () => {
    const payload = await authenticateRequest(request);
    if (!payload) {
      reply.code(401).send({
        success: false,
        error: { code: 'UNAUTHORIZED', message: 'Authentication required', statusCode: 401 }
      });
      return null;
    }
    return payload;
  };
}

export function requireRole(...roles: string[]) {
  return async (request: FastifyRequest, reply: FastifyReply) => {
    const payload = await authenticateRequest(request);
    if (!payload || !roles.includes(payload.role)) {
      reply.code(403).send({
        success: false,
        error: { code: 'FORBIDDEN', message: 'Insufficient permissions', statusCode: 403 }
      });
      return null;
    }
    return payload;
  };
}

