import { z } from 'zod';
import { prisma } from '../../shared/database';
import { getAIProvider } from '../../shared/ai';
import { auditLog } from '../../shared/utils/audit';

const askSchema = z.object({
  prompt: z.string().min(1).max(10000),
  context: z.string().optional(),
  model: z.string().optional(),
  temperature: z.number().min(0).max(2).optional(),
  maxTokens: z.number().optional(),
  systemPrompt: z.string().optional()
});

const fixSchema = z.object({
  code: z.string().min(1),
  language: z.string().optional(),
  finding: z.object({
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    ruleId: z.string().optional()
  }),
  context: z.string().optional()
});

const explainSchema = z.object({
  code: z.string().min(1),
  language: z.string().optional(),
  focus: z.string().optional()
});

export async function aiRoutes(app: FastifyInstance) {
  // Ask AI
  app.post('/ask', {
    preHandler: [app.authenticate],
    schema: { body: askSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { prompt, context, model, temperature, maxTokens, systemPrompt } = request.body;

    try {
      const provider = getAIProvider();
      const response = await provider.ask({
        prompt,
        context,
        model,
        temperature,
        maxTokens,
        systemPrompt
      });

      await auditLog(request, 'AI_ASK', 'ai', undefined, { promptLength: prompt.length, model: model || 'default' });

      return { success: true, data: response };
    } catch (error: any) {
      return reply.code(500).send({ success: false, error: { code: 'AI_ERROR', message: error.message, statusCode: 500 } });
    }
  });

  // Generate fix for finding
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { code, language, finding, context } = request.body;

    try {
      const provider = getAIProvider();
      const fixPrompt = `You are a security expert. Generate a fix for the following security issue.

Finding:
- Type: ${finding.type}
- Severity: ${finding.severity}
- Title: ${finding.title}
- Description: ${finding.description}
${finding.file ? `- File: ${finding.file}` : ''}
${finding.line ? `- Line: ${finding.line}` : ''}
${finding.ruleId ? `- Rule: ${finding.ruleId}` : ''}

Code to fix:
\`\`\`${language || ''}
${code}
\`\`\`

${context ? `Additional context: ${context}` : ''}

Provide a JSON response with:
{
  "explanation": "Brief explanation of the fix",
  "patch": "Unified diff format patch",
  "confidence": 0-100,
  "steps": ["Step 1", "Step 2"]
}`;

      const response = await provider.ask({
        prompt: fixPrompt,
        systemPrompt: 'You are a security expert that generates safe, minimal fixes for security vulnerabilities. Always respond with valid JSON.',
        temperature: 0.2,
        maxTokens: 4096
      });

      await auditLog(request, 'AI_FIX_GENERATED', 'ai', undefined, { findingType: finding.type, severity: finding.severity });

      return { success: true, data: response };
    } catch (error: any) {
      return reply.code(500).send({ success: false, error: { code: 'AI_ERROR', message: error.message, statusCode: 500 } });
    }
  });

  // Explain code
  app.post('/explain', {
    preHandler: [app.authenticate],
    schema: { body: explainSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { code, language, focus } = request.body;

    try {
      const provider = getAIProvider();
      const explainPrompt = `Explain the following ${language || 'code'} code${focus ? ` with focus on: ${focus}` : ''}:

\`\`\`${language || ''}
${code}
\`\`\`

Provide a clear, concise explanation covering:
1. What the code does
2. Security implications (if any)
3. Potential improvements`;

      const response = await provider.ask({
        prompt: explainPrompt,
        temperature: 0.3,
        maxTokens: 2048
      });

      await auditLog(request, 'AI_EXPLAIN', 'ai', undefined, { language: language || 'unknown' });

      return { success: true, data: response };
    } catch (error: any) {
      return reply.code(500).send({ success: false, error: { code: 'AI_ERROR', message: error.message, statusCode: 500 } });
    }
  });

  // Get available models
  app.get('/models', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const provider = getAIProvider();
    const models = await provider.getModels?.() || ['default'];
    return { success: true, data: models };
  });

  // Test AI connection
  app.get('/test', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    try {
      const provider = getAIProvider();
      const response = await provider.ask({ prompt: 'Say "OK" if you can hear me.', maxTokens: 10 });
      return { success: true, data: { connected: true, response } };
    } catch (error: any) {
      return { success: false, data: { connected: false, error: error.message } };
    }
  });
}

