import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { hashPassword, verifyPassword, generateAccessToken, generateRefreshToken, verifyRefreshToken } from '../../shared/utils/auth';
import { auditLog } from '../../shared/utils/audit';

const loginSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  rememberMe: z.boolean().optional()
});

const registerSchema = z.object({
  name: z.string().min(2).max(100),
  email: z.string().email(),
  password: z.string().min(8).max(128)
});

const refreshSchema = z.object({
  refreshToken: z.string()
});

const changePasswordSchema = z.object({
  currentPassword: z.string(),
  newPassword: z.string().min(8).max(128)
});

export async function authRoutes(app: FastifyInstance) {
  // Login
  app.post('/login', {
    schema: {
      body: loginSchema,
      response: {
        200: z.object({
          success: z.boolean(),
          data: z.object({
            user: z.object({
              id: z.string(),
              email: z.string(),
              name: z.string(),
              avatarUrl: z.string().nullable(),
              role: z.string()
            }),
            accessToken: z.string(),
            refreshToken: z.string()
          })
        })
      }
    }
  }, async (request, reply) => {
    const { email, password, rememberMe } = request.body;

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) {
      await auditLog(request, 'LOGIN_FAILED', 'user', undefined, { email, reason: 'user_not_found' });
      return reply.code(401).send({ success: false, error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password', statusCode: 401 } });
    }

    const valid = await verifyPassword(password, user.passwordHash);
    if (!valid) {
      await auditLog(request, 'LOGIN_FAILED', 'user', user.id, { reason: 'invalid_password' });
      return reply.code(401).send({ success: false, error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password', statusCode: 401 } });
    }

    const accessToken = generateAccessToken(app, { userId: user.id, email: user.email, role: user.role });
    const refreshToken = generateRefreshToken(app, { userId: user.id, email: user.email }, rememberMe);

    await prisma.user.update({
      where: { id: user.id },
      data: { lastLoginAt: new Date() }
    });

    await auditLog(request, 'LOGIN_SUCCESS', 'user', user.id, { rememberMe });

    return {
      success: true,
      data: {
        user: { id: user.id, email: user.email, name: user.name, avatarUrl: user.avatarUrl, role: user.role },
        accessToken,
        refreshToken
      }
    };
  });

  // Register
  app.post('/register', {
    schema: {
      body: registerSchema,
      response: {
        201: z.object({
          success: z.boolean(),
          data: z.object({
            user: z.object({
              id: z.string(),
              email: z.string(),
              name: z.string(),
              avatarUrl: z.string().nullable(),
              role: z.string()
            }),
            accessToken: z.string(),
            refreshToken: z.string()
          })
        })
      }
    }
  }, async (request, reply) => {
    const { name, email, password } = request.body;

    const existing = await prisma.user.findUnique({ where: { email } });
    if (existing) {
      return reply.code(409).send({ success: false, error: { code: 'EMAIL_EXISTS', message: 'Email already registered', statusCode: 409 } });
    }

    const passwordHash = await hashPassword(password);
    const user = await prisma.user.create({
      data: { name, email, passwordHash },
      select: { id: true, email: true, name: true, avatarUrl: true, role: true }
    });

    // Create default settings
    await prisma.settings.create({ data: { userId: user.id } });

    const accessToken = generateAccessToken(app, { userId: user.id, email: user.email, role: user.role });
    const refreshToken = generateRefreshToken(app, { userId: user.id, email: user.email }, false);

    await auditLog(request, 'REGISTER', 'user', user.id, { email });

    return reply.code(201).send({
      success: true,
      data: { user, accessToken, refreshToken }
    });
  });

  // Refresh token
  app.post('/refresh', {
    schema: { body: refreshSchema }
  }, async (request, reply) => {
    const { refreshToken } = request.body;

    const payload = verifyRefreshToken(app, refreshToken);
    if (!payload) {
      return reply.code(401).send({ success: false, error: { code: 'INVALID_REFRESH_TOKEN', message: 'Invalid or expired refresh token', statusCode: 401 } });
    }

    const user = await prisma.user.findUnique({ where: { id: payload.userId } });
    if (!user) {
      return reply.code(401).send({ success: false, error: { code: 'USER_NOT_FOUND', message: 'User not found', statusCode: 401 } });
    }

    const accessToken = generateAccessToken(app, { userId: user.id, email: user.email, role: user.role });
    const newRefreshToken = generateRefreshToken(app, { userId: user.id, email: user.email }, false);

    return { success: true, data: { accessToken, refreshToken: newRefreshToken } };
  });

  // Logout (revoke refresh token - in production, add to blacklist)
  app.post('/logout', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    await auditLog(request, 'LOGOUT', 'user', (request as any).user.userId);
    return { success: true, message: 'Logged out successfully' };
  });

  // Get current user
  app.get('/me', {
    preHandler: [app.authenticate]
  }, async (request) => {
    const userId = (request as any).user.userId;
    const user = await prisma.user.findUnique({
      where: { id: userId },
      select: { id: true, email: true, name: true, avatarUrl: true, role: true, theme: true, sidebarCollapsed: true, language: true, emailNotifications: true, inAppNotifications: true, notifyScanComplete: true, notifyScanFailed: true, notifyVulnFound: true, notifyJobChange: true, lastLoginAt: true, createdAt: true }
    });

    return { success: true, data: user };
  });

  // Change password
  app.post('/change-password', {
    preHandler: [app.authenticate],
    schema: { body: changePasswordSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { currentPassword, newPassword } = request.body;

    const user = await prisma.user.findUnique({ where: { id: userId } });
    if (!user) {
      return reply.code(404).send({ success: false, error: { code: 'USER_NOT_FOUND', message: 'User not found', statusCode: 404 } });
    }

    const valid = await verifyPassword(currentPassword, user.passwordHash);
    if (!valid) {
      return reply.code(401).send({ success: false, error: { code: 'INVALID_PASSWORD', message: 'Current password is incorrect', statusCode: 401 } });
    }

    const passwordHash = await hashPassword(newPassword);
    await prisma.user.update({ where: { id: userId }, data: { passwordHash } });

    await auditLog(request, 'PASSWORD_CHANGED', 'user', userId);

    return { success: true, message: 'Password changed successfully' };
  });

  // OAuth routes (placeholder - would redirect to provider)
  app.get('/github', async (request, reply) => {
    // In production, redirect to GitHub OAuth
    return reply.redirect('/login?error=oauth_not_configured');
  });

  app.get('/gitlab', async (request, reply) => {
    return reply.redirect('/login?error=oauth_not_configured');
  });

  app.get('/bitbucket', async (request, reply) => {
    return reply.redirect('/login?error=oauth_not_configured');
  });
}

