52	export async function initializeQueue(): Promise<void> {
53	  // Create workers for each job type
54	  const worker = new Worker<JobData>(
55	    'devsecops-jobs',
56	    async (job) => await processJob(job),
57	    {
58	      connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
59	      concurrency: config.QUEUE_CONCURRENCY
60	    }
61	  );
62	
63	  worker.on('error', (err) => logger.error({ err }, 'Queue worker error'));
64	  logger.info('Job queue workers started');
65	}
66	
67	export async function shutdownQueue(): Promise<void> {
68	  await queue.close();
69	  await queueEvents.close();
70	}
71	
72	export async function createJob(data: JobData, priority: 'low' | 'normal' | 'high' = 'normal'): Promise<string> {
73	  const job = await queue.add(data.type, data, {
74	    priority: priority === 'high' ? 10 : priority === 'low' ? 1 : 5
75	  });
76	  return job.id!;
77	}
78	
79	export async function getJobStatus(jobId: string): Promise<any> {
80	  const job = await queue.getJob(jobId);
81	  if (!job) return null;
82	
83	  const state = await job.getState();
84	  const progress = job.progress;
85	
86	  return {
87	    id: job.id,
88	    type: job.name,
89	    status: state,
90	    progress: typeof progress === 'number' ? progress : 0,
91	    data: job.data,
92	    returnvalue: job.returnvalue,
93	    failedReason: job.failedReason,
94	    createdAt: new Date(job.timestamp).toISOString(),
95	    processedAt: job.processedOn ? new Date(job.processedOn).toISOString() : null,
96	    finishedAt: job.finishedOn ? new Date(job.finishedOn).toISOString() : null
97	  };
98	}
