export async function cancelJob(jobId: string): Promise<boolean> {
  const job = await queue.getJob(jobId);
  if (job) {
    await job.remove();
    await updateJobStatus(jobId, 'cancelled', 0, 'Cancelled');
    return true;
  }
  return false;
}

async function updateJobStatus(
  jobId: string,
  status: JobStatus,
  progress: number,
  currentStep: string,
  output?: any,
  error?: string
): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: {
      status,
      progress,
      currentStep,
      output,
      error,
      completedAt: ['completed', 'failed', 'cancelled'].includes(status) ? new Date() : null
    }
  });
}

async function updateJobProgress(jobId: string, progress: number, currentStep: string): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: { progress, currentStep }
  });
}

async function processJob(job: Job<JobData>): Promise<any> {
  const { type, input, userId, scanId } = job.data;

  await prisma.job.update({
    where: { id: job.id },
    data: { status: 'running', startedAt: new Date() }
  });

  try {
    let result: any;

    switch (type) {
      case 'dockerfile_scan':
        result = await scanDockerfile(input.content, job, scanId);
        break;
      case 'dockerfile_fix':
        result = await fixDockerfile(input.content, input.findings || [], job);
        break;
      case 'docker_image_scan':
        result = await scanDockerImage(input.imageName, job, scanId);
        break;
      case 'docker_image_fix':
        result = await fixDockerImage(input.dockerfile, input.vulnerabilities || [], job);
        break;
      case 'kubernetes_scan':
        result = await scanKubernetes(input.content, job, scanId);
        break;
      case 'kubernetes_fix':
        result = await fixKubernetes(input.content, input.findings || [], job);
        break;
      case 'kubernetes_generate':
        result = await generateKubernetes(input.spec, job);
        break;
      case 'jenkinsfile_scan':
        result = await scanJenkinsfile(input.content, job, scanId);
        break;
      case 'jenkinsfile_fix':
        result = await fixJenkinsfile(input.content, input.findings || [], job);
        break;
      case 'jenkinsfile_generate':
        result = await generateJenkinsfile(input.spec, job);
        break;
      case 'github_repo_scan':
        result = await scanGitHubRepo(input.repoUrl, input.branch || 'main', input.token, job, scanId);
        break;
      case 'github_code_fix':
        result = await fixGitHubCode(input.finding, input.fileContent, input.surroundingContext, job);
        break;
      case 'log_investigation':
        result = await investigateLogs(input.question, input.logEntries || [], input.context, job);
        break;
      case 'log_search':
        result = await searchLogs(input.query, input.logFiles || [], input.options, job);
        break;
      case 'log_parse':
        result = await parseLogFile(input.filePath, job);
        break;
      case 'dependency_scan':
        result = await scanDependencies(input, job, scanId);
        break;
      case 'dependency_fix':
        result = await remediateDependency(input.scanId, input.packageName, input.currentVersion, job);
        break;
      case 'sbom_generation':
        result = await generateSBOM(input.scanId, input.format || 'cyclonedx', job);
        break;
      default:
        throw new Error(`Unknown job type: ${type}`);
    }

    // Create scan record if applicable
    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: {
          status: 'completed',
          summary: result.summary,
          completedAt: new Date()
        }
      });
    }

    return result;
  } catch (error) {
    logger.error({ err: error, jobId: job.id, type }, 'Job processing failed');

    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: { status: 'failed', completedAt: new Date() }
      });
    }

    throw error;
  }
}

