import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  content: z.string().min(1),
  targetName: z.string().optional(),
  fix: z.boolean().optional().default(false)
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findings: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    code: z.string().optional(),
    ruleId: z.string().optional(),
    remediation: z.any().optional()
  })).optional()
});

const imageScanSchema = z.object({
  imageName: z.string().min(1),
  targetName: z.string().optional()
});

const imageFixSchema = z.object({
  scanId: z.string().uuid(),
  dockerfile: z.string().min(1),
  vulnerabilities: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    package: z.string().optional(),
    version: z.string().optional(),
    fixedVersion: z.string().optional()
  })).optional()
});

export async function dockerfileRoutes(app: FastifyInstance) {
  // Scan Dockerfile
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { content, targetName, fix } = request.body;

    // Create scan record
    const scan = await prisma.scan.create({
      data: {
        type: 'dockerfile',
        status: 'pending',
        targetType: 'dockerfile',
        targetValue: targetName || 'Dockerfile',
        targetMeta: { content },
        userId
      }
    });

    // Create job
    const job = await createJob('dockerfile_scan', {
      content,
      scanId: scan.id
    }, userId);

    await prisma.scan.update({
      where: { id: scan.id },
      data: { jobId: job.id }
    });

    await auditLog(request, 'DOCKERFILE_SCAN_STARTED', 'scan', scan.id, { targetName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Scan Docker Image
  app.post('/scan-image', {
    preHandler: [app.authenticate],
    schema: { body: imageScanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { imageName, targetName } = request.body;

    // Create scan record
    const scan = await prisma.scan.create({
      data: {
        type: 'docker_image',
        status: 'pending',
        targetType: 'docker_image',
        targetValue: targetName || imageName,
        targetMeta: { imageName },
        userId
      }
    });

    // Create job
    const job = await createJob('docker_image_scan', {
      imageName,
      scanId: scan.id
    }, userId);

    await prisma.scan.update({
      where: { id: scan.id },
      data: { jobId: job.id }
    });

    await auditLog(request, 'DOCKER_IMAGE_SCAN_STARTED', 'scan', scan.id, { imageName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Fix Dockerfile
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findings } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const dockerfile = (scan.targetMeta as any)?.content || '';

    const job = await createJob('dockerfile_fix', {
      scanId,
      content: dockerfile,
      findings: findings || scan.findings
    }, userId);

    await auditLog(request, 'DOCKERFILE_FIX_STARTED', 'scan', scanId);

    return { success: true, data: { jobId: job.id } };
  });

  // Fix Docker Image (base image upgrade)
  app.post('/fix-image', {
    preHandler: [app.authenticate],
    schema: { body: imageFixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, dockerfile, vulnerabilities } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('docker_image_fix', {
      scanId,
      dockerfile,
      vulnerabilities: vulnerabilities || scan.findings
    }, userId);

    await auditLog(request, 'DOCKER_IMAGE_FIX_STARTED', 'scan', scanId);

    return { success: true, data: { jobId: job.id } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });
}

