import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  image: z.string().min(1),
  tag: z.string().optional().default('latest'),
  platform: z.string().optional(),
  tools: z.array(z.enum(['grype', 'trivy', 'syft'])).optional().default(['grype', 'syft']),
  sbom: z.boolean().optional().default(true)
});

export async function dockerRoutes(app: FastifyInstance) {
  // Scan Docker image
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { image, tag, platform, tools, sbom } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'docker_image',
        status: 'pending',
        targetType: 'docker_image',
        targetValue: `${image}:${tag}`,
        targetMeta: { image, tag, platform, tools, sbom },
        userId
      }
    });

    const job = await createJob('docker_image_scan', {
      scanId: scan.id,
      image,
      tag,
      platform,
      tools,
      sbom
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'DOCKER_IMAGE_SCAN_STARTED', 'scan', scan.id, { image, tag });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // Get SBOM for scan
  app.get('/scan/:id/sbom', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const sbom = scan.targetMeta as any;
    return { success: true, data: sbom?.sbom || null };
  });

  // List local images (requires Docker daemon)
  app.get('/images', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    // Would use Docker API to list local images
    return { success: true, data: [] };
  });
}

