      findingId,
      branch,
      fixType,
      finding: {
        id: finding.id,
        type: finding.type,
        severity: finding.severity,
        title: finding.title,
        description: finding.description,
        file: finding.file,
        line: finding.line,
        code: finding.code,
        ruleId: finding.ruleId
      }
    }, userId);

