    return { success: true, data: { jobId: job.id } };
  });

  // Create PR
  app.post('/create-pr', {
    preHandler: [app.authenticate],
    schema: { body: createPrSchema }
  }, async (request, reply) => {
    // In production, use GitHub API to create PR
    const { repoId, branch, title, body, changes } = request.body;

    await auditLog(request, 'GITHUB_PR_CREATED', 'github_repo', repoId, { branch, title });

    return {
      success: true,
      data: {
        prUrl: `https://github.com/repo/pull/123`,
        prNumber: 123
      }
    };
  });

  // List connected repos
  app.get('/repos', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const repos = await prisma.gitHubRepository.findMany({
      where: { userId },
      orderBy: { connectedAt: 'desc' }
    });
    return { success: true, data: repos };
  });
}

