import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  jenkinsfile: z.string().min(1),
  targetName: z.string().optional(),
  fix: z.boolean().optional().default(false)
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findings: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    code: z.string().optional(),
    ruleId: z.string().optional(),
    remediation: z.any().optional()
  })).optional()
});

const generateSchema = z.object({
  type: z.enum(['declarative', 'scripted']),
  name: z.string(),
  agent: z.string().optional().default('any'),
  stages: z.array(z.object({
    name: z.string(),
    steps: z.array(z.object({
      type: z.enum(['sh', 'bat', 'checkout', 'archive', 'stash', 'unstash', 'input', 'timeout', 'retry']),
      command: z.string().optional(),
      args: z.record(z.any()).optional()
    }))
  })),
  environment: z.record(z.string()).optional(),
  options: z.object({
    timestamps: z.boolean().optional(),
    timeout: z.string().optional(),
    retry: z.number().optional()
  }).optional(),
  triggers: z.array(z.object({
    type: z.enum(['cron', 'pollSCM', 'github', 'generic']),
    spec: z.string().optional()
  })).optional()
});

const testConnectionSchema = z.object({
  url: z.string().url(),
  username: z.string(),
  token: z.string()
});

export async function jenkinsRoutes(app: FastifyInstance) {
  // Scan Jenkinsfile
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { jenkinsfile, targetName, fix } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'jenkinsfile',
        status: 'pending',
        targetType: 'jenkinsfile',
        targetValue: targetName || 'Jenkinsfile',
        targetMeta: { jenkinsfile },
        userId
      }
    });

    const job = await createJob('jenkinsfile_scan', {
      scanId: scan.id,
      jenkinsfile,
      fix
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'JENKINSFILE_SCAN_STARTED', 'scan', scan.id, { targetName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Fix Jenkinsfile
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findings } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('jenkinsfile_fix', {
      scanId,
      jenkinsfile: (scan.targetMeta as any)?.jenkinsfile || '',
      findings: findings || scan.findings
    }, userId);

    await auditLog(request, 'JENKINSFILE_FIX_STARTED', 'scan', scanId);
    return { success: true, data: { jobId: job.id } };
  });

  // Generate Jenkinsfile
  app.post('/generate', {
    preHandler: [app.authenticate],
    schema: { body: generateSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { type, name, agent, stages, environment, options, triggers } = request.body;

    const job = await createJob('jenkinsfile_generate', {
      type,
      name,
      agent,
      stages,
      environment,
      options,
      triggers
    }, userId);

    await auditLog(request, 'JENKINSFILE_GENERATE_STARTED', 'job', job.id, { type, name });
    return { success: true, data: { jobId: job.id } };
  });

  // Test Jenkins connection
  app.post('/test-connection', {
    preHandler: [app.authenticate],
    schema: { body: testConnectionSchema }
  }, async (request, reply) => {
    // Would test actual Jenkins API connection
    return { success: true, data: { connected: true, version: '2.400' } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });
}

