import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  yaml: z.string().min(1),
  targetName: z.string().optional(),
  tools: z.array(z.enum(['kubeconform', 'kubeval', 'checkov'])).optional().default(['kubeconform'])
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findings: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    code: z.string().optional(),
    ruleId: z.string().optional(),
    remediation: z.any().optional()
  })).optional()
});

const generateSchema = z.object({
  type: z.enum(['deployment', 'service', 'ingress', 'configmap', 'secret', 'pvc', 'cronjob']),
  name: z.string(),
  namespace: z.string().optional().default('default'),
  image: z.string().optional(),
  replicas: z.number().optional().default(1),
  ports: z.array(z.object({ port: z.number(), targetPort: z.number().optional() })).optional(),
  env: z.array(z.object({ name: z.string(), value: z.string() })).optional(),
  resources: z.object({
    limits: z.object({ cpu: z.string().optional(), memory: z.string().optional() }).optional(),
    requests: z.object({ cpu: z.string().optional(), memory: z.string().optional() }).optional()
  }).optional()
});

export async function kubernetesRoutes(app: FastifyInstance) {
  // Scan Kubernetes YAML
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { yaml, targetName, tools } = request.body;

    const scan = await prisma.scan.create({
      data: {
        type: 'kubernetes',
        status: 'pending',
        targetType: 'kubernetes_yaml',
        targetValue: targetName || 'kubernetes.yaml',
        targetMeta: JSON.stringify({ yaml, tools }),
        userId
      }
    });

    const job = await createJob('kubernetes_scan', {
      scanId: scan.id,
      yaml,
      tools
    }, userId);

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'KUBERNETES_SCAN_STARTED', 'scan', scan.id, { targetName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Fix Kubernetes YAML
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findings } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob('kubernetes_fix', {
      scanId,
      yaml: (scan.targetMeta as any)?.yaml || '',
      findings: findings || scan.findings
    }, userId);

    await auditLog(request, 'KUBERNETES_FIX_STARTED', 'scan', scanId);
    return { success: true, data: { jobId: job.id } };
  });

  // Generate Kubernetes YAML
  app.post('/generate', {
    preHandler: [app.authenticate],
    schema: { body: generateSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { type, name, namespace, image, replicas, ports, env, resources } = request.body;

    const job = await createJob('kubernetes_generate', {
      type,
      name,
      namespace,
      image,
      replicas,
      ports,
      env,
      resources
    }, userId);

    await auditLog(request, 'KUBERNETES_GENERATE_STARTED', 'job', job.id, { type, name });
    return { success: true, data: { jobId: job.id } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const scanSchema = z.object({
  jenkinsfile: z.string().min(1),
  targetName: z.string().optional(),
  fix: z.boolean().optional().default(false)
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findings: z.array(z.object({
    id: z.string(),
    type: z.string(),
    severity: z.string(),
    title: z.string(),
    description: z.string(),
    file: z.string().optional(),
    line: z.number().optional(),
    code: z.string().optional(),
    ruleId: z.string().optional(),
    remediation: z.any().optional()
  })).optional()
});

const generateSchema = z.object({
  type: z.enum(['declarative', 'scripted']),
  name: z.string(),
  agent: z.string().optional().default('any'),
  stages: z.array(z.object({
    name: z.string(),
    steps: z.array(z.object({
      type: z.enum(['sh', 'bat', 'checkout', 'archive', 'stash', 'unstash', 'input', 'timeout', 'retry']),
      command: z.string().optional(),
      args: z.record(z.any()).optional()
    }))
  })),
  environment: z.record(z.string()).optional(),
  options: z.object({
    timestamps: z.boolean().optional(),
    timeout: z.string().optional(),
    retry: z.number().optional()
  }).optional(),
  triggers: z.array(z.object({
    type: z.enum(['cron', 'pollSCM', 'github', 'generic']),
    spec: z.string().optional()
  })).optional()
});

const testConnectionSchema = z.object({
  url: z.string().url(),
  username: z.string(),
  token: z.string()
});

export async function jenkinsRoutes(app: FastifyInstance) {
  // Scan Jenkinsfile
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { jenkinsfile, targetName, fix } = request.body as { jenkinsfile: string; targetName?: string; fix?: boolean };

    const scan = await prisma.scan.create({
      data: {
        type: 'jenkinsfile',
        status: 'pending',
        targetType: 'jenkinsfile',
        targetValue: targetName || 'Jenkinsfile',
        targetMeta: JSON.stringify({ jenkinsfile }),
        userId
      }
    });

    const job = await createJob({
      type: 'jenkinsfile_scan',
      input: { jenkinsfile, fix },
      userId,
      scanId: scan.id
    });

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'JENKINSFILE_SCAN_STARTED', 'scan', scan.id, { targetName });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Fix Jenkinsfile
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findings } = request.body as { scanId: string; findings?: any[] };

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: true }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    const job = await createJob({
      type: 'jenkinsfile_fix',
      input: { jenkinsfile: (scan.targetMeta as any)?.jenkinsfile || '', findings: findings || scan.findings },
      userId,
      scanId
    });

    await auditLog(request, 'JENKINSFILE_FIX_STARTED', 'scan', scanId);
    return { success: true, data: { jobId: job.id } };
  });

  // Generate Jenkinsfile
  app.post('/generate', {
    preHandler: [app.authenticate],
    schema: { body: generateSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { type, name, agent, stages, environment, options, triggers } = request.body as { type: string; name: string; agent?: string; stages: any[]; environment?: Record<string, string>; options?: any; triggers?: any[] };

    const job = await createJob('jenkinsfile_generate', {
      type,
      name,
      agent,
      stages,
      environment,
      options,
      triggers
    }, userId);

    await auditLog(request, 'JENKINSFILE_GENERATE_STARTED', 'job', job.id, { type, name });
    return { success: true, data: { jobId: job.id } };
  });

  // Test Jenkins connection
  app.post('/test-connection', {
    preHandler: [app.authenticate],
    schema: { body: testConnectionSchema }
  }, async (request, reply) => {
    // Would test actual Jenkins API connection
    return { success: true, data: { connected: true, version: '2.400' } };
  });

  // Get scan results
  app.get('/scan/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const connectSchema = z.object({
  token: z.string().min(1),
  org: z.string().optional()
});

const scanSchema = z.object({
  repoUrl: z.string().url(),
  branch: z.string().optional().default('main'),
  scanTypes: z.array(z.enum(['vulnerabilities', 'secrets', 'dependencies', 'code'])).optional().default(['vulnerabilities', 'secrets', 'dependencies', 'code'])
});

const fixSchema = z.object({
  scanId: z.string().uuid(),
  findingId: z.string(),
  branch: z.string().optional().default('main'),
  fixType: z.enum(['patch', 'upgrade', 'config'])
});

const createPrSchema = z.object({
  repoId: z.string(),
  branch: z.string(),
  title: z.string(),
  body: z.string().optional(),
  changes: z.array(z.object({
    file: z.string(),
    content: z.string()
  }))
});

export async function githubRoutes(app: FastifyInstance) {
  // Connect GitHub
  app.post('/connect', {
    preHandler: [app.authenticate],
    schema: { body: connectSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { token, org } = request.body as { token: string; org?: string };

    // In production, validate token with GitHub API and fetch user/org info
    // For now, create a mock repository entry
    const repo = await prisma.gitHubRepository.create({
      data: {
        userId,
        githubId: Date.now(),
        name: org || 'connected-repo',
        fullName: `${org || 'user'}/connected-repo`,
        url: `https://github.com/${org || 'user'}/connected-repo`,
        cloneUrl: `https://github.com/${org || 'user'}/connected-repo.git`,
        defaultBranch: 'main'
      }
    });

    await auditLog(request, 'GITHUB_CONNECTED', 'github_repo', repo.id, { org });

    return { success: true, data: { connected: true, repo } };
  });

  // Scan GitHub repository
  app.post('/scan', {
    preHandler: [app.authenticate],
    schema: { body: scanSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { repoUrl, branch, scanTypes } = request.body as { repoUrl: string; branch?: string; scanTypes?: string[] };

    const scan = await prisma.scan.create({
      data: {
        type: 'github_repo',
        status: 'pending',
        targetType: 'github_repo',
        targetValue: repoUrl,
        targetMeta: JSON.stringify({ branch, scanTypes }),
        userId
      }
    });

    // Get GitHub token from settings
    const settings = await prisma.settings.findUnique({ where: { userId } });
    const token = settings?.githubToken || settings?.githubPrivateKey;

    const job = await createJob({
      type: 'github_repo_scan',
      input: { repoUrl, branch, scanTypes, token },
      userId,
      scanId: scan.id
    });

    await prisma.scan.update({ where: { id: scan.id }, data: { jobId: job.id } });
    await auditLog(request, 'GITHUB_SCAN_STARTED', 'scan', scan.id, { repoUrl, branch, scanTypes });

    return { success: true, data: { scanId: scan.id, jobId: job.id } };
  });

  // Get scan status
  app.get('/scan/:id/status', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    // If scan has a job, get job status
    let jobStatus = 'pending';
    let progress = 0;
    if (scan.jobId) {
      const job = await prisma.job.findUnique({ where: { id: scan.jobId } });
      if (job) {
        jobStatus = job.status;
        progress = job.progress;
      }
    }

    return { success: true, data: { status: jobStatus, progress } };
  });

  // Get scan results
  app.get('/scan/:id/results', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: { findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] } }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // Fix finding (code fix)
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { scanId, findingId, branch, fixType } = request.body;

    const scan = await prisma.scan.findUnique({
      where: { id: scanId },
      include: { findings: { where: { id: findingId } } }
    });

    if (!scan || scan.userId !== userId || scan.findings.length === 0) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Finding not found', statusCode: 404 } });
    }

    const finding = scan.findings[0];
    const job = await createJob('github_code_fix', {
      scanId,
      findingId,
      branch,
      fixType,
      finding: {
        id: finding.id,
        type: finding.type,
        severity: finding.severity,
        title: finding.title,
        description: finding.description,
        file: finding.file,
        line: finding.line,
        code: finding.code,
        ruleId: finding.ruleId
      }
    }, userId);

    await auditLog(request, 'GITHUB_FIX_STARTED', 'finding', findingId);
    return { success: true, data: { jobId: job.id } };
  });

  // Create PR
  app.post('/create-pr', {
    preHandler: [app.authenticate],
    schema: { body: createPrSchema }
  }, async (request, reply) => {
    // In production, use GitHub API to create PR
    const { repoId, branch, title, body, changes } = request.body;

    await auditLog(request, 'GITHUB_PR_CREATED', 'github_repo', repoId, { branch, title });

    return {
      success: true,
      data: {
        prUrl: `https://github.com/repo/pull/123`,
        prNumber: 123
      }
    };
  });

  // List connected repos
  app.get('/repos', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const repos = await prisma.gitHubRepository.findMany({
      where: { userId },
      orderBy: { connectedAt: 'desc' }
    });
    return { success: true, data: repos };
  });
}

import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { getAIProvider } from '../../shared/ai';
import { auditLog } from '../../shared/utils/audit';

const askSchema = z.object({
  prompt: z.string().min(1).max(10000),
  context: z.string().optional(),
  model: z.string().optional(),
  temperature: z.number().min(0).max(2).optional(),
  maxTokens: z.number().optional(),
