1	import { Queue, Worker, Job, QueueEvents } from 'bullmq';
2	import { config } from '../config';
3	import { prisma } from '../database';
4	import { aiService } from '../ai';
5	import { logger } from '../utils/logger';
6	import { JobType, JobStatus } from '@devsecops/shared/types';
7	
8	// Import scanner modules
9	import { scanDockerfile, fixDockerfile, scanDockerImage, fixDockerImage } from '../../modules/dockerfile/scanners';
10	import { scanKubernetes, fixKubernetes, generateKubernetes } from '../../modules/kubernetes/scanners';
11	import { scanJenkinsfile, fixJenkinsfile, generateJenkinsfile } from '../../modules/jenkins/scanners';
12	import { scanGitHubRepo, fixGitHubCode } from '../../modules/github/scanners';
13	import { scanDependencies, remediateDependency, generateSBOM } from '../../modules/dependencies/scanners';
14	import { investigateLogs, searchLogs, parseLogFile } from '../../modules/logs/scanners';
15	
16	interface JobData {
17	  type: JobType;
18	  input: Record<string, unknown>;
19	  userId: string;
20	  scanId?: string;
21	}
22	
23	const queue = new Queue<JobData>('devsecops-jobs', {
24	  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
25	  defaultJobOptions: {
26	    removeOnComplete: 100,
27	    removeOnFail: 50,
28	    attempts: 3,
29	    backoff: { type: 'exponential', delay: 5000 },
30	    timeout: config.JOB_TIMEOUT
31	  }
32	});
33	
34	const queueEvents = new QueueEvents('devsecops-jobs', {
35	  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') }
36	});
37	
38	queueEvents.on('completed', async ({ jobId, returnvalue }) => {
39	  await updateJobStatus(jobId, 'completed', 100, 'Completed', returnvalue as any);
40	});
41	
42	queueEvents.on('failed', async ({ jobId, failedReason }) => {
43	  await updateJobStatus(jobId, 'failed', 0, 'Failed', undefined, failedReason);
44	});
45	
46	queueEvents.on('progress', async ({ jobId, data }) => {
47	  if (data && typeof data === 'object' && 'progress' in data) {
48	    await updateJobProgress(jobId, data.progress as number, data.currentStep as string);
49	  }
50	});
51	
52	export async function initializeQueue(): Promise<void> {
53	  // Create workers for each job type
54	  const worker = new Worker<JobData>(
55	    'devsecops-jobs',
56	    async (job) => await processJob(job),
57	    {
58	      connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
59	      concurrency: config.QUEUE_CONCURRENCY
60	    }
61	  );
62	
63	  worker.on('error', (err) => logger.error({ err }, 'Queue worker error'));
64	  logger.info('Job queue workers started');
65	}
66	
