import { FastifyInstance } from 'fastify';
import { z } from 'zod';
import { prisma } from '../../shared/database';
import { createJob } from '../../shared/queue';
import { auditLog } from '../../shared/utils/audit';

const searchSchema = z.object({
  query: z.string().optional(),
  logFileIds: z.array(z.string().uuid()).optional(),
  timeRange: z.object({
    start: z.string().datetime(),
    end: z.string().datetime()
  }).optional(),
  levels: z.array(z.string()).optional(),
  services: z.array(z.string()).optional(),
  limit: z.number().optional().default(100),
  offset: z.number().optional().default(0)
});

const investigateSchema = z.object({
  question: z.string().min(1),
  logFileIds: z.array(z.string().uuid()).min(1),
  timeRange: z.object({
    start: z.string().datetime(),
    end: z.string().datetime()
  }).optional()
});

export async function logsRoutes(app: FastifyInstance) {
  // Upload log file
  app.post('/upload', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const data = await request.file();

    if (!data) {
      return reply.code(400).send({ success: false, error: { code: 'NO_FILE', message: 'No file uploaded', statusCode: 400 } });
    }

    const chunks: Buffer[] = [];
    for await (const chunk of data.file) {
      chunks.push(chunk);
    }
    const buffer = Buffer.concat(chunks);
    const content = buffer.toString('utf-8');
    const lines = content.split('\n').filter(l => l.trim().length > 0);

    // Parse log format (simple heuristic)
    const format = data.filename.endsWith('.json') ? 'json' : 'text';

    const logFile = await prisma.logFile.create({
      data: {
        name: data.filename,
        size: BigInt(buffer.length),
        lineCount: lines.length,
        format,
        userId
      }
    });

    // Parse entries (simplified - would use proper log parser in production)
    const entries = lines.slice(0, 10000).map((line, index) => {
      let parsed: any = { message: line };
      try {
        if (format === 'json') {
          parsed = JSON.parse(line);
        }
      } catch {
        // Keep as raw message
      }
      return {
        logFileId: logFile.id,
        timestamp: parsed.timestamp ? new Date(parsed.timestamp) : new Date(),
        level: (parsed.level || parsed.severity || 'info').toLowerCase(),
        service: parsed.service || parsed.component || 'unknown',
        message: parsed.message || parsed.msg || line,
        raw: line,
        fields: parsed
      };
    });

    if (entries.length > 0) {
      await prisma.logEntry.createMany({ data: entries });
    }

    await prisma.logFile.update({
      where: { id: logFile.id },
      data: { indexed: true }
    });

    await auditLog(request, 'LOG_UPLOADED', 'log_file', logFile.id, { name: data.filename, lines: lines.length });

    return { success: true, data: logFile };
  });

  // List log files
  app.get('/files', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const files = await prisma.logFile.findMany({
      where: { userId },
      orderBy: { createdAt: 'desc' },
      select: { id: true, name: true, size: true, lineCount: true, format: true, indexed: true, createdAt: true }
    });
    return { success: true, data: files };
  });

  // Delete log file
  app.delete('/files/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const logFile = await prisma.logFile.findUnique({ where: { id } });
    if (!logFile || logFile.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Log file not found', statusCode: 404 } });
    }

    await prisma.logFile.delete({ where: { id } });
    await auditLog(request, 'LOG_DELETED', 'log_file', id);
    return { success: true, message: 'Log file deleted' };
  });

  // Search logs
  app.post('/search', {
    preHandler: [app.authenticate],
    schema: { body: searchSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { query, logFileIds, timeRange, levels, services, limit, offset } = request.body;

    // Get user's log files
    const userFiles = await prisma.logFile.findMany({
      where: { userId },
      select: { id: true }
    });
    const userFileIds = userFiles.map(f => f.id);

