      case 'dockerfile_scan':
        result = await scanDockerfile(input.content, job, scanId);
        break;
      case 'dockerfile_fix':
        result = await fixDockerfile(input.content, input.findings || [], job);
        break;
      case 'docker_image_scan':
        result = await scanDockerImage(input.imageName, job, scanId);
        break;
      case 'docker_image_fix':
        result = await fixDockerImage(input.dockerfile, input.vulnerabilities || [], job);
        break;
      case 'kubernetes_scan':
        result = await scanKubernetes(input.content, job, scanId);
        break;
      case 'kubernetes_fix':
        result = await fixKubernetes(input.content, input.findings || [], job);
        break;
      case 'kubernetes_generate':
        result = await generateKubernetes(input.spec, job);
        break;
      case 'jenkinsfile_scan':
        result = await scanJenkinsfile(input.content, job, scanId);
        break;
      case 'jenkinsfile_fix':
        result = await fixJenkinsfile(input.content, input.findings || [], job);
