        result = await generateJenkinsfile(input.spec, job);
        break;
      case 'github_repo_scan':
        result = await scanGitHubRepo(input.repoUrl, input.branch || 'main', input.token, job, scanId);
        break;
      case 'github_code_fix':
        result = await fixGitHubCode(input.finding, input.fileContent || '', input.surroundingContext || '', job);
        break;
      case 'log_investigation':
        result = await investigateLogs(input.question, input.logEntries || [], input.context, job);
        break;
      case 'log_search':
        result = await searchLogs(input.query, input.logFiles || [], input.options, job);
