        break;
      case 'kubernetes_fix':
        result = await fixKubernetes(getString('content'), (i.findings as any[]) || [], job);
        break;
      case 'kubernetes_generate':
        result = await generateKubernetes(i.spec as any, job);
        break;
      case 'jenkinsfile_scan':
        result = await scanJenkinsfile(getString('content'), job, scanId);
        break;
      case 'jenkinsfile_fix':
        result = await fixJenkinsfile(getString('content'), (i.findings as any[]) || [], job);
        break;
      case 'jenkinsfile_generate':
        result = await generateJenkinsfile(i.spec as any, job);
        break;
      case 'github_repo_scan':
        result = await scanGitHubRepo(getString('repoUrl'), getString('branch', 'main'), i.token as string | undefined, job, scanId);
        break;
      case 'github_code_fix':
        result = await fixGitHubCode(i.finding as any, getString('fileContent'), getString('surroundingContext'), job);
        break;
      case 'log_investigation':
        result = await investigateLogs(getString('question'), (i.logEntries as any[]) || [], i.context, job);
        break;
      case 'log_search':
        result = await searchLogs(getString('query'), (i.logFiles as string[]) || [], i.options as { caseSensitive?: boolean; regex?: boolean; before?: number; after?: number } || {}, job);
        break;
      case 'log_parse':
        result = await parseLogFile(getString('filePath'), job);
        break;
      case 'dependency_scan':
        result = await scanDependencies(i as any, job, scanId);
        break;
      case 'dependency_fix':
        result = await remediateDependency(getString('scanId'), getString('packageName'), getString('currentVersion'), job);
        break;
      case 'sbom_generation':
        result = await generateSBOM(getString('scanId'), ((i.format as string) || 'cyclonedx') as 'cyclonedx' | 'spdx', job);
        break;
      default:
        throw new Error(`Unknown job type: ${type}`);
    }

    // Create scan record if applicable
    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: {
          status: 'completed',
          summary: result.summary,
          completedAt: new Date()
        }
      });
    }

    return result;
  } catch (error) {
    logger.error({ err: error, jobId: job.id, type }, 'Job processing failed');

    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: { status: 'failed', completedAt: new Date() }
      });
    }

    throw error;
  }
}

