import { FastifyInstance } from 'fastify';
import { prisma } from '../../shared/database';
import { auditLog } from '../../shared/utils/audit';
import crypto from 'crypto';

const updateSettingsSchema = {
  type: 'object',
  properties: {
    general: {
      type: 'object',
      properties: {
        displayName: { type: 'string' },
        email: { type: 'string', format: 'email' },
        timezone: { type: 'string' },
        language: { type: 'string' }
      }
    },
    appearance: {
      type: 'object',
      properties: {
        theme: { type: 'string', enum: ['dark', 'light', 'system'] },
        compactMode: { type: 'boolean' },
        animations: { type: 'boolean' },
        sidebarCollapsed: { type: 'boolean' }
      }
    },
    notifications: {
      type: 'object',
      properties: {
        email: { type: 'boolean' },
        scanComplete: { type: 'boolean' },
        scanFailed: { type: 'boolean' },
        vulnerabilityAlerts: { type: 'boolean' },
        weeklyDigest: { type: 'boolean' }
      }
    },
    security: {
      type: 'object',
      properties: {
        currentPassword: { type: 'string' },
        newPassword: { type: 'string', minLength: 8 },
        twoFA: { type: 'boolean' },
        sessionTimeout: { type: 'number' }
      }
    },
    integrations: {
      type: 'object',
      properties: {
        github: { type: 'object', properties: { token: { type: 'string' } } },
        gitlab: { type: 'object', properties: { token: { type: 'string' } } },
        bitbucket: { type: 'object', properties: { token: { type: 'string' } } },
        slack: { type: 'object', properties: { webhook: { type: 'string' } } },
        teams: { type: 'object', properties: { webhook: { type: 'string' } } },
        jira: { type: 'object', properties: { url: { type: 'string' }, token: { type: 'string' } } },
        webhook: { type: 'object', properties: { url: { type: 'string' }, secret: { type: 'string' } } }
      }
    },
    advanced: {
      type: 'object',
      properties: {
        debugMode: { type: 'boolean' },
        telemetryEnabled: { type: 'boolean' },
        autoUpdate: { type: 'boolean' }
      }
    }
  }
};

const createApiKeySchema = {
  type: 'object',
  required: ['name'],
  properties: {
    name: { type: 'string', minLength: 1, maxLength: 100 },
    expiresAt: { type: 'string', format: 'date-time' }
  }
};

export async function settingsRoutes(app: FastifyInstance) {
  // Get all settings
  app.get('/', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;

    const [user, settings, apiKeys] = await Promise.all([
      prisma.user.findUnique({
        where: { id: userId },
        select: { name: true, email: true, theme: true, sidebarCollapsed: true, language: true, emailNotifications: true, inAppNotifications: true, notifyScanComplete: true, notifyScanFailed: true, notifyVulnFound: true, notifyJobChange: true }
      }),
      prisma.settings.findUnique({ where: { userId } }),
      prisma.apiKey.findMany({ where: { userId, revokedAt: null }, orderBy: { createdAt: 'desc' } })
    ]);

    return {
      success: true,
      data: {
        general: {
          displayName: user?.name,
          email: user?.email,
          timezone: 'UTC',
          language: user?.language || 'en'
        },
        appearance: {
          theme: user?.theme || 'system',
          compactMode: false,
          animations: true,
          sidebarCollapsed: user?.sidebarCollapsed || false
        },
        notifications: {
          email: user?.emailNotifications ?? true,
          scanComplete: user?.notifyScanComplete ?? true,
          scanFailed: user?.notifyScanFailed ?? true,
          vulnerabilityAlerts: user?.notifyVulnFound ?? true,
          weeklyDigest: user?.notifyJobChange ?? false
        },
        security: {
          twoFA: false,
          sessionTimeout: 30
        },
        integrations: settings ? {
          github: settings.githubPrivateKey ? { token: '***' } : undefined,
          gitlab: settings.gitlabToken ? { token: '***' } : undefined,
          bitbucket: settings.bitbucketToken ? { token: '***' } : undefined,
          slack: settings.slackWebhook ? { webhook: '***' } : undefined,
          teams: settings.teamsWebhook ? { webhook: '***' } : undefined,
          jira: settings.jiraUrl ? { url: settings.jiraUrl, token: '***' } : undefined,
          webhook: settings.webhookUrl ? { url: settings.webhookUrl, secret: '***' } : undefined
        } : {},
        apiKeys: apiKeys.map(k => ({
          id: k.id,
          name: k.name,
          prefix: k.prefix,
          createdAt: k.createdAt,
          lastUsedAt: k.lastUsedAt,
          expiresAt: k.expiresAt
        })),
        advanced: {
          debugMode: false,
          telemetryEnabled: true,
          autoUpdate: true
        }
      }
    };
  });

  // Update settings
  app.patch('/', {
    preHandler: [app.authenticate],
    schema: { body: updateSettingsSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const body = request.body as z.infer<typeof updateSettingsSchema>;

    // Update user table
    if (body.general || body.appearance || body.notifications) {
      const userData: any = {};
      if (body.general?.displayName) userData.name = body.general.displayName;
      if (body.general?.email) userData.email = body.general.email;
      if (body.general?.language) userData.language = body.general.language;
      if (body.appearance?.theme) userData.theme = body.appearance.theme;
      if (body.appearance?.sidebarCollapsed !== undefined) userData.sidebarCollapsed = body.appearance.sidebarCollapsed;
      if (body.notifications?.email !== undefined) userData.emailNotifications = body.notifications.email;
      if (body.notifications?.scanComplete !== undefined) userData.notifyScanComplete = body.notifications.scanComplete;
      if (body.notifications?.scanFailed !== undefined) userData.notifyScanFailed = body.notifications.scanFailed;
      if (body.notifications?.vulnerabilityAlerts !== undefined) userData.notifyVulnFound = body.notifications.vulnerabilityAlerts;
      if (body.notifications?.weeklyDigest !== undefined) userData.notifyJobChange = body.notifications.weeklyDigest;

      if (Object.keys(userData).length > 0) {
        await prisma.user.update({ where: { id: userId }, data: userData });
      }
    }

    // Update settings table
    if (body.security || body.integrations || body.advanced) {
      const settingsData: any = {};
      if (body.security?.twoFA !== undefined) settingsData.twoFA = body.security.twoFA;
      if (body.security?.sessionTimeout) settingsData.sessionTimeout = body.security.sessionTimeout;

      if (body.integrations?.github?.token) settingsData.githubToken = body.integrations.github.token;
      if (body.integrations?.gitlab?.token) settingsData.gitlabToken = body.integrations.gitlab.token;
      if (body.integrations?.bitbucket?.token) settingsData.bitbucketToken = body.integrations.bitbucket.token;
      if (body.integrations?.slack?.webhook) settingsData.slackWebhook = body.integrations.slack.webhook;
      if (body.integrations?.teams?.webhook) settingsData.teamsWebhook = body.integrations.teams.webhook;
      if (body.integrations?.jira?.url) settingsData.jiraUrl = body.integrations.jira.url;
      if (body.integrations?.jira?.token) settingsData.jiraToken = body.integrations.jira.token;
      if (body.integrations?.webhook?.url) settingsData.webhookUrl = body.integrations.webhook.url;
      if (body.integrations?.webhook?.secret) settingsData.webhookSecret = body.integrations.webhook.secret;

      if (body.advanced?.debugMode !== undefined) settingsData.debugMode = body.advanced.debugMode;
      if (body.advanced?.telemetryEnabled !== undefined) settingsData.telemetryEnabled = body.advanced.telemetryEnabled;
      if (body.advanced?.autoUpdate !== undefined) settingsData.autoUpdate = body.advanced.autoUpdate;

      if (Object.keys(settingsData).length > 0) {
        await prisma.settings.upsert({
          where: { userId },
          update: settingsData,
          create: { userId, ...settingsData }
        });
      }
    }

    // Handle password change
    if (body.security?.currentPassword && body.security?.newPassword) {
      // This would be handled by the auth routes /change-password
      // But we can validate here
    }

    await auditLog(request, 'SETTINGS_UPDATED', 'settings', userId, { updatedFields: Object.keys(body) });

    return { success: true, message: 'Settings updated' };
  });

  // Create API key
  app.post('/api-keys', {
    preHandler: [app.authenticate],
    schema: { body: createApiKeySchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { name, expiresAt } = request.body as z.infer<typeof createApiKeySchema>;

    const rawKey = `dsops_${crypto.randomBytes(32).toString('hex')}`;
    const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
    const prefix = rawKey.slice(0, 12);

    const apiKey = await prisma.apiKey.create({
      data: {
        name,
        keyHash,
        prefix,
        userId,
        expiresAt: expiresAt ? new Date(expiresAt) : null
      }
    });

    await auditLog(request, 'API_KEY_CREATED', 'api_key', apiKey.id, { name });

    return {
      success: true,
      data: {
        ...apiKey,
        key: rawKey // Only returned once!
      }
    };
  });

  // Revoke API key
  app.delete('/api-keys/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const apiKey = await prisma.apiKey.findUnique({ where: { id } });
    if (!apiKey || apiKey.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'API key not found', statusCode: 404 } });
    }

    await prisma.apiKey.update({ where: { id }, data: { revokedAt: new Date() } });
    await auditLog(request, 'API_KEY_REVOKED', 'api_key', id);

    return { success: true, message: 'API key revoked' };
  });

  // Export user data
  app.get('/export', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;

    const [user, settings, scans, jobs, logs, apiKeys, notifications] = await Promise.all([
      prisma.user.findUnique({ where: { id: userId } }),
      prisma.settings.findUnique({ where: { userId } }),
      prisma.scan.findMany({ where: { userId }, include: { findings: true } }),
      prisma.job.findMany({ where: { userId } }),
      prisma.logFile.findMany({ where: { userId }, include: { entries: true } }),
      prisma.apiKey.findMany({ where: { userId } }),
      prisma.notification.findMany({ where: { userId } })
    ]);

    return {
      success: true,
      data: {
        user: { ...user, passwordHash: undefined },
        settings: { ...settings, githubPrivateKey: undefined, gitlabToken: undefined, bitbucketToken: undefined, slackWebhook: undefined, teamsWebhook: undefined, jiraToken: undefined, webhookSecret: undefined },
        scans,
        jobs,
        logs,
        apiKeys: apiKeys.map(k => ({ ...k, keyHash: undefined })),
        notifications,
        exportedAt: new Date().toISOString()
      }
    };
  });

  // Import user data
  app.post('/import', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    // Would parse uploaded file and import data
    return { success: true, message: 'Import completed' };
  });

  // Delete account
  app.delete('/account', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;

    await prisma.user.delete({ where: { id: userId } });
    await auditLog(request, 'ACCOUNT_DELETED', 'user', userId);

    return { success: true, message: 'Account deleted' };
  });
}

import { FastifyInstance } from 'fastify';
import { prisma } from '../../shared/database';
import { auditLog } from '../../shared/utils/audit';

const listSchema = {
  type: 'object',
  properties: {
    page: { type: 'number', default: 1 },
    pageSize: { type: 'number', default: 20 },
    type: { type: 'array', items: { type: 'string', enum: ['dockerfile', 'docker_image', 'kubernetes', 'jenkinsfile', 'github_repo', 'dependency', 'logs'] } },
    status: { type: 'array', items: { type: 'string', enum: ['pending', 'running', 'completed', 'failed', 'cancelled'] } },
    search: { type: 'string' },
    sortBy: { type: 'string', enum: ['createdAt', 'duration', 'severity'], default: 'createdAt' },
    sortOrder: { type: 'string', enum: ['asc', 'desc'], default: 'desc' }
  }
};

const batchDeleteSchema = {
  type: 'object',
  required: ['ids'],
  properties: {
    ids: { type: 'array', items: { type: 'string', format: 'uuid' }, minItems: 1 }
  }
};

const exportSchema = {
  type: 'object',
  properties: {
    format: { type: 'string', enum: ['json', 'csv'], default: 'json' },
    type: { type: 'array', items: { type: 'string', enum: ['dockerfile', 'docker_image', 'kubernetes', 'jenkinsfile', 'github_repo', 'dependency', 'logs'] } },
    status: { type: 'array', items: { type: 'string', enum: ['pending', 'running', 'completed', 'failed', 'cancelled'] } },
    search: { type: 'string' }
  }
};

export async function scansRoutes(app: FastifyInstance) {
  // List scans with pagination and filters
  app.get('/', {
    preHandler: [app.authenticate],
    schema: { querystring: listSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { page, pageSize, type, status, search, sortBy, sortOrder } = request.query as any;

    const where: any = { userId };
    if (type?.length) where.type = { in: type };
    if (status?.length) where.status = { in: status };
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { targetValue: { contains: search, mode: 'insensitive' } },
        { id: { contains: search, mode: 'insensitive' } }
      ];
    }

    const [scans, total] = await Promise.all([
      prisma.scan.findMany({
        where,
        orderBy: { [sortBy]: sortOrder },
        take: pageSize,
        skip: (page - 1) * pageSize,
        include: {
          findings: {
            select: { severity: true },
            where: { status: 'open' }
          }
        }
      }),
      prisma.scan.count({ where })
    ]);

    const data = scans.map((scan: any) => ({
      ...scan,
      summary: {
        totalFindings: scan.findings?.length || 0,
        critical: scan.findings?.filter((f: any) => f.severity === 'critical').length || 0,
        high: scan.findings?.filter((f: any) => f.severity === 'high').length || 0,
        medium: scan.findings?.filter((f: any) => f.severity === 'medium').length || 0,
        low: scan.findings?.filter((f: any) => f.severity === 'low').length || 0,
        info: scan.findings?.filter((f: any) => f.severity === 'info').length || 0
      },
      duration: null // job relation removed
    }));

    return {
      success: true,
      data: {
        scans: data,
        total,
        totalPages: Math.ceil(total / pageSize),
        page,
        pageSize
      }
    };
  });

  // Get single scan with findings
  app.get('/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({
      where: { id },
      include: {
        findings: { orderBy: [{ severity: 'desc' }, { createdAt: 'desc' }] }
      }
    });

    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    return { success: true, data: scan };
  });

  // Delete scan
  app.delete('/:id', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { id } = request.params as { id: string };

    const scan = await prisma.scan.findUnique({ where: { id } });
    if (!scan || scan.userId !== userId) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Scan not found', statusCode: 404 } });
    }

    await prisma.scan.delete({ where: { id } });
    await auditLog(request, 'SCAN_DELETED', 'scan', id);
    return { success: true, message: 'Scan deleted' };
  });

  // Batch delete
  app.delete('/batch', {
    preHandler: [app.authenticate],
    schema: { body: batchDeleteSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { ids } = request.body as { ids: string[] };

    const scans = await prisma.scan.findMany({
      where: { id: { in: ids }, userId },
      select: { id: true }
    });

    if (scans.length === 0) {
      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'No scans found', statusCode: 404 } });
    }

    await prisma.scan.deleteMany({ where: { id: { in: ids }, userId } });
    await auditLog(request, 'SCANS_BATCH_DELETED', 'scan', undefined, { count: scans.length, ids: scans.map(s => s.id) });

    return { success: true, message: `Deleted ${scans.length} scans`, data: { deleted: scans.length } };
  });

  // Export scans
  app.post('/export', {
    preHandler: [app.authenticate],
    schema: { body: exportSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { format, type, status, search } = request.body as { format?: string; type?: string[]; status?: string[]; search?: string };

    const where: any = { userId };
    if (type?.length) where.type = { in: type };
    if (status?.length) where.status = { in: status };
    if (search) {
      where.OR = [
        { name: { contains: search, mode: 'insensitive' } },
        { targetValue: { contains: search, mode: 'insensitive' } },
        { id: { contains: search, mode: 'insensitive' } }
      ];
    }

    const scans = await prisma.scan.findMany({
      where,
      orderBy: { createdAt: 'desc' },
      include: { findings: { select: { severity: true, type: true, title: true } } }
    });

    return { success: true, data: scans };
  });

  // Get scan stats
  app.get('/stats', {
    preHandler: [app.authenticate]
  }, async (request, reply) => {
    const userId = (request as any).user.userId;

    const [total, byType, byStatus, recent] = await Promise.all([
      prisma.scan.count({ where: { userId } }),
      prisma.scan.groupBy({ by: ['type'], where: { userId }, _count: true }),
      prisma.scan.groupBy({ by: ['status'], where: { userId }, _count: true }),
      prisma.scan.findMany({
        where: { userId },
        orderBy: { createdAt: 'desc' },
        take: 5,
        select: { id: true, targetValue: true, type: true, status: true, createdAt: true }
      })
    ]);

    return {
      success: true,
      data: {
        total,
        byType: byType.map(t => ({ type: t.type, count: t._count })),
        byStatus: byStatus.map(s => ({ status: s.status, count: s._count })),
        recent
      }
    };
  });
}

import 'dotenv/config';
import Fastify from 'fastify';
import { fastifyCors } from '@fastify/cors';
import { fastifyHelmet } from '@fastify/helmet';
import { fastifyJwt } from '@fastify/jwt';
import { fastifyMultipart } from '@fastify/multipart';
import { fastifyRateLimit } from '@fastify/rate-limit';
import { fastifyWebsocket } from '@fastify/websocket';
import pino from 'pino';

import { config } from './shared/config';
import { prisma } from './shared/database';
import { registerRoutes } from './modules/routes';
import { initializeQueue, shutdownQueue } from './shared/queue';
import { initializeWebSocket } from './shared/websocket';
import { logger } from './shared/utils/logger';

async function bootstrap() {
  const app = Fastify({
    logger: config.NODE_ENV === 'development' ? {
      transport: {
        target: 'pino-pretty',
        options: { colorize: true, translateTime: 'HH:MM:ss Z', ignore: 'pid,hostname' }
      }
    } : true
  });

  // Security plugins
  await app.register(fastifyHelmet, {
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'", "'unsafe-inline'"],
        styleSrc: ["'self'", "'unsafe-inline'"],
        imgSrc: ["'self'", 'data:', 'https:'],
        connectSrc: ["'self'", 'ws:', 'wss:']
      }
    }
  });

  await app.register(fastifyCors, {
    origin: config.CORS_ORIGIN,
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS']
  });

  await app.register(fastifyRateLimit, {
    max: config.RATE_LIMIT_MAX,
    timeWindow: config.RATE_LIMIT_WINDOW,
    keyGenerator: (req) => req.ip
  });

  // Auth plugin
  await app.register(fastifyJwt, {
    secret: config.JWT_SECRET,
    sign: { expiresIn: config.JWT_EXPIRES_IN },
    verify: { algorithms: ['HS256'] }
  });

  app.decorate('authenticate', async (request: any, reply: any) => {
    try {
      await request.jwtVerify();
    } catch (err) {
      reply.code(401).send({ success: false, error: { code: 'UNAUTHORIZED', message: 'Invalid or expired token', statusCode: 401 } });
    }
  });

  // Multipart for file uploads
  await app.register(fastifyMultipart, {
    limits: {
      fileSize: config.MAX_FILE_SIZE,
      files: 10
    }
  });

  // WebSocket for real-time updates
  await app.register(fastifyWebsocket);
  initializeWebSocket(app);

  // Health check
  app.get('/health', async () => ({
    status: 'ok',
    timestamp: new Date().toISOString(),
    version: config.APP_VERSION
  }));

  // Register all routes
  await registerRoutes(app);

  // Error handler
  app.setErrorHandler((error, request, reply) => {
    logger.error({ err: error, url: request.url }, 'Request error');

    if (error.validation) {
      return reply.code(400).send({
        success: false,
        error: {
          code: 'VALIDATION_ERROR',
          message: 'Invalid request data',
          details: error.validation,
          statusCode: 400
        }
      });
    }

    const statusCode = error.statusCode || 500;
    reply.code(statusCode).send({
      success: false,
      error: {
        code: error.code || 'INTERNAL_ERROR',
        message: error.message || 'Internal server error',
        statusCode
      }
    });
  });

  // 404 handler
  app.setNotFoundHandler((request, reply) => {
    reply.code(404).send({
      success: false,
      error: { code: 'NOT_FOUND', message: `Route ${request.method} ${request.url} not found`, statusCode: 404 }
    });
  });

  // Graceful shutdown
  const shutdown = async (signal: string) => {
    logger.info({ signal }, 'Shutting down...');
    await shutdownQueue();
    await app.close();
    await prisma.$disconnect();
    process.exit(0);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  try {
    // Initialize database
    await prisma.$connect();
    logger.info('Database connected');

    // Initialize job queue
    await initializeQueue();
    logger.info('Job queue initialized');

    // Start server
    await app.listen({ port: config.PORT, host: config.HOST });
    logger.info(`Server running on http://${config.HOST}:${config.PORT}`);
  } catch (err) {
    logger.error(err, 'Failed to start server');
    process.exit(1);
  }
}

bootstrap();

import { config } from '../config';
import { prisma } from '../database';
import { logger } from './logger';
import { FastifyRequest, FastifyReply } from 'fastify';

export interface JWTPayload {
  sub: string;
  email: string;
  role: string;
  iat: number;
  exp: number;
}

import bcrypt from 'bcryptjs';

export async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, config.BCRYPT_ROUNDS);
}

export async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}

export async function verifyToken(token: string): Promise<JWTPayload> {
  const jwt = await import('jsonwebtoken');
  return jwt.verify(token, config.JWT_SECRET) as JWTPayload;
}

export function generateTokens(user: { id: string; email: string; role: string }): { accessToken: string; refreshToken: string } {
  const jwt = require('jsonwebtoken');
  const accessToken = jwt.sign(
    { sub: user.id, email: user.email, role: user.role },
    config.JWT_SECRET,
    { expiresIn: config.JWT_EXPIRES_IN }
  );
  const refreshToken = jwt.sign(
    { sub: user.id, type: 'refresh' },
    config.JWT_SECRET,
    { expiresIn: config.JWT_REFRESH_EXPIRES_IN }
  );
  return { accessToken, refreshToken };
}

export async function authenticateRequest(request: FastifyRequest): Promise<JWTPayload | null> {
  try {
    const authHeader = request.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return null;
    }
    const token = authHeader.slice(7);
    return await verifyToken(token);
  } catch {
    return null;
  }
}

export async function getCurrentUser(request: FastifyRequest) {
  const payload = await authenticateRequest(request);
  if (!payload) return null;

  const user = await prisma.user.findUnique({
    where: { id: payload.sub },
    select: {
      id: true,
      email: true,
      name: true,
      avatarUrl: true,
      role: true,
      theme: true,
      sidebarCollapsed: true,
      language: true,
      emailNotifications: true,
      inAppNotifications: true,
      notifyScanComplete: true,
      notifyScanFailed: true,
      notifyVulnFound: true,
      notifyJobChange: true,
      createdAt: true,
      lastLoginAt: true
    }
  });

  return user;
}

export function requireAuth(request: FastifyRequest, reply: FastifyReply) {
  return async () => {
    const payload = await authenticateRequest(request);
    if (!payload) {
      reply.code(401).send({
        success: false,
        error: { code: 'UNAUTHORIZED', message: 'Authentication required', statusCode: 401 }
      });
      return null;
    }
    return payload;
  };
}

export function requireRole(...roles: string[]) {
  return async (request: FastifyRequest, reply: FastifyReply) => {
    const payload = await authenticateRequest(request);
    if (!payload || !roles.includes(payload.role)) {
      reply.code(403).send({
        success: false,
        error: { code: 'FORBIDDEN', message: 'Insufficient permissions', statusCode: 403 }
      });
      return null;
    }
    return payload;
  };
}

import { FastifyInstance } from 'fastify';
import { prisma } from '../../shared/database';
import { getAIProvider } from '../../shared/ai';
import { auditLog } from '../../shared/utils/audit';

const askSchema = {
  type: 'object',
  required: ['prompt'],
  properties: {
    prompt: { type: 'string', minLength: 1, maxLength: 10000 },
    context: { type: 'string' },
    model: { type: 'string' },
    temperature: { type: 'number', minimum: 0, maximum: 2 },
    maxTokens: { type: 'number' },
    systemPrompt: { type: 'string' }
  }
};

const fixSchema = {
  type: 'object',
  required: ['code', 'finding'],
  properties: {
    code: { type: 'string', minLength: 1 },
    language: { type: 'string' },
    finding: {
      type: 'object',
      required: ['type', 'severity', 'title', 'description'],
      properties: {
        type: { type: 'string' },
        severity: { type: 'string' },
        title: { type: 'string' },
        description: { type: 'string' },
        file: { type: 'string' },
        line: { type: 'number' },
        ruleId: { type: 'string' }
      }
    },
    context: { type: 'string' }
  }
};

const explainSchema = {
  type: 'object',
  required: ['code'],
  properties: {
    code: { type: 'string', minLength: 1 },
    language: { type: 'string' },
    focus: { type: 'string' }
  }
};

export async function aiRoutes(app: FastifyInstance) {
  // Ask AI
  app.post('/ask', {
    preHandler: [app.authenticate],
    schema: { body: askSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { prompt, context, model, temperature, maxTokens, systemPrompt } = request.body as { prompt: string; context?: string; model?: string; temperature?: number; maxTokens?: number; systemPrompt?: string };

    try {
      const provider = getAIProvider();
      const response = await provider.complete({
        prompt,
        context: context ? { additional: context } : undefined,
        model,
        temperature,
        maxTokens,
        systemPrompt
      });

      await auditLog(request, 'AI_ASK', 'ai', undefined, { promptLength: prompt.length, model: model || 'default' });

      return { success: true, data: response };
    } catch (error: any) {
      return reply.code(500).send({ success: false, error: { code: 'AI_ERROR', message: error.message, statusCode: 500 } });
    }
  });

  // Generate fix for finding
  app.post('/fix', {
    preHandler: [app.authenticate],
    schema: { body: fixSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { code, language, finding, context } = request.body as { code: string; language?: string; finding: any; context?: string };

    try {
      const provider = getAIProvider();
      const fixPrompt = `You are a security expert. Generate a fix for the following security issue.

Finding:
- Type: ${finding.type}
- Severity: ${finding.severity}
- Title: ${finding.title}
- Description: ${finding.description}
${finding.file ? `- File: ${finding.file}` : ''}
${finding.line ? `- Line: ${finding.line}` : ''}
${finding.ruleId ? `- Rule: ${finding.ruleId}` : ''}

Code to fix:
\`\`\`${language || ''}
${code}
\`\`\`

${context ? `Additional context: ${context}` : ''}

Provide a JSON response with:
{
  "explanation": "Brief explanation of the fix",
  "patch": "Unified diff format patch",
  "confidence": 0-100,
  "steps": ["Step 1", "Step 2"]
}`;

      const response = await provider.complete({
        prompt: fixPrompt,
        systemPrompt: 'You are a security expert that generates safe, minimal fixes for security vulnerabilities. Always respond with valid JSON.',
        temperature: 0.2,
        maxTokens: 4096
      });

      await auditLog(request, 'AI_FIX_GENERATED', 'ai', undefined, { findingType: finding.type, severity: finding.severity });

      return { success: true, data: response };
    } catch (error: any) {
      return reply.code(500).send({ success: false, error: { code: 'AI_ERROR', message: error.message, statusCode: 500 } });
    }
  });

  // Explain code
  app.post('/explain', {
    preHandler: [app.authenticate],
    schema: { body: explainSchema }
  }, async (request, reply) => {
    const userId = (request as any).user.userId;
    const { code, language, focus } = request.body as { code: string; language?: string; focus?: string };

    try {
      const provider = getAIProvider();
      const explainPrompt = `Explain the following ${language || 'code'} code${focus ? ` with focus on: ${focus}` : ''}:

\`\`\`${language || ''}
${code}
\`\`\`

