import { prisma } from '../../shared/database';
import { hashPassword, verifyPassword, generateTokens, verifyToken } from '../../shared/utils/auth';
import { auditLog } from '../../shared/utils/audit';

const loginSchema = {
  type: 'object',
  required: ['email', 'password'],
  properties: {
    email: { type: 'string', format: 'email' },
    password: { type: 'string', minLength: 8 },
    rememberMe: { type: 'boolean' }
  }
};

const registerSchema = {
  type: 'object',
  required: ['name', 'email', 'password'],
  properties: {
    name: { type: 'string', minLength: 2, maxLength: 100 },
    email: { type: 'string', format: 'email' },
    password: { type: 'string', minLength: 8, maxLength: 128 }
  }
};

const refreshSchema = {
  type: 'object',
  required: ['refreshToken'],
  properties: {
    refreshToken: { type: 'string' }
  }
};

const changePasswordSchema = {
  type: 'object',
  required: ['currentPassword', 'newPassword'],
  properties: {
    currentPassword: { type: 'string' },
    newPassword: { type: 'string', minLength: 8, maxLength: 128 }
  }
};

export async function authRoutes(app: FastifyInstance) {
  // Login
  app.post('/login', {
    schema: {
      body: loginSchema
    }
  }, async (request, reply) => {
    const { email, password, rememberMe } = request.body as { email: string; password: string; rememberMe?: boolean };

    const user = await prisma.user.findUnique({ where: { email } });
    if (!user) {
      await auditLog(request, 'LOGIN_FAILED', 'user', undefined, { email, reason: 'user_not_found' });
      return reply.code(401).send({ success: false, error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password', statusCode: 401 } });
    }

    const valid = await verifyPassword(password, user.passwordHash);
    if (!valid) {
      await auditLog(request, 'LOGIN_FAILED', 'user', user.id, { reason: 'invalid_password' });
      return reply.code(401).send({ success: false, error: { code: 'INVALID_CREDENTIALS', message: 'Invalid email or password', statusCode: 401 } });
    }

    const tokens = generateTokens({ id: user.id, email: user.email, role: user.role });
    const accessToken = tokens.accessToken;
    const refreshToken = tokens.refreshToken;

    await prisma.user.update({
