import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  Mail,
  Lock,
  User,
  Eye,
  EyeOff,
  Github,
  Gitlab,
  AlertCircle,
  Loader2,
  Shield
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

export function Register() {
  const { loginWithTokens } = useAuth();
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [terms, setTerms] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [passwordStrength, setPasswordStrength] = useState(0);

  const checkPasswordStrength = (pwd: string) => {
    let strength = 0;
    if (pwd.length >= 8) strength++;
    if (pwd.length >= 12) strength++;
    if (/[A-Z]/.test(pwd)) strength++;
    if (/[a-z]/.test(pwd)) strength++;
    if (/[0-9]/.test(pwd)) strength++;
    if (/[^A-Za-z0-9]/.test(pwd)) strength++;
    setPasswordStrength(strength);
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!name.trim()) newErrors.name = 'Name is required';
    else if (name.trim().length < 2) newErrors.name = 'Name must be at least 2 characters';
    if (!email.trim()) newErrors.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = 'Invalid email format';
    if (!password) newErrors.password = 'Password is required';
    else if (password.length < 8) newErrors.password = 'Password must be at least 8 characters';
    else if (passwordStrength < 3) newErrors.password = 'Password is too weak';
    if (password !== confirmPassword) newErrors.confirmPassword = 'Passwords do not match';
    if (!terms) newErrors.terms = 'You must accept the terms and conditions';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setLoading(true);
    try {
      const response = await authApi.register({ name: name.trim(), email: email.trim(), password });
      if (response.data.success) {
        loginWithTokens(response.data.data.user, response.data.data.accessToken, response.data.data.refreshToken);
        toast.success('Account created successfully!');
        navigate('/dashboard');
      } else {
        toast.error(response.data.error?.message || 'Registration failed');
        if (response.data.error?.details) {
          setErrors(response.data.error.details);
        }
      }
    } catch (err: any) {
      toast.error(err.response?.data?.error?.message || 'Registration failed');
      console.error(err);
    } finally {
      setLoading(false);
    }

import React, { useState, useCallback, useEffect } from 'react';
import {
  History,
  Search,
  Download,
  Trash2,
  RefreshCw,
  ChevronDown,
  ChevronUp,
  Calendar,
  Container,
  FileCode,
  GitBranch,
  Package,
  Server,
  CheckCircle,
  XCircle,
  Clock,
  Eye
} from 'lucide-react';
import { scansApi } from '../services/api';
import { Scan, ScanType, ScanStatus } from '@devsecops/shared/types';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';
import { formatDistanceToNow } from 'date-fns';

const TYPE_ICONS: Record<ScanType, React.ComponentType<any>> = {
  dockerfile: FileCode,
  docker_image: Container,
  kubernetes: GitBranch,
  jenkinsfile: Server,
  github_repo: GitBranch,
  logs: FileCode,
  dependency: Package
} as Record<ScanType, React.ComponentType<any>>;

const TYPE_LABELS: Record<ScanType, string> = {
  dockerfile: 'Dockerfile Fix',
  docker_image: 'Image Scan',
  kubernetes: 'K8s YAML',
  jenkinsfile: 'Jenkins',
  github_repo: 'GitHub Security',
  logs: 'Log Investigation',
  dependency: 'Dependency Radar'
} as Record<ScanType, string>;

const STATUS_COLORS: Record<ScanStatus, { text: string; bg: string }> = {
  pending: { text: 'text-accent-yellow', bg: 'bg-accent-yellow/10' },
  running: { text: 'text-accent-blue', bg: 'bg-accent-blue/10' },
  completed: { text: 'text-accent-green', bg: 'bg-accent-green/10' },
  failed: { text: 'text-severity-critical', bg: 'bg-severity-critical/10' },
  cancelled: { text: 'text-foreground-muted', bg: 'bg-background-tertiary' }
};

export function ScanHistory() {
  const [scans, setScans] = useState<Scan[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalCount, setTotalCount] = useState(0);
  const [pageSize] = useState(20);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string[]>([]);
  const [filterStatus, setFilterStatus] = useState<string[]>([]);
  const [sortBy, setSortBy] = useState<'createdAt' | 'duration' | 'severity'>('createdAt');
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [selectedScans, setSelectedScans] = useState<string[]>([]);
  const [expandedScan, setExpandedScan] = useState<string | null>(null);

  const loadScans = useCallback(async () => {
    setLoading(true);
    try {
      const response = await scansApi.list({
        page,
        pageSize,
        search: searchQuery.trim() || undefined
      });
      if (response.data.success) {
        setScans(response.data.data.scans);
        setTotalPages(response.data.data.totalPages);
        setTotalCount(response.data.data.total);
      }
    } catch (err) {
      toast.error('Failed to load scan history');
      console.error(err);
    } finally {
      setLoading(false);
    }
  }, [page, pageSize, filterType, filterStatus, searchQuery, sortBy, sortOrder]);

  useEffect(() => {
    loadScans();
  }, [loadScans]);

  const handleDelete = async (id: string) => {
    try {
      const response = await scansApi.delete(id);
      if (response.data.success) {
        setScans(prev => prev.filter(s => s.id !== id));
        setSelectedScans(prev => prev.filter(s => s !== id));
        toast.success('Scan deleted');
      } else {
        toast.error(response.data.error?.message || 'Delete failed');
      }
    } catch (err) {
      toast.error('Failed to delete');
      console.error(err);
    }
  };

  const handleBatchDelete = async () => {
    if (selectedScans.length === 0) return;
    try {
      const response = await scansApi.batchDelete(selectedScans);
      if (response.data.success) {
        setScans(prev => prev.filter(s => !selectedScans.includes(s.id)));
        setSelectedScans([]);
        toast.success(`Deleted ${selectedScans.length} scans`);
      } else {
        toast.error(response.data.error?.message || 'Batch delete failed');
      }
    } catch (err) {
      toast.error('Failed to delete scans');
      console.error(err);
    }
  };

  const handleExport = async (format: 'json' | 'csv') => {
    try {
      const response = await scansApi.export({
        format,
        type: filterType.length > 0 ? filterType : undefined,
        status: filterStatus.length > 0 ? filterStatus : undefined,
        search: searchQuery.trim() || undefined
      });
      if (response.data.success) {
        const blob = new Blob([JSON.stringify(response.data.data, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `scan-history-${new Date().toISOString().split('T')[0]}.${format}`;
        a.click();
        URL.revokeObjectURL(url);
        toast.success('Export downloaded');
      }
    } catch (err) {
      toast.error('Export failed');
      console.error(err);
    }
  };

  const toggleSelect = (id: string) => {
    setSelectedScans(prev =>
      prev.includes(id) ? prev.filter(s => s !== id) : [...prev, id]
    );
  };

  const toggleExpand = (id: string) => {
    setExpandedScan(prev => prev === id ? null : id);
  };

  const allSelected = scans.length > 0 && selectedScans.length === scans.length;

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Scan History</h1>
          <p className="text-foreground-secondary mt-1">
            View and manage all your security scans
          </p>
        </div>
        <div className="flex gap-2">
          <button className="btn-secondary" onClick={loadScans}>
            <RefreshCw className="w-4 h-4" />
            Refresh
          </button>
          <button className="btn-secondary" onClick={() => handleExport('json')}>
            <Download className="w-4 h-4" />
            Export JSON
          </button>
        </div>
      </div>

      {/* Filters */}
      <div className="card">
        <div className="flex flex-col lg:flex-row gap-3 items-start lg:items-center">
          <div className="relative flex-1 min-w-0">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by name, ID, or target..."
              className="input pl-10"
            />
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            <select
              className="input w-auto py-2"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
            >
              <option value="createdAt">Sort: Date</option>
              <option value="duration">Sort: Duration</option>
              <option value="severity">Sort: Severity</option>
            </select>
            <button
              className="btn-secondary px-3 py-2"
              onClick={() => setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc')}
            >
              {sortOrder === 'asc' ? '↑' : '↓'}
            </button>
          </div>
        </div>

        <div className="flex flex-wrap gap-2 mt-3">
          {(Object.keys(TYPE_LABELS) as ScanType[]).map(type => (
            <button
              key={type}
              className={clsx(
                'px-3 py-1.5 rounded-lg text-sm transition-colors flex items-center gap-1.5',
                filterType.includes(type)
                  ? 'bg-accent-blue/20 text-accent-blue border border-accent-blue/30'
                  : 'bg-background-tertiary text-foreground-secondary'
              )}
              onClick={() => {
                setFilterType(prev =>
                  prev.includes(type) ? prev.filter(t => t !== type) : [...prev, type]
                );
                setPage(1);
              }}
            >
              {React.createElement(TYPE_ICONS[type], { className: 'w-3.5 h-3.5' })}
              {TYPE_LABELS[type]}
            </button>
          ))}
          {(['pending', 'running', 'completed', 'failed'] as ScanStatus[]).map(status => (
            <button
              key={status}
              className={clsx(
                'px-3 py-1.5 rounded-lg text-sm transition-colors capitalize',
                filterStatus.includes(status)
                  ? 'bg-accent-blue/20 text-accent-blue border border-accent-blue/30'
                  : 'bg-background-tertiary text-foreground-secondary'
              )}
              onClick={() => {
                setFilterStatus(prev =>
                  prev.includes(status) ? prev.filter(s => s !== status) : [...prev, status]
                );
                setPage(1);
              }}
            >
              {status}
            </button>
          ))}
        </div>

        {selectedScans.length > 0 && (
          <div className="mt-3 flex items-center gap-2 p-2 bg-accent-blue/10 border border-accent-blue/20 rounded-lg">
            <span className="text-sm text-accent-blue font-medium">{selectedScans.length} selected</span>
            <button className="btn-secondary text-sm" onClick={handleBatchDelete}>
              <Trash2 className="w-3.5 h-3.5" />
              Delete Selected
            </button>
            <button className="btn-secondary text-sm" onClick={() => setSelectedScans([])}>
              Clear
            </button>
          </div>
        )}
      </div>

      {/* Results */}
      {loading ? (
        <div className="flex items-center justify-center h-64">
          <div className="flex flex-col items-center gap-3">
            <div className="w-8 h-8 border-2 border-accent-blue/30 border-t-accent-blue rounded-full animate-spin" />
            <p className="text-foreground-secondary">Loading scans...</p>
          </div>
        </div>
      ) : scans.length === 0 ? (
        <div className="card text-center py-16">
          <History className="w-12 h-12 mx-auto text-foreground-muted mb-4" />
          <p className="text-foreground-secondary">No scans found</p>
          <p className="text-sm text-foreground-muted mt-1">Try adjusting your filters</p>
        </div>
      ) : (
        <>
          <div className="card p-0 overflow-hidden">
            {/* Header row */}
            <div className="hidden md:grid grid-cols-12 gap-4 px-4 py-3 border-b border-border text-sm text-foreground-secondary">
              <div className="col-span-1">
                <input
                  type="checkbox"
                  checked={allSelected}
                  onChange={() => {
                    if (allSelected) setSelectedScans([]);
                    else setSelectedScans(scans.map(s => s.id));
                  }}
                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
                />
              </div>
              <div className="col-span-3">Scan</div>
              <div className="col-span-2">Type</div>
              <div className="col-span-2">Status</div>
              <div className="col-span-2">Findings</div>
              <div className="col-span-1">Duration</div>
              <div className="col-span-1">Actions</div>
            </div>

            <div className="divide-y divide-border">
              {scans.map(scan => {
                const TypeIcon = TYPE_ICONS[scan.type];
                const statusColor = STATUS_COLORS[scan.status];
                const totalFindings = scan.summary?.totalFindings || 0;
                return (
                  <div key={scan.id} className="hover:bg-background-tertiary/30 transition-colors">
                    <div className="grid grid-cols-1 md:grid-cols-12 gap-4 px-4 py-3 items-center">
                      <div className="col-span-1">
                        <input
                          type="checkbox"
                          checked={selectedScans.includes(scan.id)}
                          onChange={() => toggleSelect(scan.id)}
                          className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
                        />
                      </div>
                      <div className="col-span-3 min-w-0">
                        <p className="font-medium text-foreground truncate">{scan.target?.value || 'Unknown'}</p>
                        <p className="text-xs text-foreground-muted font-mono truncate">{scan.id}</p>
                        <p className="text-xs text-foreground-secondary mt-0.5 flex items-center gap-1">
                          <Calendar className="w-3 h-3" />
                          {formatDistanceToNow(new Date(scan.createdAt), { addSuffix: true })}
                        </p>
                      </div>
                      <div className="col-span-2">
                        <span className="badge badge-ghost flex items-center gap-1.5 w-fit">
                          <TypeIcon className="w-3.5 h-3.5" />
                          {TYPE_LABELS[scan.type]}
                        </span>
                      </div>
                      <div className="col-span-2">
                        <span className={clsx('badge flex items-center gap-1.5 w-fit', statusColor.bg, statusColor.text)}>
                          {scan.status === 'completed' && <CheckCircle className="w-3.5 h-3.5" />}
                          {scan.status === 'failed' && <XCircle className="w-3.5 h-3.5" />}
                          {scan.status === 'running' && <Clock className="w-3.5 h-3.5" />}
                          {scan.status === 'pending' && <Clock className="w-3.5 h-3.5" />}
                          <span className="capitalize">{scan.status}</span>
                        </span>
                      </div>
                      <div className="col-span-2">
                        {totalFindings > 0 ? (
                          <div className="flex items-center gap-1 flex-wrap">
                            {scan.summary?.critical > 0 && <span className="badge bg-severity-critical/10 text-severity-critical text-xs">{scan.summary.critical}C</span>}
                            {scan.summary?.high > 0 && <span className="badge bg-severity-high/10 text-severity-high text-xs">{scan.summary.high}H</span>}
                            {scan.summary?.medium > 0 && <span className="badge bg-severity-medium/10 text-severity-medium text-xs">{scan.summary.medium}M</span>}
                            {scan.summary?.low > 0 && <span className="badge bg-severity-low/10 text-severity-low text-xs">{scan.summary.low}L</span>}
                          </div>
                        ) : (
                          <span className="text-foreground-muted text-sm">No findings</span>
                        )}
                      </div>
                      <div className="col-span-1 text-sm text-foreground-secondary">
                        {(scan as any).duration ? `${Math.round((scan as any).duration / 1000)}s` : '-'}
                      </div>
                      <div className="col-span-1 flex items-center gap-1">
                        <button className="btn-icon" onClick={() => toggleExpand(scan.id)}>
                          {expandedScan === scan.id ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
                        </button>
                        <button
                          className="btn-icon text-foreground-muted hover:text-severity-critical"
                          onClick={() => handleDelete(scan.id)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>

                    {expandedScan === scan.id && (
                      <div className="px-4 pb-4 bg-background-tertiary/50 space-y-3">
                        {scan.target && (
                          <div className="text-sm">
                            <span className="text-foreground-secondary">Target: </span>
                            <span className="font-mono text-foreground">{scan.target.value}</span>
                          </div>
                        )}
                        {(scan as any).metadata && Object.keys((scan as any).metadata).length > 0 && (
                          <div className="code-block">
                            <pre className="text-xs"><code>{JSON.stringify(scan.metadata, null, 2)}</code></pre>
                          </div>
                        )}
                        {scan.error && (
                          <div className="p-2 bg-severity-critical/10 border border-severity-critical/20 rounded-lg text-sm text-severity-critical">
                            {scan.error}
                          </div>
                        )}
                        <div className="flex gap-2">
                          <button className="btn-secondary text-sm">
                            <Eye className="w-3.5 h-3.5" />
                            View Details
                          </button>
                          <button
                            className="btn-secondary text-sm"
                            onClick={() => handleExport('json')}
                          >
                            <Download className="w-3.5 h-3.5" />
                            Export
                          </button>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Pagination */}
          <div className="flex items-center justify-between">
            <p className="text-sm text-foreground-secondary">
              Showing {((page - 1) * pageSize) + 1} - {Math.min(page * pageSize, totalCount)} of {totalCount}
            </p>
            <div className="flex items-center gap-2">
              <button
                className="btn-secondary"
                disabled={page <= 1}
                onClick={() => setPage(p => Math.max(1, p - 1))}
              >
                Previous
              </button>
              <span className="text-sm text-foreground-secondary px-2">
                Page {page} of {totalPages}
              </span>
              <button
                className="btn-secondary"
                disabled={page >= totalPages}
                onClick={() => setPage(p => Math.min(totalPages, p + 1))}
              >
                Next
              </button>
            </div>
          </div>
        </>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import {
  Mail,
  Lock,
  Eye,
  EyeOff,
  Github,
  Gitlab,
  AlertCircle,
  Loader2,
  Shield
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

export function Login() {
  const { loginWithTokens } = useAuth();
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [remember, setRemember] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!email.trim()) newErrors.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = 'Invalid email format';
    if (!password) newErrors.password = 'Password is required';
    else if (password.length < 8) newErrors.password = 'Password must be at least 8 characters';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setLoading(true);
    try {
      const response = await authApi.login({ email, password, rememberMe: remember });
      if (response.data.success) {
        loginWithTokens(response.data.data.user, response.data.data.accessToken, response.data.data.refreshToken);
        toast.success('Welcome back!');
        navigate('/dashboard');
      } else {
        toast.error(response.data.error?.message || 'Login failed');
        if (response.data.error?.details) {
          setErrors(response.data.error.details);
        }
      }
    } catch (err: any) {
      toast.error(err.response?.data?.error?.message || 'Login failed');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleOAuthLogin = (provider: 'github' | 'gitlab' | 'bitbucket') => {
    window.location.href = `/api/auth/${provider}`;
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-gradient-to-br from-background via-background-tertiary to-background">
      <div className="w-full max-w-md">
        {/* Logo */}
        <div className="text-center mb-8">
          <Link to="/" className="inline-flex items-center gap-2 text-2xl font-bold text-foreground">
            <Shield className="w-8 h-8 text-accent-blue" />
            <span>DevSecOps AI</span>
          </Link>
        </div>

        {/* Login Card */}
        <div className="card p-8">
          <div className="text-center mb-8">
            <h1 className="text-2xl font-bold text-foreground">Welcome back</h1>
            <p className="text-foreground-secondary mt-2">Sign in to your DevSecOps AI Platform account</p>
          </div>

          {/* Social Login */}
          <div className="space-y-3 mb-6">
            <button
              type="button"
              className="btn-secondary w-full flex items-center justify-center gap-2"
              onClick={() => handleOAuthLogin('github')}
            >
              <Github className="w-5 h-5" />
              Continue with GitHub
            </button>
            <button
              type="button"
              className="btn-secondary w-full flex items-center justify-center gap-2"
              onClick={() => handleOAuthLogin('gitlab')}
            >
              <Gitlab className="w-5 h-5" />
              Continue with GitLab
            </button>
            <button
              type="button"
              className="btn-secondary w-full flex items-center justify-center gap-2"
              onClick={() => handleOAuthLogin('bitbucket')}
            >
              <Bitbucket className="w-5 h-5" />
              Continue with Bitbucket
            </button>
          </div>

          {/* Divider */}
          <div className="relative mb-6">
            <div className="absolute inset-0 flex items-center">
              <div className="w-full border-t border-border" />
            </div>
            <div className="relative flex justify-center text-sm">
              <span className="px-4 bg-background text-foreground-muted">Or continue with email</span>
            </div>
          </div>

          {/* Email/Password Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label htmlFor="email" className="label">Email Address</label>
              <div className="relative">
                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
                <input
                  id="email"
                  type="email"
                  value={email}
                  onChange={(e) => { setEmail(e.target.value); setErrors(prev => ({ ...prev, email: '' })); }}
                  placeholder="you@example.com"
                  className={clsx('input pl-10', errors.email && 'border-severity-critical')}
                  autoComplete="email"
                  disabled={loading}
                />
              </div>
              {errors.email && (
                <p className="text-sm text-severity-critical mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5" />
                  {errors.email}
                </p>
              )}
            </div>

            <div>
              <label htmlFor="password" className="label">Password</label>
              <div className="relative">
                <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
                <input
                  id="password"
                  type={showPassword ? 'text' : 'password'}
                  value={password}
                  onChange={(e) => { setPassword(e.target.value); setErrors(prev => ({ ...prev, password: '' })); }}
                  placeholder="••••••••"
                  className={clsx('input pl-10 pr-10', errors.password && 'border-severity-critical')}
                  autoComplete="current-password"
                  disabled={loading}
                />
                <button
                  type="button"
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-foreground-muted hover:text-foreground"
                  onClick={() => setShowPassword(!showPassword)}
                  disabled={loading}
                >
                  {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
              </div>
              {errors.password && (
                <p className="text-sm text-severity-critical mt-1 flex items-center gap-1">
                  <AlertCircle className="w-3.5 h-3.5" />
                  {errors.password}
                </p>
              )}
            </div>

            <div className="flex items-center justify-between">
              <label className="flex items-center gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={remember}
                  onChange={(e) => setRemember(e.target.checked)}
                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
                  disabled={loading}
                />
                <span className="text-sm text-foreground-secondary">Remember me</span>
              </label>
              <Link to="/forgot-password" className="text-sm text-accent-blue hover:underline">
                Forgot password?
              </Link>
            </div>

            <button
              type="submit"
              className="btn-primary w-full py-3"
              disabled={loading}
            >
              {loading ? (
                <div className="flex items-center justify-center gap-2">
                  <Loader2 className="w-5 h-5 animate-spin" />
                  Signing in...
                </div>
              ) : (
                'Sign In'
              )}
            </button>
          </form>
        </div>

        {/* Footer */}
        <div className="text-center mt-6 text-sm text-foreground-secondary">
          <p>Don't have an account? <Link to="/register" className="text-accent-blue hover:underline font-medium">Sign up</Link></p>
          <p className="mt-2">By signing in, you agree to our <Link to="/terms" className="text-accent-blue hover:underline">Terms of Service</Link> and <Link to="/privacy" className="text-accent-blue hover:underline">Privacy Policy</Link></p>
        </div>

        {/* Demo Credentials Hint */}
        <div className="mt-6 p-4 bg-background-tertiary rounded-lg">
          <p className="text-xs text-foreground-muted text-center">
            <strong>Demo:</strong> Use any email/password (min 8 chars) to test the UI.
            Backend validation will be implemented with real auth.
          </p>
        </div>
      </div>
    </div>
  );
}

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { api } from '../services/api';
import { User, AuthTokens, LoginCredentials, RegisterData } from '@devsecops/shared/types';

interface AuthContextType {
  user: User | null;
  tokens: AuthTokens | null;
  loading: boolean;
  login: (credentials: LoginCredentials) => Promise<void>;
  loginWithTokens: (user: User, accessToken: string, refreshToken: string) => void;
  register: (data: RegisterData) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
  updateUser: (data: Partial<User>) => Promise<void>;
  updateProfile: (data: Partial<User>) => Promise<void>;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [tokens, setTokens] = useState<AuthTokens | null>(null);
  const [loading, setLoading] = useState(true);

  const loadStoredAuth = useCallback(async () => {
    const storedTokens = localStorage.getItem('auth_tokens');
    if (storedTokens) {
      try {
        const parsed = JSON.parse(storedTokens);
        setTokens(parsed);
        api.defaults.headers.common['Authorization'] = `Bearer ${parsed.accessToken}`;
        await refreshUser();
      } catch {
        localStorage.removeItem('auth_tokens');
      }
    }
    setLoading(false);
  }, []);

  const refreshUser = async () => {
    try {
      const response = await api.get('/api/auth/me');
      setUser(response.data.data);
    } catch {
      setUser(null);
      setTokens(null);
      localStorage.removeItem('auth_tokens');
      delete api.defaults.headers.common['Authorization'];
    }
  };

  const login = async (credentials: LoginCredentials) => {
    const response = await api.post('/api/auth/login', credentials);
    const { user: userData, accessToken, refreshToken } = response.data.data;
    const tokensData: AuthTokens = { accessToken, refreshToken };
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
  };

  const register = async (data: RegisterData) => {
    const response = await api.post('/api/auth/register', data);
    const { user: userData, tokens: tokensData } = response.data.data;
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${tokensData.accessToken}`;
  };

  const loginWithTokens = (userData: User, accessToken: string, refreshToken: string) => {
    const tokensData: AuthTokens = { accessToken, refreshToken };
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
  };

  const logout = async () => {
    try {
      await api.post('/api/auth/logout');
    } finally {
      setUser(null);
      setTokens(null);
      localStorage.removeItem('auth_tokens');
      delete api.defaults.headers.common['Authorization'];
    }
  };

  const updateUser = async (data: Partial<User>) => {
    const response = await api.patch('/api/auth/me', data);
    setUser(response.data.data);
  };

  const updateProfile = async (data: Partial<User>) => {
    const response = await api.patch('/api/auth/me', data);
    setUser(response.data.data);
  };

  useEffect(() => {
    loadStoredAuth();
  }, [loadStoredAuth]);

  return (
    <AuthContext.Provider
      value={{
        user,
        tokens,
        loading,
        login,
        loginWithTokens,
        register,
        logout,
        refreshUser,
        updateUser,
        updateProfile,
        isAuthenticated: !!user
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import axios from 'axios';

export const api = axios.create({
  baseURL: '/api',
  headers: {
    'Content-Type': 'application/json'
  },
  withCredentials: true
});

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        const refreshToken = localStorage.getItem('auth_tokens');
        if (refreshToken) {
          const { refreshToken: token } = JSON.parse(refreshToken);
          const response = await axios.post('/api/auth/refresh', { refreshToken: token });
          const { accessToken, refreshToken: newRefreshToken } = response.data.data;

          const newTokens = { accessToken, refreshToken: newRefreshToken };
          localStorage.setItem('auth_tokens', JSON.stringify(newTokens));
          api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;

          return api(originalRequest);
        }
      } catch {
        localStorage.removeItem('auth_tokens');
        delete api.defaults.headers.common['Authorization'];
        window.location.href = '/login';
      }
    }

    return Promise.reject(error);
  }
);

