import React, { useState, useCallback, useRef } from 'react';
import {
  FileSearch,
  Upload,
  Download,
  Copy,
  Trash2,
  Search,
  Filter,
  Sparkles,
  Zap,
  AlertTriangle,
  CheckCircle,
  Clock,
  FileText,
  Server,
  Database,
  Network,
  ArrowRight,
  ChevronDown,
  ChevronUp,
  X,
  RefreshCw,
