211	            Upload, search, and analyze logs with natural language queries
212	          </p>
213	        </div>
214	      </div>
215	
216	      {/* Tabs */}
217	      <div className="tabs">
218	        <button className={clsx('tab', activeTab === 'upload' && 'tab-active')} onClick={() => setActiveTab('upload')}>
219	          <Upload className="w-4 h-4" />
220	          Upload Logs
221	        </button>
222	        <button className={clsx('tab', activeTab === 'search' && 'tab-active')} onClick={() => setActiveTab('search')}>
223	          <Search className="w-4 h-4" />
224	          Search
225	        </button>
226	        <button className={clsx('tab', activeTab === 'investigate' && 'tab-active')} onClick={() => setActiveTab('investigate')}>
227	          <Sparkles className="w-4 h-4" />
228	          AI Investigate
229	        </button>
230	      </div>
231	
232	      {/* Upload Tab */}
233	      {activeTab === 'upload' && (
234	        <>
235	          <div className="card">
236	            <div className="mb-4">
237	              <label className="label">Upload Log Files</label>
238	              <div
239	                className="border-2 border-dashed border-border rounded-lg p-8 text-center hover:border-accent-blue transition-colors relative"
240	                onClick={() => fileInputRef.current?.click()}
241	                onDragOver={(e) => { e.preventDefault(); e.currentTarget.classList.add('border-accent-blue'); }}
242	                onDragLeave={(e) => { e.currentTarget.classList.remove('border-accent-blue'); }}
243	                onDrop={(e) => {
