246	                  if (e.dataTransfer.files.length > 0) {
247	                    handleFileUpload({ target: { files: e.dataTransfer.files } } as any);
248	                  }
249	                }}
250	              >
251	                <input
252	                  ref={fileInputRef}
253	                  type="file"
254	                  accept=".log,.txt,.json,.gz"
255	                  multiple
256	                  onChange={handleFileUpload}
257	                  className="hidden"
258	                />
259	                <Upload className="w-12 h-12 mx-auto text-foreground-muted mb-4" />
260	                <p className="text-foreground">Drag & drop log files here, or click to browse</p>
261	                <p className="text-sm text-foreground-muted mt-1">Supports: .log, .txt, .json, .gz (max 25MB each)</p>
262	                {uploading && (
263	                  <div className="mt-4">
264	                    <div className="progress-bar mx-auto max-w-md">
265	                      <div className="progress-fill bg-accent-blue" style={{ width: `${uploadProgress}%` }} />
266	                    </div>
267	                    <p className="text-sm text-foreground-secondary mt-2">{uploadProgress}%</p>
268	                  </div>
269	                )}
270	              </div>
271	            </div>
