  Github,
  Gitlab,
  AlertCircle,
  Loader2,
  Shield
} from 'lucide-react';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

export function Register() {
  const { loginWithTokens } = useAuth();
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [terms, setTerms] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [passwordStrength, setPasswordStrength] = useState(0);

  const checkPasswordStrength = (pwd: string) => {
    let strength = 0;
    if (pwd.length >= 8) strength++;
    if (pwd.length >= 12) strength++;
    if (/[A-Z]/.test(pwd)) strength++;
    if (/[a-z]/.test(pwd)) strength++;
    if (/[0-9]/.test(pwd)) strength++;
    if (/[^A-Za-z0-9]/.test(pwd)) strength++;
    setPasswordStrength(strength);
  };

  const validate = () => {
    const newErrors: Record<string, string> = {};
    if (!name.trim()) newErrors.name = 'Name is required';
    else if (name.trim().length < 2) newErrors.name = 'Name must be at least 2 characters';
    if (!email.trim()) newErrors.email = 'Email is required';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = 'Invalid email format';
    if (!password) newErrors.password = 'Password is required';
    else if (password.length < 8) newErrors.password = 'Password must be at least 8 characters';
    else if (passwordStrength < 3) newErrors.password = 'Password is too weak';
    if (password !== confirmPassword) newErrors.confirmPassword = 'Passwords do not match';
    if (!terms) newErrors.terms = 'You must accept the terms and conditions';
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validate()) return;

    setLoading(true);
    try {
      const response = await authApi.register({ name: name.trim(), email: email.trim(), password });
      if (response.data.success) {
        loginWithTokens(response.data.data.user, response.data.data.accessToken, response.data.data.refreshToken);
        toast.success('Account created successfully!');
        navigate('/dashboard');
      } else {
        toast.error(response.data.error?.message || 'Registration failed');
        if (response.data.error?.details) {
          setErrors(response.data.error.details);
        }
      }
    } catch (err: any) {
      toast.error(err.response?.data?.error?.message || 'Registration failed');
      console.error(err);
    } finally {
      setLoading(false);
    }

