1	import React, { useEffect, useRef, useCallback } from 'react';
2	import Editor from '@monaco-editor/react';
3	import { Copy, Download, ChevronDown, X, Search, Replace, Settings } from 'lucide-react';
4	import { clsx } from 'clsx';
5	
6	interface CodeEditorProps {
7	  value: string;
8	  onChange: (value: string) => void;
9	  language?: string;
10	  theme?: 'vs-dark' | 'vs-light';
11	  readOnly?: boolean;
12	  minHeight?: number;
13	  maxHeight?: number;
14	  showLineNumbers?: boolean;
15	  showMinimap?: boolean;
16	  wordWrap?: 'on' | 'off' | 'bounded';
17	  tabSize?: number;
18	  placeholder?: string;
19	  onSave?: () => void;
20	  onFormat?: () => void;
21	  fileName?: string;
22	}
23	
24	const DEFAULT_LANGUAGES: Record<string, string> = {
25	  dockerfile: 'dockerfile',
26	  yaml: 'yaml',
27	  yml: 'yaml',
28	  json: 'json',
29	  groovy: 'groovy',
30	  jenkinsfile: 'groovy',
31	  javascript: 'javascript',
32	  typescript: 'typescript',
33	  python: 'python',
34	  go: 'go',
35	  rust: 'rust',
36	  bash: 'shell',
37	  sh: 'shell',
38	  sql: 'sql',
39	};
40	
41	export function CodeEditor({
42	  value,
43	  onChange,
44	  language = 'plaintext',
45	  theme = 'vs-dark',
46	  readOnly = false,
47	  minHeight = 300,
48	  maxHeight = 600,
49	  showLineNumbers = true,
50	  showMinimap = false,
51	  wordWrap = 'on',
52	  tabSize = 2,
53	  placeholder,
54	  onSave,
55	  onFormat,
56	  fileName
57	}: CodeEditorProps) {
58	  const editorRef = useRef<any>(null);
59	  const mountedRef = useRef(false);
60	
61	  const monacoLanguage = DEFAULT_LANGUAGES[language.toLowerCase()] || language;
62	
63	  const handleEditorDidMount = useCallback((editor: any) => {
64	    editorRef.current = editor;
65	    mountedRef.current = true;
66	
67	    // Set up format on save
68	    if (onFormat) {
69	      editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
70	        onFormat();
71	      });
72	    }
73	
74	    // Auto-format on paste
75	    editor.onDidPaste(() => {
76	      setTimeout(() => {
77	        editor.getAction('editor.action.formatDocument')?.run();
78	      }, 0);
79	    });
80	  }, [onFormat]);
81	
82	  const handleEditorWillUnmount = useCallback(() => {
83	    mountedRef.current = false;
84	    editorRef.current = null;
85	  }, []);
86	
87	  const format = useCallback(() => {
88	    editorRef.current?.getAction('editor.action.formatDocument')?.run();
89	  }, []);
90	
91	  const copyContent = useCallback(() => {
92	    navigator.clipboard.writeText(value);
93	  }, [value]);
94	
95	  const downloadContent = useCallback(() => {
96	    const blob = new Blob([value], { type: 'text/plain' });
97	    const url = URL.createObjectURL(blob);
98	    const a = document.createElement('a');
99	    a.href = url;
100	    a.download = fileName || `code.${language}`;
101	    a.click();
102	    URL.revokeObjectURL(url);
103	  }, [value, language, fileName]);
104	
105	  return (
106	    <div className="relative border border-border rounded-lg overflow-hidden bg-background-tertiary">
107	      {/* Toolbar */}
108	      <div className="flex items-center gap-2 px-3 py-2 bg-background-secondary border-b border-border">
109	        <span className="text-xs text-foreground-secondary font-medium uppercase tracking-wider">
110	          {fileName || monacoLanguage}
111	        </span>
112	        <div className="flex-1" />
113	        {!readOnly && (
114	          <>
115	            <button
116	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
117	              onClick={format}
118	              aria-label="Format document"
119	              title="Format (Ctrl+S)"
120	            >
121	              <Settings className="w-4 h-4" />
122	            </button>
123	            <button
124	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
125	              onClick={copyContent}
126	              aria-label="Copy to clipboard"
127	            >
128	              <Copy className="w-4 h-4" />
129	            </button>
130	            <button
131	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
132	              onClick={downloadContent}
133	              aria-label="Download file"
134	            >
135	              <Download className="w-4 h-4" />
136	            </button>
137	          </>
138	        )}
139	        {readOnly && (
140	          <span className="badge badge-info">Read Only</span>
141	        )}
142	      </div>
143	
144	      {/* Editor */}
145	      <Editor
146	        height={`${maxHeight}px`}
147	        minHeight={`${minHeight}px`}
148	        defaultLanguage={monacoLanguage}
149	        defaultValue={value}
150	        onChange={onChange}
151	        onMount={handleEditorDidMount}
152	        onBeforeUnmount={handleEditorWillUnmount}
153	        options={{
154	          theme,
155	          readOnly,
156	          lineNumbers: showLineNumbers ? 'on' : 'off',
157	          minimap: { enabled: showMinimap },
158	          wordWrap,
159	          tabSize,
160	          fontSize: 13,
161	          fontFamily: "'JetBrains Mono', 'Fira Code', monospace",
162	          fontLigatures: true,
163	          renderLineHighlight: 'all',
164	          scrollBeyondLastLine: false,
165	          automaticLayout: true,
166	          bracketPairColorization: { enabled: true },
167	          guides: { bracketPairs: true },
168	          folding: true,
169	          matchBrackets: 'always',
170	          renderWhitespace: 'selection',
171	          smoothScrolling: true,
172	          cursorBlinking: 'smooth',
173	          cursorSmoothCaretAnimation: 'on',
174	          scrollbar: {
175	            vertical: 'auto',
176	            horizontal: 'auto',
177	            useShadows: false,
178	            verticalHasArrows: false,
179	            horizontalHasArrows: false
180	          },
181	          find: { addExtraSpaceOnTop: false },
182	          placeholder: placeholder || '',
183	          ...(readOnly ? { contextmenu: false } : {})
184	        }}
185	      />
186	
187	      {/* Status bar */}
