1	import React, { useRef, useEffect } from 'react';
2	import { User, Settings, LogOut, Moon, Sun, Monitor } from 'lucide-react';
3	import { useAuth } from '../context/AuthContext';
4	import { useTheme } from '../context/ThemeContext';
5	import { User as UserType } from '@devsecops/shared/types';
6	
7	interface UserMenuProps {
8	  user: UserType | null;
9	  onLogout: () => void;
10	  onSettings: () => void;
11	}
12	
13	export function UserMenu({ user, onLogout, onSettings }: UserMenuProps) {
14	  const [open, setOpen] = React.useState(false);
15	  const dropdownRef = useRef<HTMLDivElement>(null);
16	  const { theme, setTheme, resolvedTheme } = useTheme();
17	
18	  useEffect(() => {
19	    function handleClickOutside(event: MouseEvent) {
20	      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
21	        setOpen(false);
22	      }
23	    }
24	    document.addEventListener('mousedown', handleClickOutside);
25	    return () => document.removeEventListener('mousedown', handleClickOutside);
26	  }, []);
27	
28	  return (
29	    <div className="relative" ref={dropdownRef}>
30	      <button
31	        className="flex items-center gap-2 btn-icon p-1.5"
32	        onClick={() => setOpen(!open)}
33	        aria-label="User menu"
34	        aria-expanded={open}
35	      >
36	        {user?.avatarUrl ? (
37	          <img src={user.avatarUrl} alt="" className="w-8 h-8 rounded-full" />
38	        ) : (
39	          <div className="w-8 h-8 rounded-full bg-accent-blue/20 flex items-center justify-center">
40	            <User className="w-4 h-4 text-accent-blue" />
41	          </div>
42	        )}
43	      </button>
44	
45	      {open && (
46	        <div className="dropdown w-56">
47	          <div className="px-4 py-3 border-b border-border">
48	            <div className="flex items-center gap-3">
49	              {user?.avatarUrl ? (
50	                <img src={user.avatarUrl} alt="" className="w-10 h-10 rounded-full" />
51	              ) : (
52	                <div className="w-10 h-10 rounded-full bg-accent-blue/20 flex items-center justify-center">
53	                  <span className="text-lg font-medium text-accent-blue">{user?.name?.[0].toUpperCase()}</span>
54	                </div>
55	              )}
56	              <div className="flex-1 min-w-0">
57	                <p className="font-medium text-foreground truncate">{user?.name}</p>
58	                <p className="text-xs text-foreground-muted truncate">{user?.email}</p>
59	                <span className={`badge ${user?.role === 'admin' ? 'badge-critical' : user?.role === 'engineer' ? 'badge-info' : 'badge-success'}`}>
60	                  {user?.role}
61	                </span>
62	              </div>
63	            </div>
64	          </div>
65	
66	          <div className="py-1">
67	            <button
68	              className="dropdown-item"
69	              onClick={() => { onSettings(); setOpen(false); }}
70	            >
71	              <Settings className="w-4 h-4" />
72	              Settings
73	            </button>
74	            <div className="dropdown-divider" />
75	            <div className="px-4 py-2">
76	              <p className="text-xs font-medium text-foreground-secondary uppercase tracking-wider mb-2">Theme</p>
77	              <div className="grid grid-cols-3 gap-1">
78	                {['light', 'dark', 'system'].map((t) => (
79	                  <button
80	                    key={t}
81	                    className={`py-1.5 px-2 rounded text-xs font-medium transition-colors ${
82	                      theme === t
83	                        ? 'bg-accent-blue/20 text-accent-blue'
84	                        : 'text-foreground-secondary hover:text-foreground hover:bg-background-tertiary'
85	                    }`}
86	                    onClick={() => { setTheme(t as any); setOpen(false); }}
87	                  >
88	                    {t === 'light' && <Sun className="w-4 h-4 mx-auto mb-1" />}
89	                    {t === 'dark' && <Moon className="w-4 h-4 mx-auto mb-1" />}
90	                    {t === 'system' && <Monitor className="w-4 h-4 mx-auto mb-1" />}
91	                    <span className="block capitalize">{t}</span>
92	                  </button>
93	                ))}
94	              </div>
95	            </div>
96	            <div className="dropdown-divider" />
97	            <button
98	              className="dropdown-item text-severity-critical"
99	              onClick={onLogout}
100	            >
101	              <LogOut className="w-4 h-4" />
102	              Sign out
103	            </button>
104	          </div>
105	        </div>
106	      )}
