1	import { useEffect, useRef, useCallback } from 'react';
2	import { useAuth } from '../context/AuthContext';
3	import { Notification, JobProgressUpdate } from '@devsecops/shared/types';
4	
5	interface UseWebSocketOptions {
6	  onNotification?: (notification: Notification) => void;
7	  onJobUpdate?: (update: JobProgressUpdate) => void;
8	  onScanUpdate?: (update: { scanId: string; status: string; progress: number }) => void;
9	}
10	
11	export function useWebSocket(options: UseWebSocketOptions = {}) {
12	  const { tokens, isAuthenticated } = useAuth();
13	  const wsRef = useRef<WebSocket | null>(null);
14	  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
15	  const lastMessageRef = useRef<any>(null);
16	  const reconnectAttempts = useRef(0);
17	  const maxReconnectAttempts = 5;
18	
19	  const connect = useCallback(() => {
20	    if (!isAuthenticated || !tokens) return;
21	
22	    const wsUrl = `${import.meta.env.VITE_WS_URL || 'ws://localhost:3001'}/ws?token=${tokens.accessToken}`;
23	    const ws = new WebSocket(wsUrl);
24	    wsRef.current = ws;
25	
26	    ws.onopen = () => {
27	      console.log('WebSocket connected');
28	      reconnectAttempts.current = 0;
29	      // Subscribe to channels
30	      ws.send(JSON.stringify({
31	        type: 'subscribe',
32	        payload: { channels: ['notifications', 'jobs', 'scans'] }
33	      }));
34	    };
35	
36	    ws.onmessage = (event) => {
37	      try {
38	        const message = JSON.parse(event.data);
39	        lastMessageRef.current = message;
40	
41	        switch (message.type) {
42	          case 'notification':
43	            options.onNotification?.(message.payload);
44	            break;
45	          case 'job_update':
46	            options.onJobUpdate?.(message.payload);
47	            break;
48	          case 'scan_update':
49	            options.onScanUpdate?.(message.payload);
50	            break;
51	        }
52	      } catch (err) {
53	        console.error('WebSocket message parse error:', err);
54	      }
55	    };
56	
57	    ws.onclose = () => {
58	      console.log('WebSocket disconnected');
59	      if (reconnectAttempts.current < maxReconnectAttempts) {
60	        const delay = Math.min(1000 * 2 ** reconnectAttempts.current, 30000);
61	        reconnectTimeoutRef.current = setTimeout(() => {
62	          reconnectAttempts.current++;
63	          connect();
64	        }, delay);
65	      }
66	    };
67	
68	    ws.onerror = (error) => {
69	      console.error('WebSocket error:', error);
70	    };
71	  }, [isAuthenticated, tokens, options]);
72	
73	  useEffect(() => {
74	    if (isAuthenticated && tokens) {
75	      connect();
76	    } else {
77	      wsRef.current?.close();
78	    }
79	
80	    return () => {
81	      if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);
82	      wsRef.current?.close();
83	    };
84	  }, [connect, isAuthenticated, tokens]);
85	
86	  const send = useCallback((message: any) => {
87	    if (wsRef.current?.readyState === WebSocket.OPEN) {
