1	import { useRef, useCallback } from 'react';
2	import Editor from '@monaco-editor/react';
3	import { Copy, Download, Settings } from 'lucide-react';
4	
5	interface CodeEditorProps {
6	  value: string;
7	  onChange: (value: string | undefined) => void;
8	  language?: string;
9	  theme?: 'vs-dark' | 'vs-light';
10	  readOnly?: boolean;
11	  minHeight?: number;
12	  maxHeight?: number;
13	  showLineNumbers?: boolean;
14	  showMinimap?: boolean;
15	  wordWrap?: 'on' | 'off' | 'bounded';
16	  tabSize?: number;
17	  placeholder?: string;
18	  onFormat?: () => void;
19	  fileName?: string;
20	}
21	
22	const DEFAULT_LANGUAGES: Record<string, string> = {
23	  dockerfile: 'dockerfile',
24	  yaml: 'yaml',
25	  yml: 'yaml',
26	  json: 'json',
27	  groovy: 'groovy',
28	  jenkinsfile: 'groovy',
29	  javascript: 'javascript',
30	  typescript: 'typescript',
31	  python: 'python',
32	  go: 'go',
33	  rust: 'rust',
34	  bash: 'shell',
35	  sh: 'shell',
36	  sql: 'sql',
37	};
38	
39	export function CodeEditor({
40	  value,
41	  onChange,
42	  language = 'plaintext',
43	  theme = 'vs-dark',
44	  readOnly = false,
45	  minHeight = 300,
46	  maxHeight = 600,
47	  showLineNumbers = true,
48	  showMinimap = false,
49	  wordWrap = 'on',
50	  tabSize = 2,
51	  placeholder,
52	  onFormat,
53	  fileName
54	}: CodeEditorProps) {
55	  const editorRef = useRef<any>(null);
56	  const mountedRef = useRef(false);
57	
58	  const monacoLanguage = DEFAULT_LANGUAGES[language.toLowerCase()] || language;
59	
60	  const handleEditorDidMount = useCallback((editor: any) => {
61	    editorRef.current = editor;
62	    mountedRef.current = true;
63	
64	    // Set up format on save
65	    if (onFormat) {
66	      editor.addCommand(editor.KeyMod.CtrlCmd | editor.KeyCode.KeyS, () => {
67	        onFormat();
68	      });
69	    }
70	
71	    // Auto-format on paste
72	    editor.onDidPaste(() => {
73	      setTimeout(() => {
74	        editor.getAction('editor.action.formatDocument')?.run();
75	      }, 0);
76	    });
77	  }, [onFormat]);
78	
79	  const handleEditorWillUnmount = useCallback(() => {
80	    mountedRef.current = false;
81	    editorRef.current = null;
82	  }, []);
83	
84	  const format = useCallback(() => {
85	    editorRef.current?.getAction('editor.action.formatDocument')?.run();
86	  }, []);
87	
88	  const copyContent = useCallback(() => {
89	    navigator.clipboard.writeText(value);
90	  }, [value]);
91	
92	  const downloadContent = useCallback(() => {
93	    const blob = new Blob([value], { type: 'text/plain' });
94	    const url = URL.createObjectURL(blob);
95	    const a = document.createElement('a');
96	    a.href = url;
97	    a.download = fileName || `code.${language}`;
98	    a.click();
99	    URL.revokeObjectURL(url);
100	  }, [value, language, fileName]);
101	
102	  return (
103	    <div className="relative border border-border rounded-lg overflow-hidden bg-background-tertiary">
104	      {/* Toolbar */}
105	      <div className="flex items-center gap-2 px-3 py-2 bg-background-secondary border-b border-border">
106	        <span className="text-xs text-foreground-secondary font-medium uppercase tracking-wider">
107	          {fileName || monacoLanguage}
108	        </span>
109	        <div className="flex-1" />
110	        {!readOnly && (
111	          <>
112	            <button
113	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
114	              onClick={format}
115	              aria-label="Format document"
116	              title="Format (Ctrl+S)"
117	            >
118	              <Settings className="w-4 h-4" />
119	            </button>
120	            <button
121	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
122	              onClick={copyContent}
123	              aria-label="Copy to clipboard"
124	            >
125	              <Copy className="w-4 h-4" />
126	            </button>
127	            <button
128	              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
129	              onClick={downloadContent}
130	              aria-label="Download file"
131	            >
132	              <Download className="w-4 h-4" />
133	            </button>
134	          </>
