import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Container,
  ShieldCheck,
  Boxes,
  GitBranch,
  Github,
  FileSearch,
  Radar,
  History,
  AlertTriangle,
  CheckCircle,
  TrendingUp,
  TrendingDown,
  Clock,
  Zap,
  ExternalLink,
  RefreshCw
} from 'lucide-react';
import { scansApi, jobsApi } from '../services/api';
import { Scan, Job } from '@devsecops/shared/types';
import { CardSkeleton } from '../components/LoadingScreen';
import { formatDistanceToNow } from 'date-fns';
import { clsx } from 'clsx';

const QUICK_ACTIONS = [
  { path: '/dockerfile', label: 'Analyze Dockerfile', description: 'Scan & fix Dockerfile issues', icon: Container, color: 'text-accent-blue' },
  { path: '/docker', label: 'Scan Docker Image', description: 'Find vulnerabilities in images', icon: ShieldCheck, color: 'text-accent-green' },
  { path: '/kubernetes', label: 'Kubernetes YAML', description: 'Validate & generate K8s configs', icon: Boxes, color: 'text-accent-purple' },
  { path: '/jenkins', label: 'Jenkins Pipeline', description: 'Fix & generate Jenkinsfiles', icon: GitBranch, color: 'text-accent-yellow' },
  { path: '/github', label: 'GitHub Security', description: 'Scan repos for vulnerabilities', icon: Github, color: 'text-foreground' },
  { path: '/logs', label: 'Investigate Logs', description: 'AI-powered log analysis', icon: FileSearch, color: 'text-accent-cyan' },
  { path: '/dependencies', label: 'Dependency Risk', description: 'Scan & fix vulnerable deps', icon: Radar, color: 'text-accent-purple' },
  { path: '/scans', label: 'Scan History', description: 'View all past scans', icon: History, color: 'text-foreground-muted' },
];

const STATS = [
  { label: 'Total Scans', value: '0', change: '+12%', trend: 'up', icon: CheckCircle, color: 'text-accent-green' },
  { label: 'Vulnerabilities Found', value: '0', change: '+5%', trend: 'up', icon: AlertTriangle, color: 'text-severity-critical' },
  { label: 'Critical Issues', value: '0', change: '-3%', trend: 'down', icon: AlertTriangle, color: 'text-severity-critical' },
  { label: 'Issues Fixed', value: '0', change: '+8%', trend: 'up', icon: Zap, color: 'text-accent-blue' },
];

export function Dashboard() {
  const [stats, setStats] = useState(STATS);
  const [recentScans, setRecentScans] = useState<Scan[]>([]);
  const [recentJobs, setRecentJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      const [scansRes, jobsRes] = await Promise.all([
        scansApi.list({ page: 1, pageSize: 10 }),
        jobsApi.list({ page: 1, pageSize: 10 })
      ]);

      if (scansRes.data.success) {
        setRecentScans(scansRes.data.data?.data || []);
        // Update stats based on actual data
        const allScans = scansRes.data.data?.data || [];
        setStats([
          { ...STATS[0], value: allScans.length.toString() },
          {
            ...STATS[1],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.totalFindings || 0), 0).toString()
          },
          {
            ...STATS[2],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.critical || 0), 0).toString()
          },
          {
            ...STATS[3],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.fixedCount || 0), 0).toString()
          }
        ]);
      }

      if (jobsRes.data.success) {
        setRecentJobs(jobsRes.data.data?.data || []);
      }
    } catch (err) {
      console.error('Failed to load dashboard data', err);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: Job['status']) => {
    switch (status) {
      case 'completed': return 'text-accent-green';
      case 'failed': return 'text-severity-critical';
      case 'running':
      case 'analyzing':
      case 'fixing': return 'text-accent-blue';
      case 'queued': return 'text-foreground-muted';
      default: return 'text-foreground-secondary';
    }
  };

  const getStatusIcon = (status: Job['status']) => {
    switch (status) {
      case 'completed': return <CheckCircle className="w-4 h-4" />;
      case 'failed': return <AlertTriangle className="w-4 h-4" />;
      case 'running':
      case 'analyzing':
      case 'fixing': return <RefreshCw className="w-4 h-4 animate-spin" />;
      case 'queued': return <Clock className="w-4 h-4" />;
      default: return <Clock className="w-4 h-4" />;
    }
  };

  if (loading) {
    return (
      <div className="space-y-6 animate-fade-in">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map(i => <CardSkeleton key={i} />)}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Dashboard</h1>
          <p className="text-foreground-secondary mt-1">Your DevSecOps command center overview</p>
        </div>
        <button className="btn-secondary" onClick={loadDashboardData}>
          <RefreshCw className="w-4 h-4" />
          Refresh
        </button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, index) => (
          <div key={index} className="stat-card">
            <div className="flex items-start justify-between">
              <div>
                <p className="stat-label">{stat.label}</p>
                <p className="stat-value">{stat.value}</p>
                <div className="stat-trend">
                  {stat.trend === 'up' ? (
                    <TrendingUp className="w-4 h-4 text-accent-green" />
                  ) : (
                    <TrendingDown className="w-4 h-4 text-severity-critical" />
                  )}
                  <span className={clsx('font-medium', stat.color)}>{stat.change}</span>
                </div>
              </div>
              <div className={`p-3 rounded-xl bg-background-tertiary ${stat.color.replace('text-', 'bg-')}/10`}>
                <stat.icon className={`w-6 h-6 ${stat.color}`} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Quick Actions & Recent Scans */}
        <div className="lg:col-span-2 space-y-6">
          {/* Quick Actions */}
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Quick Actions</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
              {QUICK_ACTIONS.map((action, i) => {
                const Icon = action.icon;
                return (
                  <Link
                    key={i}
                    to={action.path}
                    className="card p-4 hover:shadow-card-hover transition-shadow group"
                  >
                    <div className={`p-2 rounded-lg bg-background-tertiary ${action.color} mb-3`}>
                      <Icon className="w-5 h-5" />
                    </div>
                    <h3 className="font-medium text-foreground">{action.label}</h3>
                    <p className="text-sm text-foreground-secondary mt-1">{action.description}</p>
                    <div className="mt-3 flex items-center text-accent-blue text-sm group-hover:gap-1 transition-all">
                      <span>Open</span>
                      <ExternalLink className="w-3.5 h-3.5" />
                    </div>
                  </Link>
                );
              })}
            </div>
          </div>

          {/* Recent Scans */}
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Recent Scans</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            {recentScans.length === 0 ? (
              <div className="text-center py-8 text-foreground-secondary">
                <Container className="w-12 h-12 mx-auto mb-3 opacity-50" />
                <p>No scans yet</p>
                <p className="text-sm mt-1">Start by scanning a Dockerfile, image, or repository</p>
                <div className="mt-4 flex gap-2 justify-center">
                  <Link to="/dockerfile" className="btn-primary text-sm">Scan Dockerfile</Link>
                  <Link to="/docker" className="btn-secondary text-sm">Scan Image</Link>
                </div>
              </div>
            ) : (
              <div className="table-container">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Type</th>
                      <th>Target</th>
                      <th>Status</th>
                      <th>Findings</th>
                      <th>Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentScans.map((scan) => (
                      <tr key={scan.id}>
                        <td>
                          <span className="badge badge-info capitalize">{scan.type.replace('_', ' ')}</span>
                        </td>
                        <td className="font-mono text-sm max-w-[200px] truncate">{scan.target?.value || 'Unknown'}</td>
                        <td>
                          <span className={clsx('badge', {
                            'badge-success': scan.status === 'completed',
                            'badge-critical': scan.status === 'failed',
                            'badge-medium': scan.status === 'running',
                            'badge-info': scan.status === 'pending'
                          })}>
                            {scan.status}
                          </span>
                        </td>
                        <td>
                          {scan.summary && (
                            <div className="flex items-center gap-1">
                              {scan.summary.critical > 0 && <span className="badge badge-critical">{scan.summary.critical}</span>}
                              {scan.summary.high > 0 && <span className="badge badge-high">{scan.summary.high}</span>}
                              {scan.summary.medium > 0 && <span className="badge badge-medium">{scan.summary.medium}</span>}
                              {scan.summary.low > 0 && <span className="badge badge-low">{scan.summary.low}</span>}
                              {scan.summary.info > 0 && <span className="badge badge-info">{scan.summary.info}</span>}
                              {(scan.summary.totalFindings || 0) === 0 && <span className="badge badge-success">Clean</span>}
                            </div>
                          )}
                        </td>
                        <td className="text-foreground-secondary">
                          {formatDistanceToNow(new Date(scan.createdAt), { addSuffix: true })}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* Right Column - Recent Jobs */}
        <div className="space-y-6">
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Recent Jobs</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            {recentJobs.length === 0 ? (
              <div className="text-center py-8 text-foreground-secondary">
                <Zap className="w-12 h-12 mx-auto mb-3 opacity-50" />
                <p>No jobs running</p>
                <p className="text-sm mt-1">Jobs appear here when you start scans or fixes</p>
              </div>
            ) : (
              <div className="space-y-3">
                {recentJobs.map((job) => (
                  <div key={job.id} className="flex items-center gap-3 p-3 bg-background-tertiary rounded-lg">
                    <div className={clsx('p-2 rounded-lg', getStatusColor(job.status).replace('text-', 'bg-') + '/10')}>
                      {getStatusIcon(job.status)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-foreground truncate">{job.type.replace('_', ' ')}</p>
                      <p className="text-sm text-foreground-secondary truncate">{job.currentStep || 'Queued'}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-20">
                        <div className="progress-bar">
                          <div
                            className="progress-fill"
                            style={{ width: `${job.progress}%` }}
                          />
                        </div>
                      </div>
                      <span className={clsx('text-sm font-medium', getStatusColor(job.status))}>
                        {job.status}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* System Health */}
          <div className="card">
            <h2 className="text-lg font-semibold text-foreground mb-4">System Health</h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">API Status</p>
                <p className="font-medium text-accent-green flex items-center gap-1">
                  <CheckCircle className="w-4 h-4" /> Operational
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">Job Queue</p>
                <p className="font-medium text-accent-blue flex items-center gap-1">
                  <Clock className="w-4 h-4" /> {recentJobs.filter(j => j.status === 'queued').length} queued
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">Active Scans</p>
                <p className="font-medium text-accent-blue flex items-center gap-1">
                  <Zap className="w-4 h-4" /> {recentJobs.filter(j => ['running', 'analyzing', 'fixing'].includes(j.status)).length} running
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">AI Service</p>
                <p className="font-medium text-accent-green flex items-center gap-1">
                  <CheckCircle className="w-4 h-4" /> Connected
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useRef, useCallback } from 'react';
import Editor from '@monaco-editor/react';
import { Copy, Download, Settings } from 'lucide-react';

interface CodeEditorProps {
  value: string;
  onChange: (value: string | undefined) => void;
  language?: string;
  theme?: 'vs-dark' | 'vs-light';
  readOnly?: boolean;
  maxHeight?: number;
  showLineNumbers?: boolean;
  showMinimap?: boolean;
  wordWrap?: 'on' | 'off' | 'bounded';
  tabSize?: number;
  placeholder?: string;
  onFormat?: () => void;
  fileName?: string;
}

const DEFAULT_LANGUAGES: Record<string, string> = {
  dockerfile: 'dockerfile',
  yaml: 'yaml',
  yml: 'yaml',
  json: 'json',
  groovy: 'groovy',
  jenkinsfile: 'groovy',
  javascript: 'javascript',
  typescript: 'typescript',
  python: 'python',
  go: 'go',
  rust: 'rust',
  bash: 'shell',
  sh: 'shell',
  sql: 'sql',
};

export function CodeEditor({
  value,
  onChange,
  language = 'plaintext',
  theme = 'vs-dark',
  readOnly = false,
  maxHeight = 600,
  showLineNumbers = true,
  showMinimap = false,
  wordWrap = 'on',
  tabSize = 2,
  placeholder,
  onFormat,
  fileName
}: CodeEditorProps) {
  const editorRef = useRef<any>(null);
  const mountedRef = useRef(false);

  const monacoLanguage = DEFAULT_LANGUAGES[language.toLowerCase()] || language;

  const handleEditorDidMount = useCallback((editor: any) => {
    editorRef.current = editor;
    mountedRef.current = true;

    // Set up format on save
    if (onFormat) {
      editor.addCommand(editor.KeyMod.CtrlCmd | editor.KeyCode.KeyS, () => {
        onFormat();
      });
    }

    // Auto-format on paste
    editor.onDidPaste(() => {
      setTimeout(() => {
        editor.getAction('editor.action.formatDocument')?.run();
      }, 0);
    });
  }, [onFormat]);

  const handleEditorWillUnmount = useCallback(() => {
    mountedRef.current = false;
    editorRef.current = null;
  }, []);

  const format = useCallback(() => {
    editorRef.current?.getAction('editor.action.formatDocument')?.run();
  }, []);

  const copyContent = useCallback(() => {
    navigator.clipboard.writeText(value);
  }, [value]);

  const downloadContent = useCallback(() => {
    const blob = new Blob([value], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName || `code.${language}`;
    a.click();
    URL.revokeObjectURL(url);
  }, [value, language, fileName]);

  return (
    <div className="relative border border-border rounded-lg overflow-hidden bg-background-tertiary">
      {/* Toolbar */}
      <div className="flex items-center gap-2 px-3 py-2 bg-background-secondary border-b border-border">
        <span className="text-xs text-foreground-secondary font-medium uppercase tracking-wider">
          {fileName || monacoLanguage}
        </span>
        <div className="flex-1" />
        {!readOnly && (
          <>
            <button
              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
              onClick={format}
              aria-label="Format document"
              title="Format (Ctrl+S)"
            >
              <Settings className="w-4 h-4" />
            </button>
            <button
              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
              onClick={copyContent}
              aria-label="Copy to clipboard"
            >
              <Copy className="w-4 h-4" />
            </button>
            <button
              className="btn-icon p-1.5 text-foreground-secondary hover:text-foreground"
              onClick={downloadContent}
              aria-label="Download file"
            >
              <Download className="w-4 h-4" />
            </button>
          </>
        )}
        {readOnly && (
          <span className="badge badge-info">Read Only</span>
        )}
      </div>

      {/* Editor */}
      <Editor
        height={`${maxHeight}px`}
        defaultLanguage={monacoLanguage}
        defaultValue={value}
        onChange={onChange}
        onMount={handleEditorDidMount}
        options={{
          theme,
          readOnly,
          lineNumbers: showLineNumbers ? 'on' : 'off',
          minimap: { enabled: showMinimap },
          wordWrap,
          tabSize,
          fontSize: 13,
          fontFamily: "'JetBrains Mono', 'Fira Code', monospace",
          fontLigatures: true,
          renderLineHighlight: 'all',
          scrollBeyondLastLine: false,
          automaticLayout: true,
          bracketPairColorization: { enabled: true },
          guides: { bracketPairs: true },
          folding: true,
          matchBrackets: 'always',
          renderWhitespace: 'selection',
          smoothScrolling: true,
          cursorBlinking: 'smooth',
          cursorSmoothCaretAnimation: 'on',
          scrollbar: {
            vertical: 'auto',
            horizontal: 'auto',
            useShadows: false,
            verticalHasArrows: false,
            horizontalHasArrows: false
          },
          find: { addExtraSpaceOnTop: false },
          placeholder: placeholder || '',
          ...(readOnly ? { contextmenu: false } : {})
        }}
      />

      {/* Status bar */}
      <div className="flex items-center gap-4 px-3 py-1.5 bg-background-secondary border-t border-border text-xs text-foreground-muted">
        <span>Ln {value.split('\n').length}, Col 1</span>
        <span>{monacoLanguage}</span>
        <span>Spaces: {tabSize}</span>
        <span>UTF-8</span>
      </div>
    </div>
  );
}

import { useRef, useEffect, useState } from 'react';
import { User, Settings, LogOut, Moon, Sun, Monitor } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';
import { User as UserType } from '@devsecops/shared/types';

interface UserMenuProps {
  user: UserType | null;
  onLogout: () => void;
  onSettings: () => void;
}

export function UserMenu({ user, onLogout, onSettings }: UserMenuProps) {
  const [open, setOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);
  const { theme, setTheme } = useTheme();

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="relative" ref={dropdownRef}>
      <button
        className="flex items-center gap-2 btn-icon p-1.5"
        onClick={() => setOpen(!open)}
        aria-label="User menu"
        aria-expanded={open}
      >
        {user?.avatarUrl ? (
          <img src={user.avatarUrl} alt="" className="w-8 h-8 rounded-full" />
        ) : (
          <div className="w-8 h-8 rounded-full bg-accent-blue/20 flex items-center justify-center">
            <User className="w-4 h-4 text-accent-blue" />
          </div>
        )}
      </button>

      {open && (
        <div className="dropdown w-56">
          <div className="px-4 py-3 border-b border-border">
            <div className="flex items-center gap-3">
              {user?.avatarUrl ? (
                <img src={user.avatarUrl} alt="" className="w-10 h-10 rounded-full" />
              ) : (
                <div className="w-10 h-10 rounded-full bg-accent-blue/20 flex items-center justify-center">
                  <span className="text-lg font-medium text-accent-blue">{user?.name?.[0].toUpperCase()}</span>
                </div>
              )}
              <div className="flex-1 min-w-0">
                <p className="font-medium text-foreground truncate">{user?.name}</p>
                <p className="text-xs text-foreground-muted truncate">{user?.email}</p>
                <span className={`badge ${user?.role === 'admin' ? 'badge-critical' : user?.role === 'engineer' ? 'badge-info' : 'badge-success'}`}>
                  {user?.role}
                </span>
              </div>
            </div>
          </div>

          <div className="py-1">
            <button
              className="dropdown-item"
              onClick={() => { onSettings(); setOpen(false); }}
            >
              <Settings className="w-4 h-4" />
              Settings
            </button>
            <div className="dropdown-divider" />
            <div className="px-4 py-2">
              <p className="text-xs font-medium text-foreground-secondary uppercase tracking-wider mb-2">Theme</p>
              <div className="grid grid-cols-3 gap-1">
                {['light', 'dark', 'system'].map((t) => (
                  <button
                    key={t}
                    className={`py-1.5 px-2 rounded text-xs font-medium transition-colors ${
                      theme === t
                        ? 'bg-accent-blue/20 text-accent-blue'
                        : 'text-foreground-secondary hover:text-foreground hover:bg-background-tertiary'
                    }`}
                    onClick={() => { setTheme(t as any); setOpen(false); }}
                  >
                    {t === 'light' && <Sun className="w-4 h-4 mx-auto mb-1" />}
                    {t === 'dark' && <Moon className="w-4 h-4 mx-auto mb-1" />}
                    {t === 'system' && <Monitor className="w-4 h-4 mx-auto mb-1" />}
                    <span className="block capitalize">{t}</span>
                  </button>
                ))}
              </div>
            </div>
            <div className="dropdown-divider" />
            <button
              className="dropdown-item text-severity-critical"
              onClick={onLogout}
            >
              <LogOut className="w-4 h-4" />
              Sign out
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Outlet, NavLink, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { useTheme } from '../context/ThemeContext';
import {
  LayoutDashboard,
  Container,
  ShieldCheck,
  Boxes,
  GitBranch,
  Github,
  FileSearch,
  Radar,
  History,
  Settings,
  Menu,
  X,
  Sun,
  Moon,
  ChevronDown
} from 'lucide-react';
import { NotificationDropdown } from './NotificationDropdown';
import { UserMenu } from './UserMenu';
import { useWebSocket } from '../hooks/useWebSocket';
import { Notification } from '@devsecops/shared/types';

const SIDEBAR_ITEMS = [
  { path: '/', label: 'Dashboard', icon: LayoutDashboard },
  { path: '/dockerfile', label: 'Dockerfile AI Fixer', icon: Container },
  { path: '/docker', label: 'Docker Image Scanner', icon: ShieldCheck },
  { path: '/kubernetes', label: 'Kubernetes YAML AI', icon: Boxes },
  { path: '/jenkins', label: 'Jenkins AI Assistant', icon: GitBranch },
  { path: '/github', label: 'GitHub Security', icon: Github },
  { path: '/logs', label: 'AI Log Investigation', icon: FileSearch },
  { path: '/dependencies', label: 'Dependency Risk Radar', icon: Radar },
  { path: '/scans', label: 'Scan History', icon: History },
  { path: '/settings', label: 'Settings', icon: Settings }
] as const;

export function Layout() {
  const { user, logout } = useAuth();
  const { resolvedTheme, toggleTheme } = useTheme();
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);

  const { lastMessage: _lastMessage } = useWebSocket({
    onNotification: (notification: Notification) => {
      setNotifications(prev => [notification, ...prev].slice(0, 50));
      setUnreadCount(prev => prev + 1);
    },
    onJobUpdate: (_update) => {
      // Job updates handled by individual pages
    }
  });

  useEffect(() => {
    // Load sidebar collapsed state
    const stored = localStorage.getItem('sidebarCollapsed');
    if (stored) setSidebarCollapsed(JSON.parse(stored));
  }, []);

  useEffect(() => {
    localStorage.setItem('sidebarCollapsed', JSON.stringify(sidebarCollapsed));
  }, [sidebarCollapsed]);

  const handleLogout = async () => {
    await logout();
    navigate('/login');
  };

  return (
    <div className="min-h-screen bg-background flex">
      {/* Mobile sidebar overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Sidebar */}
      <aside
        className={`fixed lg:relative top-0 left-0 z-50 h-screen bg-background-secondary border-r border-border transition-all duration-300 flex flex-col ${
          sidebarCollapsed ? 'w-16' : 'w-64'
        } ${sidebarOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}
        aria-label="Main navigation"
      >
        {/* Logo / Brand */}
        <div className={`flex items-center justify-between h-16 px-4 border-b border-border ${sidebarCollapsed ? 'justify-center' : ''}`}>
          {!sidebarCollapsed && (
            <NavLink to="/" className="flex items-center gap-2 text-foreground font-semibold text-lg" aria-label="DevSecOps AI Platform">
              <Container className="w-6 h-6 text-accent-blue" />
              <span>DevSecOps AI</span>
            </NavLink>
          )}
          <button
            className="lg:hidden btn-icon text-foreground-secondary hover:text-foreground"
            onClick={() => setSidebarOpen(false)}
            aria-label="Close sidebar"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Navigation */}
        <nav className="flex-1 overflow-y-auto p-3 space-y-1" role="navigation" aria-label="Main">
          {SIDEBAR_ITEMS.map((item) => {
            const Icon = item.icon;
            const isActive = window.location.pathname === item.path ||
              (item.path !== '/' && window.location.pathname.startsWith(item.path));
            return (
              <NavLink
                key={item.path}
                to={item.path}
                className={`sidebar-link ${isActive ? 'sidebar-link-active' : ''} ${sidebarCollapsed ? 'justify-center' : ''}`}
                aria-current={isActive ? 'page' : undefined}
                title={sidebarCollapsed ? item.label : undefined}
                onClick={() => setSidebarOpen(false)}
              >
                <Icon className="w-5 h-5 flex-shrink-0" aria-hidden="true" />
                {!sidebarCollapsed && <span>{item.label}</span>}
              </NavLink>
            );
          })}
        </nav>

        {/* Sidebar toggle & user info */}
        <div className={`p-3 border-t border-border ${sidebarCollapsed ? 'items-center justify-center' : ''}`}>
          {!sidebarCollapsed && user && (
            <div className="flex items-center gap-3 p-2 rounded-lg hover:bg-background-tertiary">
              <div className="w-8 h-8 rounded-full bg-accent-blue/20 flex items-center justify-center">
                {user.avatarUrl ? (
                  <img src={user.avatarUrl} alt="" className="w-8 h-8 rounded-full" />
                ) : (
                  <span className="text-sm font-medium text-accent-blue">{user.name[0].toUpperCase()}</span>
                )}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-foreground truncate">{user.name}</p>
                <p className="text-xs text-foreground-muted truncate">{user.email}</p>
              </div>
            </div>
          )}
          <button
            className={`btn-icon w-full ${sidebarCollapsed ? 'mx-auto' : ''}`}
            onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
            aria-label={sidebarCollapsed ? 'Expand sidebar' : 'Collapse sidebar'}
            aria-expanded={!sidebarCollapsed}
          >
            {sidebarCollapsed ? (
              <ChevronDown className="w-5 h-5 rotate-180" />
            ) : (
              <Menu className="w-5 h-5" />
            )}
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0 lg:ml-0">
        {/* Top Header */}
        <header className="sticky top-0 z-30 h-16 bg-background-secondary/80 backdrop-blur-lg border-b border-border flex items-center justify-between px-4 lg:px-6">
          <div className="flex items-center gap-4">
            <button
              className="lg:hidden btn-icon text-foreground-secondary hover:text-foreground"
              onClick={() => setSidebarOpen(true)}
              aria-label="Open sidebar"
            >
              <Menu className="w-5 h-5" />
            </button>
            <h1 className="text-lg font-semibold text-foreground hidden sm:block">
              {SIDEBAR_ITEMS.find(item =>
                window.location.pathname === item.path ||
                (item.path !== '/' && window.location.pathname.startsWith(item.path))
              )?.label || 'Dashboard'}
            </h1>
          </div>

          <div className="flex items-center gap-2">
            {/* Theme Toggle */}
            <button
              className="btn-icon text-foreground-secondary hover:text-foreground relative"
              onClick={toggleTheme}
              aria-label={`Switch to ${resolvedTheme === 'dark' ? 'light' : 'dark'} mode`}
            >
              {resolvedTheme === 'dark' ? (
                <Sun className="w-5 h-5" />
              ) : (
                <Moon className="w-5 h-5" />
              )}
            </button>

            {/* Notifications */}
            <NotificationDropdown
              notifications={notifications}
              unreadCount={unreadCount}
              onMarkRead={(id) => setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n))}
              onMarkAllRead={() => setNotifications(prev => prev.map(n => ({ ...n, read: true })))}
            />

            {/* User Menu */}
            <UserMenu
              user={user}
              onLogout={handleLogout}
              onSettings={() => navigate('/settings')}
            />
          </div>
        </header>

        {/* Page Content */}
        <main className="flex-1 p-4 lg:p-6 overflow-auto">
          <Outlet />
        </main>
      </div>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { DiffChange } from '@devsecops/shared/types';
import { clsx } from 'clsx';

interface DiffViewerProps {
  original: string;
  fixed: string;
  changes: DiffChange[];
  onApplyFixed?: () => void;
  onReset?: () => void;
  showActions?: boolean;
  readOnly?: boolean;
}

export function DiffViewer({
  original,
  fixed,
  changes,
  onApplyFixed,
  onReset,
  showActions = true,
  readOnly = false
}: DiffViewerProps) {
  const [viewMode, setViewMode] = useState('side-by-side');
  const [showLineNumbers, setShowLineNumbers] = useState(true);

  const originalLines = useMemo(() => original.split('\n'), [original]);
  const fixedLines = useMemo(() => fixed.split('\n'), [fixed]);

  const changeMap = useMemo(() => {
    const map = new Map<number, DiffChange>();
    changes.forEach(change => {
      if (change.originalLine) map.set(change.originalLine, change);
      if (change.fixedLine) map.set(change.fixedLine, change);
    });
    return map;
  }, [changes]);

  const getLineClass = (lineNum: number, _isOriginal: boolean) => {
    const change = changeMap.get(lineNum);
    if (!change) return 'line-unchanged';
    if (change.type === 'added') return 'line-added';
    if (change.type === 'removed') return 'line-removed';
    return 'line-modified';
  };

  const renderLineNumber = (num: number, className: string) => (
    <span className={clsx('w-8 text-right pr-3 text-foreground-muted select-none', className)}>
      {num}
    </span>
  );

  const renderLineContent = (content: string, change?: DiffChange, isOriginal = true) => {
    if (!change) return <span className="line-unchanged">{content || ' '}</span>;

    if (change.type === 'modified' && change.originalContent !== change.fixedContent) {
      // Show inline diff
      return (
        <span className={clsx('relative', isOriginal ? 'line-removed' : 'line-added')}>
          {isOriginal ? (
            <>
              <span className="inline-removed">{change.originalContent}</span>
              <span className="inline-added hidden">{change.fixedContent}</span>
            </>
          ) : (
            <>
              <span className="inline-removed hidden">{change.originalContent}</span>
              <span className="inline-added">{change.fixedContent}</span>
            </>
          )}
        </span>
      );
    }

    return <span className={clsx(isOriginal ? 'line-removed' : 'line-added')}>{content || ' '}</span>;
  };

  if (viewMode === 'unified') {
    return (
      <div className="diff-view font-mono text-sm bg-background-tertiary border border-border rounded-lg overflow-hidden">
        {showActions && !readOnly && (
          <div className="flex items-center gap-2 p-3 border-b border-border bg-background-secondary">
            <div className="flex items-center gap-1 border border-border rounded px-2">
              <button
                className={clsx('px-2 py-1 text-xs rounded', viewMode === 'side-by-side' ? 'bg-accent-blue/20 text-accent-blue' : 'text-foreground-secondary hover:text-foreground')}
                onClick={() => setViewMode('side-by-side')}
              >
                Side by Side
              </button>
              <button
                className={clsx('px-2 py-1 text-xs rounded', viewMode === 'unified' ? 'bg-accent-blue/20 text-accent-blue' : 'text-foreground-secondary hover:text-foreground')}
                onClick={() => setViewMode('unified')}
              >
                Unified
              </button>
            </div>
            <label className="flex items-center gap-1 text-sm text-foreground-secondary">
              <input
                type="checkbox"
                checked={showLineNumbers}
                onChange={(e) => setShowLineNumbers(e.target.checked)}
                className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
              />
              Line numbers
            </label>
            <div className="flex-1" />
            {onApplyFixed && (
              <button className="btn-primary" onClick={onApplyFixed}>
                Apply Fixed Version
              </button>
            )}
            {onReset && (
              <button className="btn-secondary" onClick={onReset}>
                Reset
              </button>
            )}
          </div>
        )}
        <div className="overflow-x-auto max-h-[600px]">
          <table className="w-full border-collapse">
            <thead>
              <tr>
                {showLineNumbers && <th className="w-16 px-3 py-2 text-left font-semibold text-foreground-secondary bg-background-tertiary border-b border-border">Line</th>}
                <th className="px-3 py-2 text-left font-semibold text-foreground-secondary bg-background-tertiary border-b border-border">Content</th>
              </tr>
            </thead>
            <tbody>
              {fixedLines.map((line, index) => {
                const lineNum = index + 1;
                const change = changeMap.get(lineNum);
                const isChange = !!change;

                if (!isChange) {
                  return (
                    <tr key={lineNum} className="line-unchanged">
                      {showLineNumbers && renderLineNumber(lineNum, '')}
                      <td className="px-3 py-1 whitespace-pre">{line || ' '}</td>
                    </tr>
                  );
                }

                if (change.type === 'added') {
                  return (
                    <tr key={lineNum} className="line-added">
                      {showLineNumbers && renderLineNumber(lineNum, 'text-accent-green')}
                      <td className="px-3 py-1 whitespace-pre">
                        <span className="inline-flex items-center gap-2">
                          <span className="text-accent-green">+</span>
                          {line}
                        </span>
                      </td>
                    </tr>
                  );
                }

                if (change.type === 'removed') {
                  return (
                    <tr key={lineNum} className="line-removed">
                      {showLineNumbers && renderLineNumber(lineNum, 'text-severity-critical')}
                      <td className="px-3 py-1 whitespace-pre">
                        <span className="inline-flex items-center gap-2">
                          <span className="text-severity-critical">-</span>
                          {change.originalContent}
                        </span>
                      </td>
                    </tr>
                  );
                }

                // Modified
                return (
                  <>
                    <tr key={`removed-${lineNum}`} className="line-removed">
                      {showLineNumbers && renderLineNumber(lineNum, 'text-severity-critical')}
                      <td className="px-3 py-1 whitespace-pre">
                        <span className="inline-flex items-center gap-2">
                          <span className="text-severity-critical">-</span>
                          {change.originalContent}
                        </span>
                      </td>
                    </tr>
                    <tr key={`added-${lineNum}`} className="line-added">
                      {showLineNumbers && renderLineNumber(0, 'text-accent-green')}
                      <td className="px-3 py-1 whitespace-pre">
                        <span className="inline-flex items-center gap-2">
                          <span className="text-accent-green">+</span>
                          {change.fixedContent}
                        </span>
                      </td>
                    </tr>
                  </>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    );
  }

  // Side-by-side view
  return (
    <div className="diff-view font-mono text-sm bg-background-tertiary border border-border rounded-lg overflow-hidden">
      {showActions && !readOnly && (
        <div className="flex items-center gap-2 p-3 border-b border-border bg-background-secondary">
          <div className="flex items-center gap-1 border border-border rounded px-2">
            <button
              className={clsx('px-2 py-1 text-xs rounded', viewMode === 'side-by-side' ? 'bg-accent-blue/20 text-accent-blue' : 'text-foreground-secondary hover:text-foreground')}
              onClick={() => setViewMode('side-by-side')}
            >
              Side by Side
            </button>
            <button
              className={clsx('px-2 py-1 text-xs rounded', viewMode === 'unified' ? 'bg-accent-blue/20 text-accent-blue' : 'text-foreground-secondary hover:text-foreground')}
              onClick={() => setViewMode('unified')}
            >
              Unified
            </button>
          </div>
          <label className="flex items-center gap-1 text-sm text-foreground-secondary">
            <input
              type="checkbox"
              checked={showLineNumbers}
              onChange={(e) => setShowLineNumbers(e.target.checked)}
              className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
            />
            Line numbers
          </label>
          <div className="flex-1" />
          {onApplyFixed && (
            <button className="btn-primary" onClick={onApplyFixed}>
              Apply Fixed Version
            </button>
          )}
          {onReset && (
            <button className="btn-secondary" onClick={onReset}>
              Reset
            </button>
          )}
        </div>
      )}
      <div className="flex overflow-x-auto max-h-[600px]">
        {/* Original */}
        <div className="w-1/2 border-r border-border min-w-0">
          <div className="sticky top-0 bg-background-secondary border-b border-border px-3 py-2 font-semibold text-foreground-secondary">
            Original
          </div>
          <div className="overflow-y-auto">
            <table className="w-full border-collapse">
              <tbody>
                {originalLines.map((line, index) => {
                  const lineNum = index + 1;
                  const change = changeMap.get(lineNum);
                  const lineClass = getLineClass(lineNum, true);
                  return (
                    <tr key={lineNum} className={lineClass}>
                      {showLineNumbers && renderLineNumber(lineNum, lineClass !== 'line-unchanged' ? 'text-severity-critical' : '')}
                      <td className="px-3 py-1 whitespace-pre">
                        {renderLineContent(line, change, true)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>

        {/* Fixed */}
        <div className="w-1/2 min-w-0">
          <div className="sticky top-0 bg-background-secondary border-b border-border px-3 py-2 font-semibold text-foreground-secondary">
            Fixed
          </div>
          <div className="overflow-y-auto">
            <table className="w-full border-collapse">
              <tbody>
                {fixedLines.map((line, index) => {
                  const lineNum = index + 1;
                  const change = changeMap.get(lineNum);
                  const lineClass = getLineClass(lineNum, false);
                  return (
                    <tr key={lineNum} className={lineClass}>
                      {showLineNumbers && renderLineNumber(lineNum, lineClass !== 'line-unchanged' ? 'text-accent-green' : '')}
                      <td className="px-3 py-1 whitespace-pre">
                        {renderLineContent(line, change, false)}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

