1	import React, { useState, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import {
4	  FileText,
5	  Upload,
6	  Download,
7	  Copy,
8	  RotateCcw,
9	  Sparkles,
10	  Shield,
11	  AlertTriangle,
12	  CheckCircle,
13	  XCircle,
14	  Info,
15	  HelpCircle,
16	  ChevronLeft,
17	  ChevronRight,
18	  Search,
19	  Filter,
20	  Settings
21	} from 'lucide-react';
22	import { dockerfileApi } from '../services/api';
23	import { DockerfileAnalysis, DockerfileIssue, Severity } from '@devsecops/shared/types';
24	import { CodeEditor } from '../components/CodeEditor';
25	import { DiffViewer } from '../components/DiffViewer';
26	import { FindingCard, FindingList } from '../components/FindingCard';
27	import { toast } from 'react-hot-toast';
28	import { clsx } from 'clsx';
29	
30	const DEFAULT_DOCKERFILE = `# Example vulnerable Dockerfile
31	FROM ubuntu:latest
32	
33	# Running as root (bad practice)
34	USER root
35	
36	# Install packages without pinning versions
37	RUN apt-get update && apt-get install -y \\
38	    nginx \\
39	    curl \\
40	    python3 \\
41	    python3-pip
42	
43	# Copy application
44	COPY . /app
45	WORKDIR /app
46	
47	# Install Python dependencies without pinning
48	RUN pip install -r requirements.txt
49	
50	# Expose port
51	EXPOSE 80
52	
53	# No health check
54	CMD ["nginx", "-g", "daemon off;"]`;
55	
56	const SEVERITY_ORDER: Record<Severity, number> = {
57	  critical: 5,
58	  high: 4,
59	  medium: 3,
60	  low: 2,
61	  info: 1
62	};
63	
64	export function DockerfileFixer() {
65	  const navigate = useNavigate();
66	  const [dockerfile, setDockerfile] = useState(DEFAULT_DOCKERFILE);
67	  const [analysis, setAnalysis] = useState<DockerfileAnalysis | null>(null);
68	  const [fixedDockerfile, setFixedDockerfile] = useState('');
69	  const [loading, setLoading] = useState(false);
70	  const [fixing, setFixing] = useState(false);
71	  const [viewMode, setViewMode] = useState<'editor' | 'diff' | 'side-by-side'>('editor');
72	  const [filterSeverity, setFilterSeverity] = useState<Severity[]>(['critical', 'high', 'medium', 'low', 'info']);
73	  const [filterType, setFilterType] = useState<string[]>([]);
74	  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
75	  const [showOnlyFixable, setShowOnlyFixable] = useState(false);
76	  const fileInputRef = useRef<HTMLInputElement>(null);
77	
78	  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
79	    const file = event.target.files?.[0];
80	    if (!file) return;
81	
82	    if (!file.name.match(/^(Dockerfile|\.dockerfile$)/i) && !file.name.endsWith('.dockerfile')) {
83	      toast.warning('File does not appear to be a Dockerfile');
84	    }
85	
86	    const reader = new FileReader();
87	    reader.onload = (e) => {
88	      setDockerfile(e.target?.result as string);
89	      setAnalysis(null);
90	      setFixedDockerfile('');
91	      setViewMode('editor');
92	      toast.success('Dockerfile loaded');
93	    };
94	    reader.readAsText(file);
95	    event.target.value = '';
96	  }, []);
97	
98	  const handleAnalyze = async () => {
99	    if (!dockerfile.trim()) {
100	      toast.error('Please provide a Dockerfile');
101	      return;
102	    }
103	
104	    setLoading(true);
105	    try {
106	      const response = await dockerfileApi.analyze(dockerfile);
107	      if (response.data.success) {
108	        setAnalysis(response.data.data);
109	        toast.success(`Analysis complete: ${response.data.data.issues.length} issues found`);
110	      } else {
111	        toast.error(response.data.error?.message || 'Analysis failed');
112	      }
113	    } catch (err) {
114	      toast.error('Failed to analyze Dockerfile');
115	      console.error(err);
116	    } finally {
117	      setLoading(false);
118	    }
119	  };
120	
121	  const handleFix = async () => {
122	    if (!analysis) {
123	      toast.error('Please analyze first');
124	      return;
125	    }
126	
127	    setFixing(true);
128	    try {
129	      const response = await dockerfileApi.fix(dockerfile, analysis.issues);
130	      if (response.data.success) {
131	        setFixedDockerfile(response.data.data.fixedDockerfile);
132	        setAnalysis(prev => prev ? {
133	          ...prev,
134	          fixedDockerfile: response.data.data.fixedDockerfile,
135	          changes: response.data.data.changes,
136	          securityImprovements: response.data.data.securityImprovements,
137	          explanation: response.data.data.explanation
138	        } : null);
139	        setViewMode('side-by-side');
140	        toast.success('Dockerfile fixed successfully!');
141	      } else {
142	        toast.error(response.data.error?.message || 'Fix failed');
143	      }
144	    } catch (err) {
145	      toast.error('Failed to fix Dockerfile');
146	      console.error(err);
147	    } finally {
148	      setFixing(false);
149	    }
150	  };
151	
152	  const handleApplyFixed = () => {
153	    if (fixedDockerfile) {
154	      setDockerfile(fixedDockerfile);
155	      setViewMode('editor');
156	      toast.success('Fixed version applied to editor');
157	    }
158	  };
159	
160	  const handleReset = () => {
161	    setDockerfile(DEFAULT_DOCKERFILE);
162	    setAnalysis(null);
163	    setFixedDockerfile('');
164	    setViewMode('editor');
165	    toast.success('Reset to default');
166	  };
167	
168	  const handleDownload = () => {
169	    const content = viewMode === 'editor' ? dockerfile : fixedDockerfile || dockerfile;
170	    const blob = new Blob([content], { type: 'text/plain' });
171	    const url = URL.createObjectURL(blob);
172	    const a = document.createElement('a');
173	    a.href = url;
174	    a.download = 'Dockerfile.fixed';
175	    a.click();
176	    URL.revokeObjectURL(url);
177	    toast.success('Downloaded');
178	  };
179	
180	  const handleCopy = () => {
181	    const content = viewMode === 'editor' ? dockerfile : fixedDockerfile || dockerfile;
182	    navigator.clipboard.writeText(content);
183	    toast.success('Copied to clipboard');
184	  };
185	
186	  const filteredIssues = analysis?.issues.filter(issue => {
187	    if (!filterSeverity.includes(issue.severity)) return false;
188	    if (filterType.length > 0 && !filterType.includes(issue.type)) return false;
189	    if (showOnlyFixable && !issue.fixable) return false;
190	    return true;
191	  }) || [];
192	
193	  const sortedIssues = [...filteredIssues].sort((a, b) =>
194	    SEVERITY_ORDER[b.severity] - SEVERITY_ORDER[a.severity]
195	  );
196	
197	  const issueTypes = [...new Set(analysis?.issues.map(i => i.type) || [])];
198	
199	  const severityCounts = analysis?.issues.reduce((acc, issue) => {
200	    acc[issue.severity] = (acc[issue.severity] || 0) + 1;
201	    return acc;
202	  }, {} as Record<Severity, number>) || { critical: 0, high: 0, medium: 0, low: 0, info: 0 };
203	
204	  const toggleExpand = (finding: DockerfileIssue) => {
205	    setExpandedFindings(prev => {
206	      const next = new Set(prev);
207	      if (next.has(finding.id)) next.delete(finding.id);
208	      else next.add(finding.id);
209	      return next;
210	    });
211	  };
212	
213	  return (
214	    <div className="space-y-6 animate-fade-in">
215	      {/* Header */}
216	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
217	        <div>
218	          <h1 className="text-2xl font-bold text-foreground">Dockerfile AI Fixer</h1>
219	          <p className="text-foreground-secondary mt-1">
220	            Analyze, secure, and optimize your Dockerfiles with AI-powered fixes
221	          </p>
222	        </div>
223	        <div className="flex items-center gap-2">
224	          <button className="btn-secondary" onClick={() => fileInputRef.current?.click()}>
225	            <Upload className="w-4 h-4" />
226	            Upload
227	          </button>
228	          <input
229	            ref={fileInputRef}
230	            type="file"
231	            accept=".dockerfile,Dockerfile,.txt"
232	            onChange={handleFileUpload}
233	            className="hidden"
234	          />
235	          <button className="btn-secondary" onClick={handleDownload}>
236	            <Download className="w-4 h-4" />
237	            Download
238	          </button>
239	          <button className="btn-secondary" onClick={handleCopy}>
240	            <Copy className="w-4 h-4" />
241	            Copy
242	          </button>
243	          <button className="btn-secondary" onClick={handleReset}>
244	            <RotateCcw className="w-4 h-4" />
245	            Reset
246	          </button>
247	        </div>
248	      </div>
249	
250	      {/* Toolbar */}
251	      <div className="card p-4">
252	        <div className="flex flex-wrap items-center gap-4">
253	          {/* View Mode Tabs */}
254	          <div className="tabs">
255	            <button
256	              className={clsx('tab', viewMode === 'editor' && 'tab-active')}
257	              onClick={() => setViewMode('editor')}
258	            >
259	              <FileText className="w-4 h-4" />
260	              Editor
261	            </button>
262	            {analysis && (
263	              <>
264	                <button
265	                  className={clsx('tab', viewMode === 'side-by-side' && 'tab-active')}
266	                  onClick={() => setViewMode('side-by-side')}
267	                >
268	                  <ChevronLeft className="w-4 h-4" />
269	                  <ChevronRight className="w-4 h-4" />
270	                  Diff
271	                </button>
272	                <button
273	                  className={clsx('tab', viewMode === 'diff' && 'tab-active')}
274	                  onClick={() => setViewMode('diff')}
275	                >
276	                  <Search className="w-4 h-4" />
277	                  Findings
278	                </button>
279	              </>
280	            )}
281	          </div>
282	
283	          <div className="flex-1" />
284	
285	          {/* Filters */}
286	          {analysis && (
287	            <div className="flex items-center gap-4">
288	              <div className="flex items-center gap-2">
289	                <Filter className="w-4 h-4 text-foreground-muted" />
290	                <select
291	                  className="input py-1.5 px-3 text-sm w-auto"
292	                  multiple
293	                  value={filterSeverity}
294	                  onChange={(e) => {
295	                    const selected = Array.from(e.target.selectedOptions).map(o => o.value as Severity);
296	                    setFilterSeverity(selected);
297	                  }}
298	                >
299	                  {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(s => (
300	                    <option key={s} value={s} className="capitalize">
301	                      {s} ({severityCounts[s] || 0})
302	                    </option>
303	                  ))}
304	                </select>
305	              </div>
306	
307	              {issueTypes.length > 0 && (
308	                <div className="flex items-center gap-2">
309	                  <Settings className="w-4 h-4 text-foreground-muted" />
310	                  <select
311	                    className="input py-1.5 px-3 text-sm w-auto"
312	                    multiple
313	                    value={filterType}
314	                    onChange={(e) => {
315	                      const selected = Array.from(e.target.selectedOptions).map(o => o.value);
316	                      setFilterType(selected);
317	                    }}
318	                  >
319	                    {issueTypes.map(t => (
320	                      <option key={t} value={t} className="capitalize">
321	                        {t.replace('_', ' ')}
322	                      </option>
323	                    ))}
324	                  </select>
325	                </div>
326	              )}
327	
328	              <label className="flex items-center gap-2 text-sm text-foreground-secondary">
329	                <input
330	                  type="checkbox"
331	                  checked={showOnlyFixable}
332	                  onChange={(e) => setShowOnlyFixable(e.target.checked)}
333	                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
334	                />
335	                Fixable only
336	              </label>
337	            </div>
338	          )}
339	
340	          {/* Action Buttons */}
341	          <div className="flex items-center gap-2">
342	            <button
343	              className="btn-primary"
344	              onClick={handleAnalyze}
345	              disabled={loading || !dockerfile.trim()}
346	            >
347	              {loading ? (
348	                <>
349	                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
350	                  Analyzing...
351	                </>
352	              ) : (
353	                <>
354	                  <Shield className="w-4 h-4" />
355	                  Analyze
356	                </>
357	              )}
358	            </button>
359	
360	            {analysis && !fixedDockerfile && (
361	              <button
362	                className="btn-primary"
363	                onClick={handleFix}
364	                disabled={fixing}
365	              >
366	                {fixing ? (
367	                  <>
368	                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
369	                    Fixing...
370	                  </>
371	                ) : (
372	                  <>
373	                    <Sparkles className="w-4 h-4" />
374	                    AI Fix
375	                  </>
376	                )}
377	              </button>
378	            )}
379	
380	            {fixedDockerfile && viewMode !== 'editor' && (
381	              <button className="btn-secondary" onClick={handleApplyFixed}>
382	                <CheckCircle className="w-4 h-4" />
383	                Apply Fix
