1	import React, { useState, useCallback } from 'react';
2	import {
3	  Search,
4	  Shield,
5	  Download,
6	  Copy,
7	  RefreshCw,
8	  Filter,
9	  ChevronDown,
10	  ChevronUp,
11	  AlertTriangle,
12	  CheckCircle,
13	  Package,
14	  Server,
15	  Zap,
16	  ArrowRight,
17	  Clock,
18	  History
19	} from 'lucide-react';
20	import { dockerApi } from '../services/api';
21	import { DockerImageScanResult, Vulnerability, Severity } from '@devsecops/shared/types';
22	import { FindingCard, FindingList } from '../components/FindingCard';
23	import { toast } from 'react-hot-toast';
24	import { formatDistanceToNow } from 'date-fns';
25	import { clsx } from 'clsx';
26	
27	const SEVERITY_ORDER: Record<Severity, number> = {
28	  critical: 5,
29	  high: 4,
30	  medium: 3,
31	  low: 2,
32	  info: 1
33	};
34	
35	const SEVERITY_COLORS: Record<Severity, string> = {
36	  critical: 'text-severity-critical',
37	  high: 'text-severity-high',
38	  medium: 'text-severity-medium',
39	  low: 'text-severity-low',
40	  info: 'text-severity-info'
41	};
42	
43	export function DockerScanner() {
44	  const [imageRef, setImageRef] = useState('');
45	  const [scanResult, setScanResult] = useState<DockerImageScanResult | null>(null);
46	  const [loading, setLoading] = useState(false);
47	  const [fixing, setFixing] = useState(false);
48	  const [filterSeverity, setFilterSeverity] = useState<Severity[]>(['critical', 'high', 'medium', 'low', 'info']);
49	  const [filterPackage, setFilterPackage] = useState('');
50	  const [filterCVE, setFilterCVE] = useState('');
51	  const [showFixableOnly, setShowFixableOnly] = useState(false);
52	  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
53	  const [selectedVuln, setSelectedVuln] = useState<Vulnerability | null>(null);
54	  const [fixResult, setFixResult] = useState<any>(null);
55	  const [scanHistory, setScanHistory] = useState<Array<{ image: string; result: DockerImageScanResult; timestamp: Date }>>([]);
56	
57	  const handleScan = async () => {
58	    if (!imageRef.trim()) {
59	      toast.error('Please enter a Docker image reference');
60	      return;
61	    }
62	
63	    setLoading(true);
64	    try {
65	      const response = await dockerApi.scan(imageRef.trim());
66	      if (response.data.success) {
67	        const result = response.data.data;
68	        setScanResult(result);
69	        setScanHistory(prev => [{ image: imageRef.trim(), result, timestamp: new Date() }, ...prev.slice(0, 9)]);
70	        toast.success(`Scan complete: ${result.vulnerabilities.length} vulnerabilities found`);
71	      } else {
72	        toast.error(response.data.error?.message || 'Scan failed');
73	      }
74	    } catch (err) {
75	      toast.error('Failed to scan image');
76	      console.error(err);
77	    } finally {
78	      setLoading(false);
79	    }
80	  };
81	
82	  const handleFix = async (vuln: Vulnerability) => {
83	    if (!scanResult) return;
84	
85	    setSelectedVuln(vuln);
86	    setFixing(true);
87	    try {
88	      const response = await dockerApi.fix(
89	        imageRef.trim(),
90	        scanResult.vulnerabilities,
91	        undefined, // dockerfile - would need to be provided
92	        { strategy: 'update_packages', allowBreakingChanges: false }
93	      );
94	      if (response.data.success) {
95	        setFixResult(response.data.data);
96	        toast.success('Fix generated successfully!');
97	      } else {
98	        toast.error(response.data.error?.message || 'Fix failed');
99	      }
100	    } catch (err) {
101	      toast.error('Failed to generate fix');
102	      console.error(err);
103	    } finally {
104	      setFixing(false);
105	    }
106	  };
107	
108	  const filteredVulns = scanResult?.vulnerabilities.filter(v => {
109	    if (!filterSeverity.includes(v.severity)) return false;
110	    if (filterPackage && !v.package.toLowerCase().includes(filterPackage.toLowerCase())) return false;
111	    if (filterCVE && !v.id.toLowerCase().includes(filterCVE.toLowerCase())) return false;
112	    if (showFixableOnly && !v.fixAvailable) return false;
113	    return true;
114	  }) || [];
115	
116	  const sortedVulns = [...filteredVulns].sort((a, b) =>
117	    SEVERITY_ORDER[b.severity] - SEVERITY_ORDER[a.severity]
118	  );
119	
120	  const severityCounts = scanResult?.vulnerabilities.reduce((acc, v) => {
121	    acc[v.severity] = (acc[v.severity] || 0) + 1;
122	    return acc;
123	  }, {} as Record<Severity, number>) || { critical: 0, high: 0, medium: 0, low: 0, info: 0 };
124	
125	  const toggleExpand = (finding: any) => {
126	    setExpandedFindings(prev => {
127	      const next = new Set(prev);
128	      if (next.has(finding.id)) next.delete(finding.id);
129	      else next.add(finding.id);
130	      return next;
131	    });
132	  };
133	
134	  const handleLoadHistory = (item: typeof scanHistory[0]) => {
135	    setImageRef(item.image);
136	    setScanResult(item.result);
137	    setFixResult(null);
138	    setSelectedVuln(null);
139	  };
140	
141	  return (
142	    <div className="space-y-6 animate-fade-in">
143	      {/* Header */}
144	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
145	        <div>
146	          <h1 className="text-2xl font-bold text-foreground">Docker Image Security Scanner</h1>
147	          <p className="text-foreground-secondary mt-1">
148	            Scan container images for vulnerabilities using Grype
149	          </p>
150	        </div>
151	        <div className="flex items-center gap-2">
152	          <button className="btn-secondary" onClick={() => setImageRef('')}>
153	            <RefreshCw className="w-4 h-4" />
154	            Clear
155	          </button>
156	        </div>
157	      </div>
158	
159	      {/* Input Section */}
160	      <div className="card">
161	        <div className="flex flex-col sm:flex-row gap-4">
162	          <div className="flex-1">
163	            <label className="label">Docker Image Reference</label>
164	            <div className="relative">
165	              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
166	              <input
167	                type="text"
168	                value={imageRef}
169	                onChange={(e) => setImageRef(e.target.value)}
170	                placeholder="e.g., nginx:latest, myorg/myapp:v1.2.3, ghcr.io/user/repo:tag"
171	                className="input pl-10"
172	                disabled={loading}
173	              />
174	            </div>
175	            <p className="text-xs text-foreground-muted mt-1">
176	              Supports Docker Hub, GHCR, ECR, GCR, Quay, and private registries
177	            </p>
178	          </div>
179	          <button
180	            className="btn-primary self-end"
181	            onClick={handleScan}
182	            disabled={loading || !imageRef.trim()}
183	          >
184	            {loading ? (
185	              <>
186	                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
187	                Scanning...
188	              </>
189	            ) : (
190	              <>
191	                <Shield className="w-4 h-4" />
192	                Scan Image
193	              </>
194	            )}
195	          </button>
196	        </div>
197	
198	        {/* Quick Examples */}
199	        <div className="mt-4 pt-4 border-t border-border">
200	          <p className="text-sm text-foreground-secondary mb-2">Quick examples:</p>
201	          <div className="flex flex-wrap gap-2">
202	            {[
203	              'nginx:latest',
204	              'alpine:latest',
205	              'ubuntu:22.04',
206	              'node:20-alpine',
207	              'python:3.11-slim'
208	            ].map((img, i) => (
209	              <button
210	                key={i}
211	                className="btn-secondary text-sm px-3 py-1.5"
212	                onClick={() => setImageRef(img)}
213	                disabled={loading}
214	              >
215	                {img}
216	              </button>
217	            ))}
218	          </div>
219	        </div>
220	      </div>
221	
222	      {/* Results */}
223	      {scanResult && (
224	        <>
225	          {/* Image Info Card */}
226	          <div className="card">
227	            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4">
228	              <div className="flex items-center gap-4">
229	                <div className="p-3 bg-accent-blue/10 rounded-xl">
230	                  <Package className="w-6 h-6 text-accent-blue" />
231	                </div>
232	                <div>
233	                  <h2 className="text-xl font-semibold text-foreground font-mono">{scanResult.image}</h2>
234	                  <div className="flex items-center gap-4 text-sm text-foreground-secondary mt-1">
235	                    <span className="flex items-center gap-1"><Server className="w-4 h-4" /> {scanResult.os}</span>
236	                    <span className="flex items-center gap-1"><Package className="w-4 h-4" /> {scanResult.architecture}</span>
237	                    <span className="flex items-center gap-1"><Package className="w-4 h-4" /> {scanResult.packageCount} packages</span>
238	                  </div>
239	                </div>
240	              </div>
241	              <div className="flex items-center gap-2">
242	                <button className="btn-secondary" onClick={() => navigator.clipboard.writeText(scanResult.digest)}>
243	                  <Copy className="w-4 h-4" />
244	                  Copy Digest
245	                </button>
246	                <button className="btn-secondary" onClick={handleScan}>
247	                  <RefreshCw className="w-4 h-4" />
248	                  Rescan
249	                </button>
250	              </div>
251	            </div>
252	
253	            {/* Severity Summary */}
254	            <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
255	              {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(sev => (
256	                <div
257	                  key={sev}
258	                  className={clsx('p-3 rounded-lg text-center', `bg-severity-${sev}/10 border border-severity-${sev}/20`)}
259	                >
260	                  <p className="text-2xl font-bold" style={{ color: `var(--color-severity-${sev})` }}>
261	                    {severityCounts[sev] || 0}
262	                  </p>
263	                  <p className="text-xs text-foreground-secondary capitalize">{sev}</p>
264	                </div>
265	              ))}
266	            </div>
267	          </div>
268	
269	          {/* Filters */}
270	          <div className="card">
271	            <div className="flex flex-wrap items-center gap-4">
272	              <div className="flex items-center gap-2">
273	                <Filter className="w-4 h-4 text-foreground-muted" />
274	                <select
275	                  className="input py-1.5 px-3 text-sm w-auto"
276	                  multiple
277	                  value={filterSeverity}
278	                  onChange={(e) => {
279	                    const selected = Array.from(e.target.selectedOptions).map(o => o.value as Severity);
280	                    setFilterSeverity(selected);
281	                  }}
282	                >
283	                  {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(s => (
284	                    <option key={s} value={s} className="capitalize">
285	                      {s} ({severityCounts[s] || 0})
286	                    </option>
287	                  ))}
288	                </select>
289	              </div>
290	
291	              <div className="flex items-center gap-2">
292	                <Search className="w-4 h-4 text-foreground-muted" />
293	                <input
294	                  type="text"
295	                  placeholder="Filter by package..."
296	                  value={filterPackage}
297	                  onChange={(e) => setFilterPackage(e.target.value)}
298	                  className="input py-1.5 px-3 text-sm w-48"
299	                />
300	              </div>
301	
302	              <div className="flex items-center gap-2">
303	                <Search className="w-4 h-4 text-foreground-muted" />
304	                <input
305	                  type="text"
306	                  placeholder="Filter by CVE..."
307	                  value={filterCVE}
308	                  onChange={(e) => setFilterCVE(e.target.value)}
309	                  className="input py-1.5 px-3 text-sm w-48"
310	                />
311	              </div>
312	
313	              <label className="flex items-center gap-2 text-sm text-foreground-secondary">
314	                <input
315	                  type="checkbox"
316	                  checked={showFixableOnly}
317	                  onChange={(e) => setShowFixableOnly(e.target.checked)}
318	                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
319	                />
320	                Fix available only
321	              </label>
322	
323	              <div className="flex-1" />
324	              <span className="text-sm text-foreground-secondary">
325	                {sortedVulns.length} of {scanResult.vulnerabilities.length} vulnerabilities
326	              </span>
327	            </div>
328	          </div>
329	
330	          {/* Vulnerability Table */}
331	          <div className="card p-0 overflow-hidden">
332	            {sortedVulns.length === 0 ? (
333	              <div className="p-12 text-center">
334	                <CheckCircle className="w-12 h-12 text-accent-green mx-auto mb-4" />
335	                <h3 className="text-lg font-medium text-foreground mb-1">No vulnerabilities found</h3>
336	                <p className="text-foreground-secondary">Great! Your image appears clean.</p>
337	              </div>
338	            ) : (
339	              <>
340	                <div className="overflow-x-auto">
341	                  <table className="table">
342	                    <thead>
343	                      <tr>
344	                        <th className="w-10"></th>
345	                        <th>CVE</th>
346	                        <th>Package</th>
347	                        <th>Installed</th>
348	                        <th>Fixed</th>
349	                        <th>Severity</th>
350	                        <th>Type</th>
351	                        <th className="w-10"></th>
352	                      </tr>
353	                    </thead>
354	                    <tbody>
355	                      {sortedVulns.map((vuln) => (
356	                        <tr key={vuln.id}>
357	                          <td>
358	                            <button
359	                              className="text-foreground-muted hover:text-foreground"
360	                              onClick={() => toggleExpand({
361	                                id: vuln.id,
362	                                severity: vuln.severity,
363	                                type: 'vulnerability',
364	                                title: vuln.id,
365	                                description: vuln.description,
366	                                file: vuln.package,
367	                                cve: vuln.id,
368	                                package: vuln.package,
369	                                installedVersion: vuln.installedVersion,
370	                                fixedVersion: vuln.fixedVersion
371	                              })}
372	                            >
373	                              {expandedFindings.has(vuln.id) ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
374	                            </button>
375	                          </td>
376	                          <td>
377	                            <a
378	                              href={`https://cve.mitre.org/cgi-bin/cvename.cgi?name=${vuln.id}`}
379	                              target="_blank"
380	                              rel="noopener noreferrer"
381	                              className="font-mono text-sm hover:underline"
382	                            >
383	                              {vuln.id}
384	                            </a>
385	                          </td>
386	                          <td className="font-mono text-sm">{vuln.package}</td>
387	                          <td className="font-mono text-sm">{vuln.installedVersion}</td>
388	                          <td className="font-mono text-sm">
389	                            {vuln.fixedVersion ? (
390	                              <span className="text-accent-green">{vuln.fixedVersion}</span>
391	                            ) : (
392	                              <span className="text-foreground-muted">No fix</span>
393	                            )}
394	                          </td>
395	                          <td>
396	                            <span className={clsx('badge', `badge-${vuln.severity}`)}>
397	                              {vuln.severity.toUpperCase()}
398	                            </span>
399	                          </td>
400	                          <td>
401	                            <span className="badge badge-info text-xs">{vuln.type}</span>
402	                          </td>
403	                          <td>
404	                            {vuln.fixAvailable && (
405	                              <button
406	                                className="btn-primary text-xs px-2 py-1"
407	                                onClick={() => handleFix(vuln)}
408	                                disabled={fixing}
409	                              >
410	                                Fix
411	                              </button>
412	                            )}
413	                          </td>
414	                        </tr>
415	                      ))}
416	                    </tbody>
417	                  </table>
418	                </div>
419	
420	                {/* Expanded Details */}
421	                {sortedVulns.map((vuln) => expandedFindings.has(vuln.id) && (
422	                  <tr key={`expanded-${vuln.id}`} className="bg-background-tertiary/50">
423	                    <td colSpan={8} className="px-6 py-4">
424	                      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
425	                        <div>
426	                          <p className="font-medium text-foreground mb-1">Description</p>
