);

const severityCounts = scanResult?.vulnerabilities.reduce((acc, v) => {
  acc[v.severity] = (acc[v.severity] || 0) + 1;
  return acc;
}, {} as Record<Severity, number>) || { critical: 0, high: 0, medium: 0, low: 0, info: 0 };

const toggleExpand = (finding: any) => {
