451	                    fixedContent: fixedJenkinsfile || undefined
452	                  } : undefined,
453	                  status: 'open' as const,
454	                  createdAt: new Date().toISOString()
455	                }))}
456	                expandedIds={expandedFindings}
457	                onToggleExpand={toggleExpand}
458	                showActions={false}
459	                emptyMessage="No issues found matching current filters"
460	              />
461	            </div>
462	          )}
463	
464	          {/* Severity Summary */}
465	          {analysis && (
466	            <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
467	              {['critical', 'high', 'medium', 'low', 'info'].map(sev => (
468	                <div
469	                  key={sev}
470	                  className={clsx('card p-4 text-center', `border-l-4 border-severity-${sev}`)}
471	                >
472	                  <p className="text-3xl font-bold" style={{ color: `var(--color-severity-${sev})` }}>
473	                    {severityCounts[sev] || 0}
474	                  </p>
475	                  <p className="text-sm text-foreground-secondary capitalize">{sev}</p>
476	                </div>
477	              ))}
478	            </div>
479	          )}
480	        </>
481	      ) : activeTab === 'generator' ? (
482	        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
483	          {/* Generator Form */}
484	          <div className="card">
485	            <h2 className="text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
486	              <Wand2 className="w-5 h-5 text-accent-yellow" />
487	              Generate Jenkinsfile
488	            </h2>
489	
490	            <div className="space-y-4">
491	              <div className="grid grid-cols-2 gap-4">
492	                <div>
493	                  <label className="label">Application</label>
494	                  <select
495	                    className={input}
496	                    value={genForm.application}
497	                    onChange={(e) => setGenForm({ ...genForm, application: e.target.value as any })}
498	                  >
499	                    {['nodejs', 'python', 'java', 'go', 'docker', 'generic'].map(t => (
500	                      <option key={t} value={t} className="capitalize">{t}</option>
501	                    ))}
502	                  </select>
503	                </div>
504	                <div>
505	                  <label className="label">Build Tool</label>
506	                  <select
507	                    className={input}
508	                    value={genForm.buildTool}
509	                    onChange={(e) => setGenForm({ ...genForm, buildTool: e.target.value as any })}
510	                  >
511	                    {['npm', 'maven', 'gradle', 'pip', 'make', 'none'].map(t => (
512	                      <option key={t} value={t}>{t}</option>
513	                    ))}
514	                  </select>
515	                </div>
516	              </div>
517	
518	              <div>
519	                <label className="label">Repository URL</label>
520	                <input
521	                  className={input}
522	                  value={genForm.repositoryUrl}
523	                  onChange={(e) => setGenForm({ ...genForm, repositoryUrl: e.target.value })}
524	                  placeholder="https://github.com/user/repo"
525	                />
526	              </div>
527	
528	              {/* Pipeline Options */}
529	              <div className="space-y-2">
530	                <p className="font-medium text-foreground mb-2">Pipeline Stages</p>
531	                {[
532	                  { key: 'testing', label: 'Testing', icon: CheckCircle },
533	                  { key: 'dockerBuild', label: 'Docker Build', icon: Workflow },
534	                  { key: 'securityScan', label: 'Security Scan', icon: Shield },
535	                  { key: 'dockerPush', label: 'Docker Push', icon: Upload }
536	                ].map(({ key, label, icon: Icon }) => (
