538	                    <input
539	                      type="checkbox"
540	                      checked={(genForm as any)[key]}
541	                      onChange={(e) => setGenForm({ ...genForm, [key]: e.target.checked })}
542	                      className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
543	                    />
544	                    <Icon className="w-4 h-4" />
545	                    {label}
546	                  </label>
547	                ))}
548	              </div>
549	
550	              <div className="grid grid-cols-2 gap-4">
551	                <div>
552	                  <label className="label">Deployment</label>
553	                  <select
554	                    className={input}
