573	
574	              <div>
575	                <label className="label">Environments</label>
576	                <div className="flex gap-2">
577	                  {['dev', 'staging', 'production'].map(env => (
578	                    <label key={env} className={clsx(
579	                      'flex-1 flex items-center justify-center gap-2 p-2 rounded-lg text-sm cursor-pointer transition-colors',
580	                      genForm.environments.includes(env as any)
581	                        ? 'bg-accent-blue/20 text-accent-blue border border-accent-blue/30'
