592	                          }
593	                        }}
594	                        className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
595	                      />
596	                      <span className="capitalize">{env}</span>
597	                    </label>
598	                  ))}
599	                </div>
600	              </div>
601	
602	              {genForm.deployment === 'kubernetes' && (
603	                <div className="p-3 bg-background-tertiary rounded-lg space-y-3">
604	                  <p className="font-medium text-foreground">Kubernetes Config</p>
605	                  <div className="grid grid-cols-2 gap-3">
606	                    <div>
607	                      <label className="label text-xs">App Name</label>
608	                      <input className={input} value={genForm.kubernetesConfig?.name} onChange={(e) => setGenForm({ ...genForm, kubernetesConfig: { ...genForm.kubernetesConfig!, name: e.target.value } })} />
609	                    </div>
610	                    <div>
611	                      <label className="label text-xs">Image</label>
612	                      <input className={input} value={genForm.kubernetesConfig?.image} onChange={(e) => setGenForm({ ...genForm, kubernetesConfig: { ...genForm.kubernetesConfig!, image: e.target.value } })} />
613	                    </div>
614	                    <div>
615	                      <label className="label text-xs">Replicas</label>
616	                      <input type="number" className={input} value={genForm.kubernetesConfig?.replicas} onChange={(e) => setGenForm({ ...genForm, kubernetesConfig: { ...genForm.kubernetesConfig!, replicas: parseInt(e.target.value) } })} />
617	                    </div>
618	                    <div>
619	                      <label className="label text-xs">Port</label>
620	                      <input type="number" className={input} value={genForm.kubernetesConfig?.port} onChange={(e) => setGenForm({ ...genForm, kubernetesConfig: { ...genForm.kubernetesConfig!, port: parseInt(e.target.value) } })} />
621	                    </div>
622	                  </div>
623	                </div>
624	              )}
625	
626	              <button className="btn-primary w-full" onClick={handleGenerate} disabled={generating}>
627	                {generating ? (
628	                  <>
629	                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
630	                    Generating...
631	                  </>
632	                ) : (
633	                  <>
634	                    <Wand2 className="w-4 h-4" />
635	                    Generate Jenkinsfile
636	                  </>
637	                )}
638	              </button>
639	            </div>
640	          </div>
641	
642	          {/* Output */}
643	          <div className="card p-0 overflow-hidden">
644	            <div className="flex items-center justify-between p-4 border-b border-border">
645	              <h3 className="font-medium text-foreground">Generated Jenkinsfile</h3>
646	              {generatedJenkinsfile && (
647	                <div className="flex gap-2">
648	                  <button className="btn-secondary text-sm" onClick={() => navigator.clipboard.writeText(generatedJenkinsfile)}>
649	                    <Copy className="w-3.5 h-3.5" />
650	                  </button>
651	                  <button className="btn-secondary text-sm" onClick={() => {
652	                    const blob = new Blob([generatedJenkinsfile], { type: 'text/plain' });
653	                    const url = URL.createObjectURL(blob);
654	                    const a = document.createElement('a');
655	                    a.href = url;
656	                    a.download = 'Jenkinsfile';
657	                    a.click();
658	                    URL.revokeObjectURL(url);
659	                  }}>
660	                    <Download className="w-3.5 h-3.5" />
661	                  </button>
662	                </div>
663	              )}
664	            </div>
665	            {generatedJenkinsfile ? (
666	              <CodeEditor
667	                value={generatedJenkinsfile}
668	                onChange={setGeneratedJenkinsfile}
669	                language="jenkinsfile"
670	                fileName="Jenkinsfile"
671	                minHeight={500}
672	                readOnly
673	              />
674	            ) : (
675	              <div className="p-12 text-center text-foreground-secondary">
676	                <GitBranch className="w-12 h-12 mx-auto mb-3 opacity-50" />
677	                <p>Configure options and click Generate</p>
678	                <p className="text-sm mt-1">Complete CI/CD pipeline will appear here</p>
679	              </div>
680	            )}
681	          </div>
682	        </div>
683	      ) : (
684	        // Integration Tab
685	        <div className="space-y-6">
686	          <div className="card">
687	            <div className="flex items-center justify-between mb-4">
688	              <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
689	                <Server className="w-5 h-5 text-accent-blue" />
690	                Jenkins Servers
691	              </h2>
692	              <button className="btn-primary text-sm" onClick={() => setShowConnectModal(true)}>
693	                <Server className="w-4 h-4" />
694	                Connect Server
695	              </button>
696	            </div>
697	
698	            {jenkinsServers.length === 0 ? (
699	              <div className="text-center py-8 text-foreground-secondary">
700	                <Server className="w-12 h-12 mx-auto mb-3 opacity-50" />
701	                <p>No Jenkins servers connected</p>
702	                <p className="text-sm mt-1">Connect a Jenkins server to trigger jobs and view build status</p>
703	              </div>
