1	import React, { useState, useCallback, useRef } from 'react';
2	import {
3	  Upload,
4	  Download,
5	  Copy,
6	  RotateCcw,
7	  Sparkles,
8	  Shield,
9	  AlertTriangle,
10	  CheckCircle,
11	  Info,
12	  FileText,
13	  Wand2,
14	  Search,
15	  Filter,
16	  Box,
17	  Network,
18	  Lock,
19	  Server
20	} from 'lucide-react';
21	import { kubernetesApi } from '../services/api';
22	import { KubernetesAnalysis, KubernetesIssue, K8sResourceType, KubernetesGeneratorConfig } from '@devsecops/shared/types';
23	import { CodeEditor } from '../components/CodeEditor';
24	import { DiffViewer } from '../components/DiffViewer';
25	import { FindingCard, FindingList } from '../components/FindingCard';
26	import { toast } from 'react-hot-toast';
27	import { clsx } from 'clsx';
28	
29	const DEFAULT_YAML = `apiVersion: apps/v1
30	kind: Deployment
31	metadata:
32	  name: my-app
33	  labels:
34	    app: my-app
35	spec:
36	  replicas: 1
37	  selector:
38	    matchLabels:
39	      app: my-app
40	  template:
41	    metadata:
42	      labels:
43	        app: my-app
44	    spec:
45	      containers:
46	      - name: my-app
47	        image: nginx:latest
48	        ports:
49	        - containerPort: 80
50	---
51	apiVersion: v1
52	kind: Service
53	metadata:
54	  name: my-app
55	spec:
56	  selector:
57	    app: my-app
58	  ports:
59	  - port: 80
60	    targetPort: 80`;
61	
62	const SEVERITY_ORDER: Record<string, number> = {
63	  critical: 5,
64	  high: 4,
65	  medium: 3,
66	  low: 2,
67	  info: 1
68	};
69	
70	const RESOURCE_TYPES: K8sResourceType[] = [
71	  'Deployment', 'Service', 'Ingress', 'ConfigMap', 'Secret', 'StatefulSet',
72	  'DaemonSet', 'Job', 'CronJob', 'Namespace', 'ServiceAccount', 'Role',
73	  'RoleBinding', 'NetworkPolicy', 'PersistentVolumeClaim'
74	];
75	
76	export function KubernetesAssistant() {
77	  const [yaml, setYaml] = useState(DEFAULT_YAML);
78	  const [analysis, setAnalysis] = useState<KubernetesAnalysis | null>(null);
79	  const [fixedYaml, setFixedYaml] = useState('');
80	  const [loading, setLoading] = useState(false);
81	  const [fixing, setFixing] = useState(false);
82	  const [generating, setGenerating] = useState(false);
83	  const [viewMode, setViewMode] = useState<'editor' | 'diff' | 'findings'>('editor');
84	  const [activeTab, setActiveTab] = useState<'fixer' | 'generator'>('fixer');
85	  const [filterSeverity, setFilterSeverity] = useState<string[]>(['critical', 'high', 'medium', 'low', 'info']);
86	  const [showOnlyFixable, setShowOnlyFixable] = useState(false);
87	  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
88	  const fileInputRef = useRef<HTMLInputElement>(null);
89	
90	  // Generator form state
91	  const [genForm, setGenForm] = useState<KubernetesGeneratorConfig>({
92	    name: 'my-app',
93	    namespace: 'default',
94	    image: 'nginx:latest',
95	    replicas: 3,
96	    port: 80,
97	    serviceType: 'ClusterIP',
98	    ingressEnabled: true,
99	    ingressHost: 'my-app.example.com',
100	    cpuRequest: '250m',
101	    memoryRequest: '256Mi',
102	    livenessProbe: { enabled: true, path: '/healthz', port: 80, initialDelaySeconds: 30, periodSeconds: 10 },
103	    readinessProbe: { enabled: true, path: '/readyz', port: 80, initialDelaySeconds: 10, periodSeconds: 5 },
104	    securityContext: { enabled: true, runAsNonRoot: true, runAsUser: 1000, readOnlyRootFilesystem: true, allowPrivilegeEscalation: false, capabilities: ['DROP_ALL'] }
105	  });
106	  const [genResourceType, setGenResourceType] = useState<K8sResourceType>('Deployment');
107	  const [generatedYaml, setGeneratedYaml] = useState('');
108	
109	  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
110	    const file = event.target.files?.[0];
111	    if (!file) return;
112	    const reader = new FileReader();
113	    reader.onload = (e) => {
114	      setYaml(e.target?.result as string);
115	      setAnalysis(null);
116	      setFixedYaml('');
117	      setViewMode('editor');
118	      toast.success('YAML loaded');
119	    };
120	    reader.readAsText(file);
121	    event.target.value = '';
122	  }, []);
123	
124	  const handleAnalyze = async () => {
125	    if (!yaml.trim()) {
126	      toast.error('Please provide YAML');
127	      return;
128	    }
129	    setLoading(true);
130	    try {
131	      const response = await kubernetesApi.analyze(yaml);
132	      if (response.data.success) {
133	        setAnalysis(response.data.data);
134	        toast.success(`Analysis complete: ${response.data.data.issues.length} issues found`);
135	      } else {
136	        toast.error(response.data.error?.message || 'Analysis failed');
137	      }
138	    } catch (err) {
139	      toast.error('Failed to analyze YAML');
140	      console.error(err);
141	    } finally {
142	      setLoading(false);
143	    }
144	  };
145	
146	  const handleFix = async () => {
147	    if (!analysis) {
148	      toast.error('Please analyze first');
149	      return;
150	    }
151	    setFixing(true);
152	    try {
153	      const response = await kubernetesApi.fix(yaml, analysis.issues);
154	      if (response.data.success) {
155	        setFixedYaml(response.data.data.fixedYaml);
156	        setAnalysis(prev => prev ? {
157	          ...prev,
158	          fixedYaml: response.data.data.fixedYaml,
159	          changes: response.data.data.changes,
160	          explanation: response.data.data.explanation
161	        } : null);
162	        setViewMode('diff');
163	        toast.success('YAML fixed successfully!');
164	      } else {
165	        toast.error(response.data.error?.message || 'Fix failed');
166	      }
167	    } catch (err) {
168	      toast.error('Failed to fix YAML');
169	      console.error(err);
170	    } finally {
171	      setFixing(false);
172	    }
173	  };
174	
175	  const handleGenerate = async () => {
176	    setGenerating(true);
177	    try {
178	      const response = await kubernetesApi.generate(genResourceType, genForm);
179	      if (response.data.success) {
180	        setGeneratedYaml(response.data.data.yaml);
181	        toast.success('YAML generated successfully!');
182	      } else {
183	        toast.error(response.data.error?.message || 'Generation failed');
184	      }
185	    } catch (err) {
186	      toast.error('Failed to generate YAML');
187	      console.error(err);
188	    } finally {
189	      setGenerating(false);
190	    }
191	  };
192	
193	  const handleApplyFixed = () => {
194	    if (fixedYaml) {
195	      setYaml(fixedYaml);
196	      setViewMode('editor');
197	      toast.success('Fixed version applied');
198	    }
199	  };
200	
201	  const handleReset = () => {
202	    setYaml(DEFAULT_YAML);
203	    setAnalysis(null);
204	    setFixedYaml('');
205	    setViewMode('editor');
206	    toast.success('Reset to default');
207	  };
208	
209	  const handleDownload = () => {
210	    const content = viewMode === 'editor' ? yaml : fixedYaml || yaml;
211	    const blob = new Blob([content], { type: 'text/yaml' });
212	    const url = URL.createObjectURL(blob);
213	    const a = document.createElement('a');
214	    a.href = url;
215	    a.download = 'manifest.yaml';
216	    a.click();
217	    URL.revokeObjectURL(url);
218	    toast.success('Downloaded');
219	  };
220	
221	  const handleCopy = () => {
222	    const content = viewMode === 'editor' ? yaml : fixedYaml || yaml;
223	    navigator.clipboard.writeText(content);
224	    toast.success('Copied to clipboard');
225	  };
226	
227	  const filteredIssues = analysis?.issues.filter(issue => {
228	    if (!filterSeverity.includes(issue.severity)) return false;
229	    if (showOnlyFixable && !issue.fixable) return false;
230	    return true;
231	  }) || [];
232	
233	  const sortedIssues = [...filteredIssues].sort((a, b) =>
234	    (SEVERITY_ORDER[b.severity] || 0) - (SEVERITY_ORDER[a.severity] || 0)
235	  );
236	
237	  const severityCounts = analysis?.issues.reduce((acc, issue) => {
238	    acc[issue.severity] = (acc[issue.severity] || 0) + 1;
239	    return acc;
240	  }, {} as Record<string, number>) || {};
241	
242	  const toggleExpand = (finding: any) => {
243	    setExpandedFindings(prev => {
244	      const next = new Set(prev);
245	      if (next.has(finding.id)) next.delete(finding.id);
246	      else next.add(finding.id);
247	      return next;
248	    });
249	  };
250	
251	  const updateGenForm = (path: string, value: any) => {
252	    setGenForm(prev => {
253	      const keys = path.split('.');
254	      const updated = { ...prev } as any;
255	      let current = updated;
256	      for (let i = 0; i < keys.length - 1; i++) {
257	        current[keys[i]] = { ...current[keys[i]] };
258	        current = current[keys[i]];
259	      }
260	      current[keys[keys.length - 1]] = value;
261	      return updated;
262	    });
263	  };
264	
265	  const input = "input w-full px-3 py-2 bg-background-tertiary border border-border rounded-lg text-foreground text-sm focus:border-accent-blue focus:ring-1 focus:ring-accent-blue";
266	
267	  return (
268	    <div className="space-y-6 animate-fade-in">
269	      {/* Header */}
270	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
271	        <div>
272	          <h1 className="text-2xl font-bold text-foreground">Kubernetes YAML AI Assistant</h1>
273	          <p className="text-foreground-secondary mt-1">
