377	
378	              <div className="flex items-center gap-2">
379	                <button className="btn-primary" onClick={handleAnalyze} disabled={loading || !yaml.trim()}>
380	                  {loading ? (
381	                    <>
382	                      <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
383	                      Analyzing...
384	                    </>
385	                  ) : (
386	                    <>
387	                      <Shield className="w-4 h-4" />
388	                      Analyze
389	                    </>
390	                  )}
391	                </button>
392	                {analysis && !fixedYaml && (
393	                  <button className="btn-primary" onClick={handleFix} disabled={fixing}>
394	                    {fixing ? (
395	                      <>
396	                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
397	                        Fixing...
398	                      </>
399	                    ) : (
400	                      <>
401	                        <Sparkles className="w-4 h-4" />
402	                        AI Fix
403	                      </>
404	                    )}
405	                  </button>
406	                )}
407	                {fixedYaml && viewMode !== 'editor' && (
408	                  <button className="btn-secondary" onClick={handleApplyFixed}>
409	                    <CheckCircle className="w-4 h-4" />
410	                    Apply Fix
411	                  </button>
412	                )}
413	              </div>
414	            </div>
415	          </div>
416	
417	          {/* Content */}
418	          {viewMode === 'editor' && (
419	            <div className="card p-0 overflow-hidden">
420	              <CodeEditor
421	                value={yaml}
422	                onChange={setYaml}
423	                language="yaml"
424	                fileName="manifest.yaml"
425	                minHeight={500}
426	                placeholder="Paste or write your Kubernetes YAML here..."
427	              />
428	            </div>
429	          )}
430	
431	          {viewMode === 'diff' && fixedYaml && analysis && (
432	            <div className="card p-0 overflow-hidden">
433	              {analysis.explanation && (
