790	                    const url = URL.createObjectURL(blob);
791	                    const a = document.createElement('a');
792	                    a.href = url;
793	                    a.download = `${genForm.name}.yaml`;
794	                    a.click();
795	                    URL.revokeObjectURL(url);
796	                  }}>
797	                    <Download className="w-3.5 h-3.5" />
798	                  </button>
799	                </div>
800	              )}
