1	import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
2	import { api } from '../services/api';
3	import { User, AuthTokens, LoginCredentials, RegisterData } from '@devsecops/shared/types';
4	
5	interface AuthContextType {
6	  user: User | null;
7	  tokens: AuthTokens | null;
8	  loading: boolean;
9	  login: (credentials: LoginCredentials) => Promise<void>;
10	  loginWithTokens: (user: User, accessToken: string, refreshToken: string) => void;
11	  register: (data: RegisterData) => Promise<void>;
12	  logout: () => Promise<void>;
13	  refreshUser: () => Promise<void>;
14	  updateUser: (data: Partial<User>) => Promise<void>;
15	  updateProfile: (data: Partial<User>) => Promise<void>;
16	  isAuthenticated: boolean;
17	}
18	
19	const AuthContext = createContext<AuthContextType | undefined>(undefined);
20	
21	export function AuthProvider({ children }: { children: React.ReactNode }) {
22	  const [user, setUser] = useState<User | null>(null);
23	  const [tokens, setTokens] = useState<AuthTokens | null>(null);
24	  const [loading, setLoading] = useState(true);
25	
26	  const loadStoredAuth = useCallback(async () => {
27	    const storedTokens = localStorage.getItem('auth_tokens');
28	    if (storedTokens) {
29	      try {
30	        const parsed = JSON.parse(storedTokens);
31	        setTokens(parsed);
32	        api.defaults.headers.common['Authorization'] = `Bearer ${parsed.accessToken}`;
33	        await refreshUser();
34	      } catch {
35	        localStorage.removeItem('auth_tokens');
36	      }
37	    }
38	    setLoading(false);
39	  }, []);
40	
41	  const refreshUser = async () => {
42	    try {
43	      const response = await api.get('/api/auth/me');
44	      setUser(response.data.data);
45	    } catch {
46	      setUser(null);
47	      setTokens(null);
48	      localStorage.removeItem('auth_tokens');
49	      delete api.defaults.headers.common['Authorization'];
50	    }
51	  };
52	
53	  const login = async (credentials: LoginCredentials) => {
54	    const response = await api.post('/api/auth/login', credentials);
55	    const { user: userData, accessToken, refreshToken, expiresIn } = response.data.data;
56	    const tokensData: AuthTokens = { accessToken, refreshToken, expiresIn };
57	    setUser(userData);
58	    setTokens(tokensData);
59	    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
60	    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
61	  };
62	
63	  const register = async (data: RegisterData) => {
64	    const response = await api.post('/api/auth/register', data);
65	    const { user: userData, tokens: tokensData } = response.data.data;
66	    setUser(userData);
67	    setTokens(tokensData);
68	    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
69	    api.defaults.headers.common['Authorization'] = `Bearer ${tokensData.accessToken}`;
70	  };
71	
72	  const loginWithTokens = (userData: User, accessToken: string, refreshToken: string, expiresIn: number = 3600) => {
73	    const tokensData: AuthTokens = { accessToken, refreshToken, expiresIn };
74	    setUser(userData);
75	    setTokens(tokensData);
76	    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
77	    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
78	  };
79	
80	  const logout = async () => {
81	    try {
82	      await api.post('/api/auth/logout');
83	    } finally {
84	      setUser(null);
85	      setTokens(null);
86	      localStorage.removeItem('auth_tokens');
87	      delete api.defaults.headers.common['Authorization'];
88	    }
89	  };
90	
91	  const updateUser = async (data: Partial<User>) => {
92	    const response = await api.patch('/api/auth/me', data);
93	    setUser(response.data.data);
94	  };
95	
96	  const updateProfile = async (data: Partial<User>) => {
97	    const response = await api.patch('/api/auth/me', data);
98	    setUser(response.data.data);
99	  };
100	
101	  useEffect(() => {
102	    loadStoredAuth();
103	  }, [loadStoredAuth]);
104	
105	  return (
106	    <AuthContext.Provider
107	      value={{
108	        user,
109	        tokens,
110	        loading,
111	        login,
112	        loginWithTokens,
113	        register,
114	        logout,
115	        refreshUser,
116	        updateUser,
117	        updateProfile,
118	        isAuthenticated: !!user
119	      }}
120	    >
121	      {children}
122	    </AuthContext.Provider>
123	  );
124	}
125	
126	export function useAuth() {
127	  const context = useContext(AuthContext);
128	  if (!context) {
129	    throw new Error('useAuth must be used within an AuthProvider');
130	  }
131	  return context;
132	}

