import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { api } from '../services/api';
import { User, AuthTokens, LoginCredentials, RegisterData } from '@devsecops/shared/types';

interface AuthContextType {
  user: User | null;
  tokens: AuthTokens | null;
  loading: boolean;
  login: (credentials: LoginCredentials) => Promise<void>;
  loginWithTokens: (user: User, accessToken: string, refreshToken: string) => void;
  register: (data: RegisterData) => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<void>;
  updateUser: (data: Partial<User>) => Promise<void>;
  updateProfile: (data: Partial<User>) => Promise<void>;
  isAuthenticated: boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [tokens, setTokens] = useState<AuthTokens | null>(null);
  const [loading, setLoading] = useState(true);

  const loadStoredAuth = useCallback(async () => {
    const storedTokens = localStorage.getItem('auth_tokens');
    if (storedTokens) {
      try {
        const parsed = JSON.parse(storedTokens);
        setTokens(parsed);
        api.defaults.headers.common['Authorization'] = `Bearer ${parsed.accessToken}`;
        await refreshUser();
      } catch {
        localStorage.removeItem('auth_tokens');
      }
    }
    setLoading(false);
  }, []);

  const refreshUser = async () => {
    try {
      const response = await api.get('/api/auth/me');
      setUser(response.data.data);
    } catch {
      setUser(null);
      setTokens(null);
      localStorage.removeItem('auth_tokens');
      delete api.defaults.headers.common['Authorization'];
    }
  };

  const login = async (credentials: LoginCredentials) => {
    const response = await api.post('/api/auth/login', credentials);
    const { user: userData, accessToken, refreshToken, expiresIn } = response.data.data;
    const tokensData: AuthTokens = { accessToken, refreshToken, expiresIn };
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
  };

  const register = async (data: RegisterData) => {
    const response = await api.post('/api/auth/register', data);
    const { user: userData, tokens: tokensData } = response.data.data;
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${tokensData.accessToken}`;
  };

  const loginWithTokens = (userData: User, accessToken: string, refreshToken: string, expiresIn: number = 3600) => {
    const tokensData: AuthTokens = { accessToken, refreshToken, expiresIn };
    setUser(userData);
    setTokens(tokensData);
    localStorage.setItem('auth_tokens', JSON.stringify(tokensData));
    api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
  };

  const logout = async () => {
    try {
      await api.post('/api/auth/logout');
    } finally {
      setUser(null);
      setTokens(null);
      localStorage.removeItem('auth_tokens');
      delete api.defaults.headers.common['Authorization'];
    }
  };

  const updateUser = async (data: Partial<User>) => {
    const response = await api.patch('/api/auth/me', data);
    setUser(response.data.data);
  };

  const updateProfile = async (data: Partial<User>) => {
    const response = await api.patch('/api/auth/me', data);
    setUser(response.data.data);
  };

  useEffect(() => {
    loadStoredAuth();
  }, [loadStoredAuth]);

  return (
    <AuthContext.Provider
      value={{
        user,
        tokens,
        loading,
        login,
        loginWithTokens,
        register,
        logout,
        refreshUser,
        updateUser,
        updateProfile,
        isAuthenticated: !!user
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

