      if (response.data.success) {
        toast.success('Data imported successfully');
        loadSettings();
      } else {
        toast.error(response.data.error?.message || 'Import failed');
      }
    } catch (err) {
      toast.error('Import failed');
      console.error(err);
    }
    event.target.value = '';
  };

