67	  const [investigationResult, setInvestigationResult] = useState<LogInvestigationResult | null>(null);
68	  const [activeTab, setActiveTab] = useState<'upload' | 'search' | 'investigate'>('upload');
69	  const [filterLevel, setFilterLevel] = useState<string[]>([]);
70	  const [filterService, setFilterService] = useState<string[]>([]);
71	  const [timeRange, setTimeRange] = useState<{ start: Date | null; end: Date | null }>({ start: null, end: null });
72	  const [expandedEntries, setExpandedEntries] = useState<Set<string>>(new Set());
73	  const fileInputRef = useRef<HTMLInputElement>(null);
74	
75	  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
76	    const files = event.target.files;
77	    if (!files || files.length === 0) return;
78	
79	    setUploading(true);
80	    setUploadProgress(0);
81	
82	    for (const file of Array.from(files)) {
83	      try {
84	        const response = await logsApi.upload(file, setUploadProgress);
85	        if (response.data.success) {
86	          setLogFiles(prev => [response.data.data, ...prev]);
87	          toast.success(`Uploaded: ${file.name}`);
88	        } else {
89	          toast.error(response.data.error?.message || `Failed to upload ${file.name}`);
90	        }
91	      } catch (err) {
92	        toast.error(`Failed to upload ${file.name}`);
93	        console.error(err);
94	      }
95	    }
96	    setUploading(false);
97	    setUploadProgress(0);
98	    event.target.value = '';
99	  };
100	
101	  const handleDeleteLog = async (id: string) => {
102	    try {
103	      const response = await logsApi.delete(id);
104	      if (response.data.success) {
105	        setLogFiles(prev => prev.filter(f => f.id !== id));
106	        setSelectedLogFiles(prev => prev.filter(f => f !== id));
