109	        toast.error(response.data.error?.message || 'Delete failed');
110	      }
111	    } catch (err) {
112	      toast.error('Failed to delete');
113	      console.error(err);
114	    }
115	  };
116	
117	  const handleSearch = async () => {
118	    if (!searchQuery.trim() && selectedLogFiles.length === 0) {
119	      toast.error('Select at least one log file or enter a search query');
120	      return;
121	    }
122	    setSearching(true);
123	    try {
124	      const response = await logsApi.search(
125	        searchQuery,
126	        selectedLogFiles,
127	        timeRange.start && timeRange.end ? { start: timeRange.start.toISOString(), end: timeRange.end.toISOString() } : undefined,
128	        filterLevel.length > 0 ? filterLevel : undefined,
129	        filterService.length > 0 ? filterService : undefined
130	      );
131	      if (response.data.success) {
132	        setSearchResults(response.data.data);
133	        setActiveTab('search');
134	        toast.success(`Found ${response.data.data.total} entries`);
135	      } else {
136	        toast.error(response.data.error?.message || 'Search failed');
137	      }
138	    } catch (err) {
139	      toast.error('Search failed');
140	      console.error(err);
141	    } finally {
142	      setSearching(false);
143	    }
144	  };
145	
146	  const handleInvestigate = async () => {
147	    if (!investigationQuestion.trim() || selectedLogFiles.length === 0) {
148	      toast.error('Enter a question and select log files');
149	      return;
150	    }
151	    setInvestigating(true);
152	    try {
153	      const response = await logsApi.investigate(
154	        investigationQuestion,
155	        selectedLogFiles,
156	        timeRange.start && timeRange.end ? { start: timeRange.start.toISOString(), end: timeRange.end.toISOString() } : undefined
157	      );
158	      if (response.data.success) {
159	        setInvestigationResult(response.data.data);
160	        toast.success('Investigation complete!');
161	      } else {
162	        toast.error(response.data.error?.message || 'Investigation failed');
163	      }
164	    } catch (err) {
165	      toast.error('Investigation failed');
166	      console.error(err);
167	    } finally {
168	      setInvestigating(false);
169	    }
170	  };
171	
172	  const toggleLogSelection = (id: string) => {
173	    setSelectedLogFiles(prev =>
174	      prev.includes(id) ? prev.filter(f => f !== id) : [...prev, id]
175	    );
176	  };
177	
178	  const toggleExpand = (id: string) => {
179	    setExpandedEntries(prev => {
180	      const next = new Set(prev);
181	      if (next.has(id)) next.delete(id);
182	      else next.add(id);
183	      return next;
184	    });
185	  };
186	
187	  const getAvailableServices = () => {
188	    const services = new Set<string>();
189	    logFiles.forEach(f => f.services?.forEach((s: string) => services.add(s)));
190	    return Array.from(services);
191	  };
192	
193	  const getAvailableLevels = () => ['fatal', 'error', 'warn', 'info', 'debug', 'trace'];
194	
195	  return (
196	    <div className="space-y-6 animate-fade-in">
197	      {/* Header */}
198	      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
199	        <div>
200	          <h1 className="text-2xl font-bold text-foreground">AI Log Investigation</h1>
201	          <p className="text-foreground-secondary mt-1">
202	            Upload, search, and analyze logs with natural language queries
203	          </p>
204	        </div>
205	      </div>
206	
207	      {/* Tabs */}
208	      <div className="tabs">
209	        <button className={clsx('tab', activeTab === 'upload' && 'tab-active')} onClick={() => setActiveTab('upload')}>
210	          <Upload className="w-4 h-4" />
211	          Upload Logs
212	        </button>
213	        <button className={clsx('tab', activeTab === 'search' && 'tab-active')} onClick={() => setActiveTab('search')}>
214	          <Search className="w-4 h-4" />
215	          Search
216	        </button>
217	        <button className={clsx('tab', activeTab === 'investigate' && 'tab-active')} onClick={() => setActiveTab('investigate')}>
218	          <Sparkles className="w-4 h-4" />
219	          AI Investigate
220	        </button>
221	      </div>
222	
223	      {/* Upload Tab */}
224	      {activeTab === 'upload' && (
225	        <>
226	          <div className="card">
227	            <div className="mb-4">
