231	                onClick={() => fileInputRef.current?.click()}
232	                onDragOver={(e) => { e.preventDefault(); e.currentTarget.classList.add('border-accent-blue'); }}
233	                onDragLeave={(e) => { e.currentTarget.classList.remove('border-accent-blue'); }}
