252	                <p className="text-sm text-foreground-muted mt-1">Supports: .log, .txt, .json, .gz (max 25MB each)</p>
253	                {uploading && (
254	                  <div className="mt-4">
255	                    <div className="progress-bar mx-auto max-w-md">
