257	                    </div>
258	                    <p className="text-sm text-foreground-secondary mt-2">{uploadProgress}%</p>
259	                  </div>
260	                )}
261	              </div>
262	            </div>
263	
264	            {logFiles.length > 0 && (
265	              <div>
266	                <div className="flex items-center justify-between mb-4">
267	                  <h3 className="font-medium text-foreground">Uploaded Log Files</h3>
