269	                </div>
270	                <div className="space-y-2">
271	                  {logFiles.map((log) => (
272	                    <div
273	                      key={log.id}
274	                      className={clsx(
275	                        'p-3 bg-background-tertiary rounded-lg flex items-center justify-between transition-colors',
276	                        selectedLogFiles.includes(log.id) ? 'bg-accent-blue/10 border border-accent-blue/20' : ''
277	                      )}
278	                    >
279	                      <div className="flex items-center gap-3 flex-1 min-w-0">
280	                        <input
281	                          type="checkbox"
282	                          checked={selectedLogFiles.includes(log.id)}
283	                          onChange={() => toggleLogSelection(log.id)}
284	                          className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue mt-0.5"
285	                        />
286	                        <FileText className="w-5 h-5 text-accent-blue" />
287	                        <div className="min-w-0">
