292	                          </p>
293	                        </div>
294	                      </div>
295	                      <div className="flex items-center gap-2">
296	                        <span className="text-xs text-foreground-muted font-mono">
297	                          {log.format}
298	                        </span>
299	                        <button
300	                          className="btn-icon p-1.5 text-foreground-muted hover:text-severity-critical"
301	                          onClick={() => handleDeleteLog(log.id)}
302	                          disabled={uploading}
303	                        >
304	                          <Trash2 className="w-4 h-4" />
305	                        </button>
306	                      </div>
307	                    </div>
308	                  ))}
309	                </div>
310	              </div>
311	            )}
312	
313	            {selectedLogFiles.length > 0 && (
314	              <div className="mt-4 p-3 bg-accent-blue/10 border border-accent-blue/20 rounded-lg">
315	                <p className="font-medium text-accent-blue mb-2">{selectedLogFiles.length} file(s) selected</p>
316	                <div className="flex gap-2">
317	                  <button className="btn-primary" onClick={() => setActiveTab('search')}>
318	                    <Search className="w-4 h-4" />
319	                    Search Logs
320	                  </button>
321	                  <button className="btn-primary" onClick={() => setActiveTab('investigate')}>
322	                    <Sparkles className="w-4 h-4" />
323	                    AI Investigate
324	                  </button>
325	                </div>
326	              </div>
327	            )}
328	          </div>
329	        </>
330	      )}
331	
332	      {/* Search Tab */}
333	      {activeTab === 'search' && (
334	        <>
335	          <div className="card">
336	            <div className="mb-4">
337	              <label className="label">Search Query</label>
338	              <div className="relative">
339	                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
340	                <input
341	                  type="text"
342	                  value={searchQuery}
343	                  onChange={(e) => setSearchQuery(e.target.value)}
344	                  placeholder="Search logs... (e.g., error, timeout, 500, connection refused)"
