349	
350	            <div className="flex flex-wrap gap-4 mb-4">
351	              <div className="flex items-center gap-2">
352	                <Filter className="w-4 h-4 text-foreground-muted" />
353	                <select
354	                  className="input py-1.5 px-3 text-sm w-auto"
355	                  multiple
356	                  value={filterLevel}
357	                  onChange={(e) => {
358	                    const selected = Array.from(e.target.selectedOptions).map(o => o.value);
359	                    setFilterLevel(selected);
360	                  }}
361	                >
362	                  {getAvailableLevels().map(l => (
363	                    <option key={l} value={l} className="capitalize">{l}</option>
364	                  ))}
365	                </select>
366	              </div>
367	              <div className="flex items-center gap-2">
368	                <Filter className="w-4 h-4 text-foreground-muted" />
369	                <select
370	                  className="input py-1.5 px-3 text-sm w-auto"
371	                  multiple
372	                  value={filterService}
373	                  onChange={(e) => {
374	                    const selected = Array.from(e.target.selectedOptions).map(o => o.value);
375	                    setFilterService(selected);
376	                  }}
377	                >
378	                  {getAvailableServices().map(s => (
379	                    <option key={s} value={s}>{s}</option>
380	                  ))}
381	                </select>
382	              </div>
383	              <div className="flex items-center gap-2">
384	                <Clock className="w-4 h-4 text-foreground-muted" />
385	                <input
386	                  type="datetime-local"
387	                  value={timeRange.start ? timeRange.start.toISOString().slice(0, 16) : ''}
388	                  onChange={(e) => setTimeRange({ ...timeRange, start: e.target.value ? new Date(e.target.value) : null })}
389	                  className="input py-1.5 px-3 text-sm w-auto"
390	                />
391	                <span className="text-foreground-muted">to</span>
392	                <input
393	                  type="datetime-local"
394	                  value={timeRange.end ? timeRange.end.toISOString().slice(0, 16) : ''}
395	                  onChange={(e) => setTimeRange({ ...timeRange, end: e.target.value ? new Date(e.target.value) : null })}
396	                  className="input py-1.5 px-3 text-sm w-auto"
397	                />
398	              </div>
399	            </div>
400	
401	            <button className="btn-primary" onClick={handleSearch} disabled={searching || (!searchQuery.trim() && selectedLogFiles.length === 0)}>
402	              {searching ? (
403	                <>
404	                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
405	                  Searching...
406	                </>
407	              ) : (
408	                <>
409	                  <Search className="w-4 h-4" />
410	                  Search
411	                </>
412	              )}
413	            </button>
414	          </div>
415	
416	          {searchResults && (
417	            <div className="card">
418	              <div className="flex items-center justify-between mb-4">
419	                <h3 className="font-medium text-foreground">Results ({searchResults.total})</h3>
420	                <div className="flex gap-2">
421	                  <button className="btn-secondary text-sm">
422	                    <Download className="w-3.5 h-3.5" />
423	                    Export
424	                  </button>
425	                </div>
426	              </div>
427	              <div className="max-h-96 overflow-y-auto">
428	                {searchResults.entries.map((entry: LogEntry) => (
429	                  <div
430	                    key={entry.id}
431	                    className={clsx(
432	                      'p-3 border-b border-border/50 hover:bg-background-tertiary/50 transition-colors cursor-pointer',
433	                      expandedEntries.has(entry.id) ? 'bg-background-tertiary/50' : ''
434	                    )}
435	                    onClick={() => toggleExpand(entry.id)}
436	                  >
437	                    <div className="flex items-start gap-3">
438	                      <span
439	                        className={clsx('px-2 py-0.5 rounded text-xs font-mono font-medium flex-shrink-0', LEVEL_COLORS[entry.level])}
440	                      >
441	                        {entry.level.toUpperCase()}
442	                      </span>
443	                      <div className="flex-1 min-w-0">
444	                        <div className="flex items-center gap-2 text-sm">
445	                          <span className="font-mono text-foreground">{entry.timestamp}</span>
446	                          {entry.service && (
447	                            <span className="badge badge-info">{entry.service}</span>
448	                          )}
449	                        </div>
450	                        <p className="text-foreground-secondary text-sm mt-1 truncate">{entry.message}</p>
451	                        {expandedEntries.has(entry.id) && (
452	                          <div className="mt-2 code-block">
453	                            <pre className="whitespace-pre-wrap text-xs"><code>{JSON.stringify(entry.fields, null, 2)}</code></pre>
454	                          </div>
