458	                    </div>
459	                  </div>
460	                ))}
461	              </div>
462	            </div>
463	          )}
464	        </>
465	      )}
466	
467	      {/* Investigate Tab */}
468	      {activeTab === 'investigate' && (
469	        <>
470	          <div className="card">
471	            <div className="mb-4">
472	              <label className="label">Ask a question about your logs</label>
473	              <textarea
474	                value={investigationQuestion}
475	                onChange={(e) => setInvestigationQuestion(e.target.value)}
476	                placeholder="e.g., Why did the application fail yesterday? What caused the spike at 14:30?"
477	                className="input min-h-[100px] resize-y"
478	                rows={3}
479	              />
480	            </div>
481	
482	            <div className="mb-4">
483	              <p className="label">Suggested questions</p>
484	              <div className="flex flex-wrap gap-2">
485	                {SAMPLE_QUESTIONS.map((q, i) => (
486	                  <button
487	                    key={i}
488	                    className="btn-secondary text-sm px-3 py-1.5"
489	                    onClick={() => setInvestigationQuestion(q)}
490	                    disabled={investigating}
491	                  >
492	                    {q}
493	                  </button>
494	                ))}
495	              </div>
496	            </div>
497	
498	            <button
499	              className="btn-primary w-full"
500	              onClick={handleInvestigate}
501	              disabled={investigating || !investigationQuestion.trim() || selectedLogFiles.length === 0}
502	            >
503	              {investigating ? (
504	                <>
505	                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
506	                  Investigating...
507	                </>
508	              ) : (
509	                <>
510	                  <Sparkles className="w-4 h-4" />
511	                  Investigate
512	                </>
513	              )}
514	            </button>
