setScanning(true);
setFindings([]);
setSummary(null);
try {
  const response = await githubApi.scan(repoUrl.trim(), branch, scanTypes);
  if (response.data.success) {
    setScanId(response.data.data.scanId);
    setScanStatus('running');
    toast.success('Scan started. This may take a few minutes.');

    // Poll for status
    const poll = setInterval(async () => {
      try {
        const statusRes = await githubApi.scanStatus(response.data.data.scanId);
        if (statusRes.data.success) {
          setScanStatus(statusRes.data.data.status);
          setProgress(statusRes.data.data.progress || 0);

          if (statusRes.data.data.status === 'completed') {
            clearInterval(poll);
            const resultsRes = await githubApi.scanResults(response.data.data.scanId);
            if (resultsRes.data.success) {
              const data = resultsRes.data.data;
              const allFindings = [
                ...(data.vulnerabilities || []).map((v: any) => ({
                  id: v.id,
                  scanId: response.data.data.scanId,
                  type: 'vulnerability' as const,
                  severity: v.severity,
                  title: `${v.package}: ${v.id}`,
                  description: v.description,
                  package: v.package,
                  installedVersion: v.installedVersion,
                  fixedVersion: v.fixedVersion,
                  cve: v.id,
                  fixable: v.fixAvailable,
                  remediation: v.fixAvailable ? {
