                  status: 'open' as const,
                  createdAt: new Date().toISOString()
                })),
                ...(data.secrets || []).map((s: any) => ({
                  id: s.id,
                  scanId: response.data.data.scanId,
                  type: 'secret' as const,
                  severity: s.severity,
                  title: `Secret detected: ${s.type}`,
