                  file: s.file,
                  line: s.line,
                  ruleId: s.rule,
                  fixable: false,
                  status: 'open' as const,
                  createdAt: new Date().toISOString()
                })),
                ...(data.codeIssues || []).map((c: any) => ({
                  id: c.id,
                  scanId: response.data.data.scanId,
                  type: 'security_issue' as const,
                  severity: c.severity,
                  title: c.message,
                  description: c.message,
                  file: c.file,
                  line: c.line,
                  code: c.code,
                  ruleId: c.ruleId,
                  fixable: c.fixable,
                  remediation: c.fixable ? {
                    available: true,
                    type: 'patch' as const,
                    description: c.suggestion || 'AI will generate a fix',
                    steps: ['Run AI Fix to generate patch'],
                    confidence: 80
                  } : undefined,
                  status: 'open' as const,
                  createdAt: new Date().toISOString()
                }))
              ];
              setFindings(allFindings);
              setSummary(data.summary || {});
              toast.success('Scan complete!');
            }
            setScanning(false);
          } else if (statusRes.data.data.status === 'failed') {
            clearInterval(poll);
            toast.error('Scan failed');
            setScanning(false);
          }
        }
      } catch (err) {
        console.error(err);

