import React, { useState, useCallback, useRef } from 'react';
import {
  Upload,
  Download,
  Copy,
  RotateCcw,
  Sparkles,
  Shield,
  AlertTriangle,
  CheckCircle,
  Info,
  FileText,
  Wand2,
  Filter,
  GitBranch,
  Server,
  RefreshCw,
  Search
} from 'lucide-react';
import { jenkinsApi } from '../services/api';
import { JenkinsfileAnalysis, JenkinsfileIssue, JenkinsGeneratorConfig } from '@devsecops/shared/types';
import { CodeEditor } from '../components/CodeEditor';
import { DiffViewer } from '../components/DiffViewer';
import { FindingCard, FindingList } from '../components/FindingCard';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

const DEFAULT_JENKINSFILE = `pipeline {
    agent any

    stages {
        stage('Build') {
            steps {
                sh 'npm install'
                sh 'npm run build'
            }
        }
        stage('Test') {
            steps {
                sh 'npm test'
            }
        }
        stage('Deploy') {
            steps {
                sh 'docker build -t myapp .'
                sh 'docker push myapp'
                sh 'kubectl apply -f k8s/'
            }
        }
    }
}`;

const SEVERITY_ORDER: Record<string, number> = {
  critical: 5,
  high: 4,
  medium: 3,
  low: 2,
  info: 1
};

export function JenkinsAssistant() {
  const [jenkinsfile, setJenkinsfile] = useState(DEFAULT_JENKINSFILE);
  const [analysis, setAnalysis] = useState<JenkinsfileAnalysis | null>(null);
  const [fixedJenkinsfile, setFixedJenkinsfile] = useState('');
  const [loading, setLoading] = useState(false);
  const [fixing, setFixing] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [viewMode, setViewMode] = useState<'editor' | 'diff' | 'findings'>('editor');
  const [activeTab, setActiveTab] = useState<'fixer' | 'generator'>('fixer');
  const [filterSeverity, setFilterSeverity] = useState<string[]>(['critical', 'high', 'medium', 'low', 'info']);
  const [showOnlyFixable, setShowOnlyFixable] = useState(false);
  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
  const [jenkinsServers, setJenkinsServers] = useState<any[]>([]);
  const [selectedServer, setSelectedServer] = useState<string>('');
  const [showConnectModal, setShowConnectModal] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Generator form
  const [genForm, setGenForm] = useState<JenkinsGeneratorConfig>({
    application: 'nodejs',
    repositoryUrl: 'https://github.com/user/repo',
    buildTool: 'npm',
    testing: true,
    dockerBuild: true,
    securityScan: true,
    dockerPush: true,
    deployment: 'kubernetes',
    environments: ['dev', 'staging', 'production'],
    registryUrl: 'docker.io/myorg',
    kubernetesConfig: {
      name: 'my-app',
      image: 'nginx:latest',
      replicas: 3,
      port: 80,
      cpuRequest: '250m',
      memoryRequest: '256Mi'
    }
  });
  const [generatedJenkinsfile, setGeneratedJenkinsfile] = useState('');

