226	export function FindingList({
227	  findings,
228	  onFix,
229	  onIgnore,
230	  expandedIds = new Set(),
231	  onToggleExpand,
232	  showActions = true,
233	  emptyMessage = 'No findings'
234	}: {
235	  findings: Finding[];
236	  onFix?: (finding: Finding) => void;
237	  onIgnore?: (finding: Finding) => void;
238	  expandedIds?: Set<string>;
239	  onToggleExpand?: (finding: Finding) => void;
240	  showActions?: boolean;
241	  emptyMessage?: string;
242	}) {
243	  if (findings.length === 0) {
244	    return (
245	      <div className="card text-center py-12">
246	        <AlertTriangle className="w-12 h-12 text-foreground-muted mx-auto mb-4 opacity-50" />
247	        <p className="text-foreground-secondary">{emptyMessage}</p>
248	      </div>
249	    );

1	/**
2	 * Shared type definitions for the DevSecOps AI Platform
3	 */
4	
5	// ============================================
6	// Common / Base Types
7	// ============================================
8	
9	export type UUID = string & { readonly __brand: unique symbol };
10	export type ISODateString = string & { readonly __brand: unique symbol };
11	
12	export interface BaseEntity {
13	  id: UUID;
14	  createdAt: ISODateString;
15	  updatedAt: ISODateString;
16	}
17	
18	export interface PaginatedResponse<T> {
19	  data: T[];
20	  total: number;
21	  page: number;
22	  pageSize: number;
23	  totalPages: number;
24	}
25	
26	export type SortOrder = 'asc' | 'desc';
27	
28	export interface SortOptions {
29	  field: string;
30	  order: SortOrder;
31	}
