import { FastifyInstance } from 'fastify';
import { authRoutes } from './auth/routes';
import { dockerfileRoutes } from './dockerfile/routes';
import { dockerRoutes } from './docker/routes';
import { kubernetesRoutes } from './kubernetes/routes';
import { jenkinsRoutes } from './jenkins/routes';
import { githubRoutes } from './github/routes';
import { logsRoutes } from './logs/routes';
import { dependenciesRoutes } from './dependencies/routes';
import { scansRoutes } from './scans/routes';
import { settingsRoutes } from './settings/routes';
import { aiRoutes } from './ai/routes';
import { jobsRoutes } from './jobs/routes';

export async function registerRoutes(app: FastifyInstance) {
  // API routes
  await app.register(authRoutes, { prefix: '/api/auth' });
  await app.register(dockerfileRoutes, { prefix: '/api/dockerfile' });
  await app.register(dockerRoutes, { prefix: '/api/docker' });
  await app.register(kubernetesRoutes, { prefix: '/api/kubernetes' });
  await app.register(jenkinsRoutes, { prefix: '/api/jenkins' });
  await app.register(githubRoutes, { prefix: '/api/github' });
  await app.register(logsRoutes, { prefix: '/api/logs' });
  await app.register(dependenciesRoutes, { prefix: '/api/dependencies' });
  await app.register(scansRoutes, { prefix: '/api/scans' });
  await app.register(settingsRoutes, { prefix: '/api/settings' });
  await app.register(aiRoutes, { prefix: '/api/ai' });
  await app.register(jobsRoutes, { prefix: '/api/jobs' });
}

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import {
  Container,
  ShieldCheck,
  Boxes,
  GitBranch,
  Github,
  FileSearch,
  Radar,
  History,
  AlertTriangle,
  CheckCircle,
  TrendingUp,
  TrendingDown,
  Clock,
  Zap,
  ExternalLink,
  RefreshCw
} from 'lucide-react';
import { scansApi, jobsApi } from '../services/api';
import { Scan, Job } from '@devsecops/shared/types';
import { CardSkeleton } from '../components/LoadingScreen';
import { formatDistanceToNow } from 'date-fns';
import { clsx } from 'clsx';

const QUICK_ACTIONS = [
  { path: '/dockerfile', label: 'Analyze Dockerfile', description: 'Scan & fix Dockerfile issues', icon: Container, color: 'text-accent-blue' },
  { path: '/docker', label: 'Scan Docker Image', description: 'Find vulnerabilities in images', icon: ShieldCheck, color: 'text-accent-green' },
  { path: '/kubernetes', label: 'Kubernetes YAML', description: 'Validate & generate K8s configs', icon: Boxes, color: 'text-accent-purple' },
  { path: '/jenkins', label: 'Jenkins Pipeline', description: 'Fix & generate Jenkinsfiles', icon: GitBranch, color: 'text-accent-yellow' },
  { path: '/github', label: 'GitHub Security', description: 'Scan repos for vulnerabilities', icon: Github, color: 'text-foreground' },
  { path: '/logs', label: 'Investigate Logs', description: 'AI-powered log analysis', icon: FileSearch, color: 'text-accent-cyan' },
  { path: '/dependencies', label: 'Dependency Risk', description: 'Scan & fix vulnerable deps', icon: Radar, color: 'text-accent-purple' },
  { path: '/scans', label: 'Scan History', description: 'View all past scans', icon: History, color: 'text-foreground-muted' },
];

const STATS = [
  { label: 'Total Scans', value: '0', change: '+12%', trend: 'up', icon: CheckCircle, color: 'text-accent-green' },
  { label: 'Vulnerabilities Found', value: '0', change: '+5%', trend: 'up', icon: AlertTriangle, color: 'text-severity-critical' },
  { label: 'Critical Issues', value: '0', change: '-3%', trend: 'down', icon: AlertTriangle, color: 'text-severity-critical' },
  { label: 'Issues Fixed', value: '0', change: '+8%', trend: 'up', icon: Zap, color: 'text-accent-blue' },
];

export function Dashboard() {
  const [stats, setStats] = useState(STATS);
  const [recentScans, setRecentScans] = useState<Scan[]>([]);
  const [recentJobs, setRecentJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadDashboardData();
  }, []);

  const loadDashboardData = async () => {
    try {
      setLoading(true);
      const [scansRes, jobsRes] = await Promise.all([
        scansApi.list({ page: 1, pageSize: 10 }),
        jobsApi.list({ page: 1, pageSize: 10 })
      ]);

      if (scansRes.data.success) {
        setRecentScans(scansRes.data.data?.data || []);
        // Update stats based on actual data
        const allScans = scansRes.data.data?.data || [];
        setStats([
          { ...STATS[0], value: allScans.length.toString() },
          {
            ...STATS[1],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.totalFindings || 0), 0).toString()
          },
          {
            ...STATS[2],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.critical || 0), 0).toString()
          },
          {
            ...STATS[3],
            value: allScans.reduce((sum: number, s: Scan) => sum + (s.summary?.fixedCount || 0), 0).toString()
          }
        ]);
      }

      if (jobsRes.data.success) {
        setRecentJobs(jobsRes.data.data?.data || []);
      }
    } catch (err) {
      console.error('Failed to load dashboard data', err);
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status: Job['status']) => {
    switch (status) {
      case 'completed': return 'text-accent-green';
      case 'failed': return 'text-severity-critical';
      case 'running':
      case 'analyzing':
      case 'fixing': return 'text-accent-blue';
      case 'queued': return 'text-foreground-muted';
      default: return 'text-foreground-secondary';
    }
  };

  const getStatusIcon = (status: Job['status']) => {
    switch (status) {
      case 'completed': return <CheckCircle className="w-4 h-4" />;
      case 'failed': return <AlertTriangle className="w-4 h-4" />;
      case 'running':
      case 'analyzing':
      case 'fixing': return <RefreshCw className="w-4 h-4 animate-spin" />;
      case 'queued': return <Clock className="w-4 h-4" />;
      default: return <Clock className="w-4 h-4" />;
    }
  };

  if (loading) {
    return (
      <div className="space-y-6 animate-fade-in">
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map(i => <CardSkeleton key={i} />)}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <CardSkeleton />
          <CardSkeleton />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Dashboard</h1>
          <p className="text-foreground-secondary mt-1">Your DevSecOps command center overview</p>
        </div>
        <button className="btn-secondary" onClick={loadDashboardData}>
          <RefreshCw className="w-4 h-4" />
          Refresh
        </button>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, index) => (
          <div key={index} className="stat-card">
            <div className="flex items-start justify-between">
              <div>
                <p className="stat-label">{stat.label}</p>
                <p className="stat-value">{stat.value}</p>
                <div className="stat-trend">
                  {stat.trend === 'up' ? (
                    <TrendingUp className="w-4 h-4 text-accent-green" />
                  ) : (
                    <TrendingDown className="w-4 h-4 text-severity-critical" />
                  )}
                  <span className={clsx('font-medium', stat.color)}>{stat.change}</span>
                </div>
              </div>
              <div className={`p-3 rounded-xl bg-background-tertiary ${stat.color.replace('text-', 'bg-')}/10`}>
                <stat.icon className={`w-6 h-6 ${stat.color}`} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Main Content Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column - Quick Actions & Recent Scans */}
        <div className="lg:col-span-2 space-y-6">
          {/* Quick Actions */}
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Quick Actions</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
              {QUICK_ACTIONS.map((action, i) => {
                const Icon = action.icon;
                return (
                  <Link
                    key={i}
                    to={action.path}
                    className="card p-4 hover:shadow-card-hover transition-shadow group"
                  >
                    <div className={`p-2 rounded-lg bg-background-tertiary ${action.color} mb-3`}>
                      <Icon className="w-5 h-5" />
                    </div>
                    <h3 className="font-medium text-foreground">{action.label}</h3>
                    <p className="text-sm text-foreground-secondary mt-1">{action.description}</p>
                    <div className="mt-3 flex items-center text-accent-blue text-sm group-hover:gap-1 transition-all">
                      <span>Open</span>
                      <ExternalLink className="w-3.5 h-3.5" />
                    </div>
                  </Link>
                );
              })}
            </div>
          </div>

          {/* Recent Scans */}
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Recent Scans</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            {recentScans.length === 0 ? (
              <div className="text-center py-8 text-foreground-secondary">
                <Container className="w-12 h-12 mx-auto mb-3 opacity-50" />
                <p>No scans yet</p>
                <p className="text-sm mt-1">Start by scanning a Dockerfile, image, or repository</p>
                <div className="mt-4 flex gap-2 justify-center">
                  <Link to="/dockerfile" className="btn-primary text-sm">Scan Dockerfile</Link>
                  <Link to="/docker" className="btn-secondary text-sm">Scan Image</Link>
                </div>
              </div>
            ) : (
              <div className="table-container">
                <table className="table">
                  <thead>
                    <tr>
                      <th>Type</th>
                      <th>Target</th>
                      <th>Status</th>
                      <th>Findings</th>
                      <th>Date</th>
                    </tr>
                  </thead>
                  <tbody>
                    {recentScans.map((scan) => (
                      <tr key={scan.id}>
                        <td>
                          <span className="badge badge-info capitalize">{scan.type.replace('_', ' ')}</span>
                        </td>
                        <td className="font-mono text-sm max-w-[200px] truncate">{scan.target?.value || 'Unknown'}</td>
                        <td>
                          <span className={clsx('badge', {
                            'badge-success': scan.status === 'completed',
                            'badge-critical': scan.status === 'failed',
                            'badge-medium': scan.status === 'running',
                            'badge-info': scan.status === 'pending'
                          })}>
                            {scan.status}
                          </span>
                        </td>
                        <td>
                          {scan.summary && (
                            <div className="flex items-center gap-1">
                              {scan.summary.critical > 0 && <span className="badge badge-critical">{scan.summary.critical}</span>}
                              {scan.summary.high > 0 && <span className="badge badge-high">{scan.summary.high}</span>}
                              {scan.summary.medium > 0 && <span className="badge badge-medium">{scan.summary.medium}</span>}
                              {scan.summary.low > 0 && <span className="badge badge-low">{scan.summary.low}</span>}
                              {scan.summary.info > 0 && <span className="badge badge-info">{scan.summary.info}</span>}
                              {(scan.summary.totalFindings || 0) === 0 && <span className="badge badge-success">Clean</span>}
                            </div>
                          )}
                        </td>
                        <td className="text-foreground-secondary">
                          {formatDistanceToNow(new Date(scan.createdAt), { addSuffix: true })}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* Right Column - Recent Jobs */}
        <div className="space-y-6">
          <div className="card">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground">Recent Jobs</h2>
              <Link to="/scans" className="text-sm text-accent-blue hover:underline">View all</Link>
            </div>
            {recentJobs.length === 0 ? (
              <div className="text-center py-8 text-foreground-secondary">
                <Zap className="w-12 h-12 mx-auto mb-3 opacity-50" />
                <p>No jobs running</p>
                <p className="text-sm mt-1">Jobs appear here when you start scans or fixes</p>
              </div>
            ) : (
              <div className="space-y-3">
                {recentJobs.map((job) => (
                  <div key={job.id} className="flex items-center gap-3 p-3 bg-background-tertiary rounded-lg">
                    <div className={clsx('p-2 rounded-lg', getStatusColor(job.status).replace('text-', 'bg-') + '/10')}>
                      {getStatusIcon(job.status)}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-medium text-foreground truncate">{job.type.replace('_', ' ')}</p>
                      <p className="text-sm text-foreground-secondary truncate">{job.currentStep || 'Queued'}</p>
                    </div>
                    <div className="flex items-center gap-3">
                      <div className="w-20">
                        <div className="progress-bar">
                          <div
                            className="progress-fill"
                            style={{ width: `${job.progress}%` }}
                          />
                        </div>
                      </div>
                      <span className={clsx('text-sm font-medium', getStatusColor(job.status))}>
                        {job.status}
                      </span>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* System Health */}
          <div className="card">
            <h2 className="text-lg font-semibold text-foreground mb-4">System Health</h2>
            <div className="grid grid-cols-2 gap-4">
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">API Status</p>
                <p className="font-medium text-accent-green flex items-center gap-1">
                  <CheckCircle className="w-4 h-4" /> Operational
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">Job Queue</p>
                <p className="font-medium text-accent-blue flex items-center gap-1">
                  <Clock className="w-4 h-4" /> {recentJobs.filter(j => j.status === 'queued').length} queued
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">Active Scans</p>
                <p className="font-medium text-accent-blue flex items-center gap-1">
                  <Zap className="w-4 h-4" /> {recentJobs.filter(j => ['running', 'analyzing', 'fixing'].includes(j.status)).length} running
                </p>
              </div>
              <div className="p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">AI Service</p>
                <p className="font-medium text-accent-green flex items-center gap-1">
                  <CheckCircle className="w-4 h-4" /> Connected
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import {
  Github,
  Shield,
  AlertTriangle,
  Key,
  Sparkles,
  GitBranch,
  Lock,
  Package,
  Code2,
  Zap,
  GitPullRequest,
  ChevronDown
} from 'lucide-react';
import { githubApi } from '../services/api';
import { Finding, Severity } from '@devsecops/shared/types';
import { FindingList } from '../components/FindingCard';
import { CodeEditor } from '../components/CodeEditor';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

const SEVERITY_ORDER: Record<Severity, number> = {
  critical: 5,
  high: 4,
  medium: 3,
  low: 2,
  info: 1
};

export function GitHubSecurity() {
  const [connected, setConnected] = useState(false);
  const [token, setToken] = useState('');
  const [repoUrl, setRepoUrl] = useState('');
  const [branch, setBranch] = useState('main');
  const [scanTypes, setScanTypes] = useState<string[]>(['vulnerabilities', 'secrets', 'dependencies', 'code']);
  const [scanning, setScanning] = useState(false);
  const [scanStatus, setScanStatus] = useState('');
  const [progress, setProgress] = useState(0);
  const [findings, setFindings] = useState<Finding[]>([]);
  const [summary, setSummary] = useState<any>(null);
  const [filterSeverity, setFilterSeverity] = useState<Severity[]>(['critical', 'high', 'medium', 'low', 'info']);
  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
  const [selectedFinding, setSelectedFinding] = useState<Finding | null>(null);
  const [fixResult, setFixResult] = useState<any>(null);
  const [showTokenModal, setShowTokenModal] = useState(false);

  const handleConnect = async () => {
    if (!token.trim()) {
      toast.error('Please enter a GitHub token');
      return;
    }
    try {
      const response = await githubApi.connect(token.trim());
      if (response.data.success) {
        setConnected(true);
        setToken('');
        setShowTokenModal(false);
        toast.success('GitHub connected successfully');
      } else {
        toast.error(response.data.error?.message || 'Connection failed');
      }
    } catch (err) {
      toast.error('Failed to connect GitHub');
      console.error(err);
    }
  };

  const handleScan = async () => {
    if (!repoUrl.trim()) {
      toast.error('Please enter a repository URL');
      return;
    }
    setScanning(true);
    setFindings([]);
    setSummary(null);
    try {
      const response = await githubApi.scan(repoUrl.trim(), branch, scanTypes);
      if (response.data.success) {
        const scanId = response.data.data.scanId;
        setScanStatus('running');
        toast.success('Scan started. This may take a few minutes.');

        // Poll for status
        const poll = setInterval(async () => {
          try {
            const statusRes = await githubApi.scanStatus(scanId);
            if (statusRes.data.success) {
              setScanStatus(statusRes.data.data.status);
              setProgress(statusRes.data.data.progress || 0);

              if (statusRes.data.data.status === 'completed') {
                clearInterval(poll);
                const resultsRes = await githubApi.scanResults(scanId);
                if (resultsRes.data.success) {
                  const data = resultsRes.data.data;
                  const allFindings = [
                    ...(data.vulnerabilities || []).map((v: any) => ({
                      id: v.id,
                      scanId: scanId,
                      type: 'vulnerability' as const,
                      severity: v.severity,
                      title: `${v.package}: ${v.id}`,
                      description: v.description,
                      package: v.package,
                      installedVersion: v.installedVersion,
                      fixedVersion: v.fixedVersion,
                      cve: v.id,
                      fixable: v.fixAvailable,
                      remediation: v.fixAvailable ? {
                        available: true,
                        type: 'upgrade' as const,
                        description: `Upgrade ${v.package} to ${v.fixedVersion || 'latest'}`,
                        steps: [`npm update ${v.package}@${v.fixedVersion || 'latest'}`],
                        confidence: 90
                      } : undefined,
                      status: 'open' as const,
                      createdAt: new Date().toISOString()
                    })),
                    ...(data.secrets || []).map((s: any) => ({
                      id: s.id,
                      scanId: scanId,
                      type: 'secret' as const,
                      severity: s.severity,
                      title: `Secret detected: ${s.type}`,
                      description: s.message,
                      file: s.file,
                      line: s.line,
                      ruleId: s.rule,
                      fixable: false,
                      status: 'open' as const,
                      createdAt: new Date().toISOString()
                    })),
                    ...(data.codeIssues || []).map((c: any) => ({
                      id: c.id,
                      scanId: scanId,
                      type: 'security_issue' as const,
                      severity: c.severity,
                      title: c.message,
                      description: c.message,
                      file: c.file,
                      line: c.line,
                      code: c.code,
                      ruleId: c.ruleId,
                      fixable: c.fixable,
                      remediation: c.fixable ? {
                        available: true,
                        type: 'patch' as const,
                        description: c.suggestion || 'AI will generate a fix',
                        steps: ['Run AI Fix to generate patch'],
                        confidence: 80
                      } : undefined,
                      status: 'open' as const,
                      createdAt: new Date().toISOString()
                    }))
                  ];
                  setFindings(allFindings);
                  setSummary(data.summary || {});
                  toast.success('Scan complete!');
                }
                setScanning(false);
              } else if (statusRes.data.data.status === 'failed') {
                clearInterval(poll);
                toast.error('Scan failed');
                setScanning(false);
              }
            }
          } catch (err) {
            console.error(err);
          }
        }, 3000);
      } else {
        toast.error(response.data.error?.message || 'Scan failed');
        setScanning(false);
      }
    } catch (err) {
      toast.error('Failed to start scan');
      console.error(err);
      setScanning(false);
    }
  };

  const handleFix = async (finding: Finding) => {
    setSelectedFinding(finding);
    try {
      const response = await githubApi.fix(finding.id, 'repo-id', branch, 'patch');
      if (response.data.success) {
        setFixResult(response.data.data);
        toast.success('Fix generated successfully!');
      } else {
        toast.error(response.data.error?.message || 'Fix failed');
      }
    } catch (err) {
      toast.error('Failed to generate fix');
      console.error(err);
    }
  };

  const handleCreatePR = async () => {
    try {
      const response = await githubApi.createPR({
        repoId: 'repo-id',
        branch: `fix/${selectedFinding?.id}`,
        title: `Fix: ${selectedFinding?.title}`,
        body: fixResult?.explanation || '',
        changes: fixResult?.changes || []
      });
      if (response.data.success) {
        toast.success('Pull request created!');
      } else {
        toast.error(response.data.error?.message || 'PR creation failed');
      }
    } catch (err) {
      toast.error('Failed to create PR');
      console.error(err);
    }
  };

  const toggleExpand = (finding: Finding) => {
    setExpandedFindings(prev => {
      const next = new Set(prev);
      if (next.has(finding.id)) next.delete(finding.id);
      else next.add(finding.id);
      return next;
    });
  };

  const filteredFindings = findings.filter(f => filterSeverity.includes(f.severity));
  const sortedFindings = [...filteredFindings].sort((a, b) =>
    SEVERITY_ORDER[b.severity] - SEVERITY_ORDER[a.severity]
  );

  const severityCounts = findings.reduce((acc, f) => {
    acc[f.severity] = (acc[f.severity] || 0) + 1;
    return acc;
  }, {} as Record<Severity, number>);

  const securityScore = summary?.securityScore || 0;
  const depsScore = summary?.dependenciesScore || 0;
  const secretsScore = summary?.secretsScore || 0;
  const codeScore = summary?.codeScore || 0;

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">GitHub Repository Security</h1>
          <p className="text-foreground-secondary mt-1">
            Clone, scan, and secure your repositories with AI-powered fixes
          </p>
        </div>
        <button
          className="btn-secondary"
          onClick={() => connected ? setConnected(false) : setShowTokenModal(true)}
        >
          <Key className="w-4 h-4" />
          {connected ? 'Disconnect' : 'Connect GitHub'}
        </button>
      </div>

      {/* Token Modal */}
      {showTokenModal && (
        <div className="modal-overlay" onClick={() => setShowTokenModal(false)}>
          <div className="modal-content w-full max-w-md p-6" onClick={(e) => e.stopPropagation()}>
            <h2 className="text-lg font-semibold text-foreground mb-4 flex items-center gap-2">
              <Key className="w-5 h-5" />
              Connect GitHub
            </h2>
            <div className="space-y-4">
              <div>
                <label className="label">Personal Access Token</label>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="ghp_..."
                  className="input"
                />
                <p className="text-xs text-foreground-muted mt-1">
                  Token is encrypted and stored server-side. Never exposed in frontend.
                </p>
              </div>
              <div className="flex gap-2">
                <button className="btn-secondary flex-1" onClick={() => setShowTokenModal(false)}>
                  Cancel
                </button>
                <button className="btn-primary flex-1" onClick={handleConnect}>
                  Connect
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Input Section */}
      <div className="card">
        <div className="flex flex-col lg:flex-row gap-4">
          <div className="flex-1">
            <label className="label">Repository URL</label>
            <div className="relative">
              <Github className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-foreground-muted" />
              <input
                type="text"
                value={repoUrl}
                onChange={(e) => setRepoUrl(e.target.value)}
                placeholder="https://github.com/user/repo"
                className="input pl-10"
                disabled={scanning}
              />
            </div>
          </div>
          <div className="w-full lg:w-40">
            <label className="label">Branch</label>
            <input
              type="text"
              value={branch}
              onChange={(e) => setBranch(e.target.value)}
              className="input"
              disabled={scanning}
            />
          </div>
        </div>

        <div className="mt-4">
          <p className="label">Scan Types</p>
          <div className="flex flex-wrap gap-2">
            {[
              { key: 'vulnerabilities', label: 'Vulnerabilities', icon: AlertTriangle },
              { key: 'secrets', label: 'Secrets', icon: Lock },
              { key: 'dependencies', label: 'Dependencies', icon: Package },
              { key: 'code', label: 'Code', icon: Code2 }
            ].map(({ key, label, icon: Icon }) => (
              <label
                key={key}
                className={clsx(
                  'flex items-center gap-2 px-3 py-2 rounded-lg text-sm cursor-pointer transition-colors',
                  scanTypes.includes(key)
                    ? 'bg-accent-blue/20 text-accent-blue border border-accent-blue/30'
                    : 'bg-background-tertiary text-foreground-secondary'
                )}
              >
                <input
                  type="checkbox"
                  checked={scanTypes.includes(key)}
                  onChange={(e) => {
                    if (e.target.checked) setScanTypes([...scanTypes, key]);
                    else setScanTypes(scanTypes.filter(t => t !== key));
                  }}
                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
                />
                <Icon className="w-4 h-4" />
                {label}
              </label>
            ))}
          </div>
        </div>

        <div className="mt-4 flex items-center gap-2">
          <button className="btn-primary" onClick={handleScan} disabled={scanning || !repoUrl.trim()}>
            {scanning ? (
              <>
                <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                Scanning...
              </>
            ) : (
              <>
                <Shield className="w-4 h-4" />
                Scan Repository
              </>
            )}
          </button>
          {scanning && (
            <div className="flex-1">
              <div className="progress-bar">
                <div className="progress-fill bg-accent-blue" style={{ width: `${progress}%` }} />
              </div>
              <p className="text-xs text-foreground-secondary mt-1">
                {scanStatus} - {progress}%
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Security Score */}
      {summary && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[
            { label: 'Security', score: securityScore, icon: Shield },
            { label: 'Dependencies', score: depsScore, icon: Package },
            { label: 'Secrets', score: secretsScore, icon: Lock },
            { label: 'Code Quality', score: codeScore, icon: Code2 }
          ].map(({ label, score, icon: Icon }) => (
            <div key={label} className="card">
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm text-foreground-secondary">{label}</span>
                <Icon className="w-5 h-5 text-accent-blue" />
              </div>
              <div className="flex items-baseline gap-1">
                <span className="text-3xl font-bold text-foreground">{score}</span>
                <span className="text-sm text-foreground-muted">/100</span>
              </div>
              <div className="mt-2">
                <div className="progress-bar">
                  <div
                    className="progress-fill"
                    style={{
                      width: `${score}%`,
                      backgroundColor: score >= 80 ? 'var(--color-accent-green)' : score >= 60 ? 'var(--color-severity-medium)' : 'var(--color-severity-critical)'
                    }}
                  />
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Severity Summary */}
      {findings.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
          {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(sev => (
            <button
              key={sev}
              className={clsx(
                'card p-3 text-center transition-all',
                filterSeverity.includes(sev) ? `border-l-4 border-severity-${sev}` : 'opacity-50'
              )}
              onClick={() => {
                if (filterSeverity.includes(sev)) setFilterSeverity(filterSeverity.filter(s => s !== sev));
                else setFilterSeverity([...filterSeverity, sev]);
              }}
            >
              <p className="text-2xl font-bold" style={{ color: `var(--color-severity-${sev})` }}>
                {severityCounts[sev] || 0}
              </p>
              <p className="text-xs text-foreground-secondary capitalize">{sev}</p>
            </button>
          ))}
          <div className="card p-3 text-center">
            <p className="text-2xl font-bold text-foreground">{findings.length}</p>
            <p className="text-xs text-foreground-secondary">Total</p>
          </div>
        </div>
      )}

      {/* Findings */}
      {findings.length > 0 && (
        <div className="card p-0 overflow-hidden">
          <FindingList
            findings={sortedFindings}
            expandedIds={expandedFindings}
            onToggleExpand={toggleExpand}
            onFix={handleFix}
            onIgnore={(f) => {
              setFindings(prev => prev.filter(x => x.id !== f.id));
              toast.success('Finding ignored');
            }}
            emptyMessage="No findings for selected severity"
          />
        </div>
      )}

      {/* Fix Result Modal */}
      {fixResult && selectedFinding && (
        <div className="modal-overlay" onClick={() => setFixResult(null)}>
          <div className="modal-content w-full max-w-4xl p-6" onClick={(e) => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-lg font-semibold text-foreground flex items-center gap-2">
                <Sparkles className="w-5 h-5 text-accent-purple" />
                AI Fix: {selectedFinding.title}
              </h2>
              <button className="btn-icon" onClick={() => setFixResult(null)}>
                <ChevronDown className="w-5 h-5" />
              </button>
            </div>

            {fixResult.explanation && (
              <div className="mb-4 p-3 bg-background-tertiary rounded-lg">
                <p className="text-sm text-foreground-secondary">{fixResult.explanation}</p>
              </div>
            )}

            {fixResult.patch && (
              <div className="mb-4">
                <p className="font-medium text-foreground mb-2">Patch</p>
                <CodeEditor
                  value={fixResult.patch}
                  onChange={() => {}}
                  language="json"
                  maxHeight={300}
                  readOnly
                />
              </div>
            )}

            <div className="flex gap-2">
              <button className="btn-secondary" onClick={() => setFixResult(null)}>
                Cancel
              </button>
              <button className="btn-primary" onClick={handleCreatePR}>
                <GitPullRequest className="w-4 h-4" />
                Create PR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Help Section */}
      <div className="card">
        <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2">
          <Zap className="w-5 h-5 text-accent-yellow" />
          How it works
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 text-sm text-foreground-secondary">
          <div className="p-3 bg-background-tertiary rounded-lg">
            <GitBranch className="w-5 h-5 text-accent-blue mb-2" />
            <p className="font-medium text-foreground mb-1">1. Clone</p>
            <p>Securely clone the repository</p>
          </div>
          <div className="p-3 bg-background-tertiary rounded-lg">
            <Package className="w-5 h-5 text-accent-green mb-2" />
            <p className="font-medium text-foreground mb-1">2. SBOM</p>
            <p>Generate software bill of materials with Syft</p>
          </div>
          <div className="p-3 bg-background-tertiary rounded-lg">
            <Shield className="w-5 h-5 text-accent-purple mb-2" />
            <p className="font-medium text-foreground mb-1">3. Scan</p>
            <p>Grype, Trivy, Semgrep, Gitleaks</p>
          </div>
          <div className="p-3 bg-background-tertiary rounded-lg">
            <GitPullRequest className="w-5 h-5 text-accent-yellow mb-2" />
            <p className="font-medium text-foreground mb-1">4. Fix</p>
            <p>AI generates safe patches as PRs</p>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useCallback, useRef } from 'react';
import {
  FileText,
  Upload,
  Download,
  Copy,
  RotateCcw,
  Sparkles,
  Shield,
  CheckCircle,
  Info,
  HelpCircle,
  ChevronLeft,
  ChevronRight,
  Search,
  Filter,
  Settings
} from 'lucide-react';
import { dockerfileApi } from '../services/api';
import { DockerfileAnalysis, Severity, Finding } from '@devsecops/shared/types';
import { CodeEditor } from '../components/CodeEditor';
import { DiffViewer } from '../components/DiffViewer';
import { FindingList } from '../components/FindingCard';
import { toast } from 'react-hot-toast';
import { clsx } from 'clsx';

const DEFAULT_DOCKERFILE = `# Example vulnerable Dockerfile
FROM ubuntu:latest

# Running as root (bad practice)
USER root

# Install packages without pinning versions
RUN apt-get update && apt-get install -y \\
    nginx \\
    curl \\
    python3 \\
    python3-pip

# Copy application
COPY . /app
WORKDIR /app

# Install Python dependencies without pinning
RUN pip install -r requirements.txt

# Expose port
EXPOSE 80

# No health check
CMD ["nginx", "-g", "daemon off;"]`;

const SEVERITY_ORDER: Record<Severity, number> = {
  critical: 5,
  high: 4,
  medium: 3,
  low: 2,
  info: 1
};

export function DockerfileFixer() {
  const [dockerfile, setDockerfile] = useState(DEFAULT_DOCKERFILE);
  const [analysis, setAnalysis] = useState<DockerfileAnalysis | null>(null);
  const [fixedDockerfile, setFixedDockerfile] = useState('');
  const [loading, setLoading] = useState(false);
  const [fixing, setFixing] = useState(false);
  const [viewMode, setViewMode] = useState<'editor' | 'diff' | 'side-by-side'>('editor');
  const [filterSeverity, setFilterSeverity] = useState<Severity[]>(['critical', 'high', 'medium', 'low', 'info']);
  const [filterType, setFilterType] = useState<string[]>([]);
  const [expandedFindings, setExpandedFindings] = useState<Set<string>>(new Set());
  const [showOnlyFixable, setShowOnlyFixable] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = useCallback((event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (!file.name.match(/^(Dockerfile|\.dockerfile$)/i) && !file.name.endsWith('.dockerfile')) {
      toast('File does not appear to be a Dockerfile', { icon: '⚠️' });
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      setDockerfile(e.target?.result as string);
      setAnalysis(null);
      setFixedDockerfile('');
      setViewMode('editor');
      toast.success('Dockerfile loaded');
    };
    reader.readAsText(file);
    event.target.value = '';
  }, []);

  const handleAnalyze = async () => {
    if (!dockerfile.trim()) {
      toast.error('Please provide a Dockerfile');
      return;
    }

    setLoading(true);
    try {
      const response = await dockerfileApi.analyze(dockerfile);
      if (response.data.success) {
        setAnalysis(response.data.data);
        toast.success(`Analysis complete: ${response.data.data.issues.length} issues found`);
      } else {
        toast.error(response.data.error?.message || 'Analysis failed');
      }
    } catch (err) {
      toast.error('Failed to analyze Dockerfile');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleFix = async () => {
    if (!analysis) {
      toast.error('Please analyze first');
      return;
    }

    setFixing(true);
    try {
      const response = await dockerfileApi.fix(dockerfile, analysis.issues);
      if (response.data.success) {
        setFixedDockerfile(response.data.data.fixedDockerfile);
        setAnalysis(prev => prev ? {
          ...prev,
          fixedDockerfile: response.data.data.fixedDockerfile,
          changes: response.data.data.changes,
          securityImprovements: response.data.data.securityImprovements,
          explanation: response.data.data.explanation
        } : null);
        setViewMode('side-by-side');
        toast.success('Dockerfile fixed successfully!');
      } else {
        toast.error(response.data.error?.message || 'Fix failed');
      }
    } catch (err) {
      toast.error('Failed to fix Dockerfile');
      console.error(err);
    } finally {
      setFixing(false);
    }
  };

  const handleApplyFixed = () => {
    if (fixedDockerfile) {
      setDockerfile(fixedDockerfile);
      setViewMode('editor');
      toast.success('Fixed version applied to editor');
    }
  };

  const handleReset = () => {
    setDockerfile(DEFAULT_DOCKERFILE);
    setAnalysis(null);
    setFixedDockerfile('');
    setViewMode('editor');
    toast.success('Reset to default');
  };

  const handleDownload = () => {
    const content = viewMode === 'editor' ? dockerfile : fixedDockerfile || dockerfile;
    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'Dockerfile.fixed';
    a.click();
    URL.revokeObjectURL(url);
    toast.success('Downloaded');
  };

  const handleCopy = () => {
    const content = viewMode === 'editor' ? dockerfile : fixedDockerfile || dockerfile;
    navigator.clipboard.writeText(content);
    toast.success('Copied to clipboard');
  };

  const filteredIssues = analysis?.issues.filter(issue => {
    if (!filterSeverity.includes(issue.severity)) return false;
    if (filterType.length > 0 && !filterType.includes(issue.type)) return false;
    if (showOnlyFixable && !issue.fixable) return false;
    return true;
  }) || [];

  const sortedIssues = [...filteredIssues].sort((a, b) =>
    SEVERITY_ORDER[b.severity] - SEVERITY_ORDER[a.severity]
  );

  const issueTypes = [...new Set(analysis?.issues.map(i => i.type) || [])];

  const severityCounts = analysis?.issues.reduce((acc, issue) => {
    acc[issue.severity] = (acc[issue.severity] || 0) + 1;
    return acc;
  }, {} as Record<Severity, number>) || { critical: 0, high: 0, medium: 0, low: 0, info: 0 };

  const toggleExpand = (findingId: string) => {
    setExpandedFindings(prev => {
      const next = new Set(prev);
      if (next.has(findingId)) next.delete(findingId);
      else next.add(findingId);
      return next;
    });
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground">Dockerfile AI Fixer</h1>
          <p className="text-foreground-secondary mt-1">
            Analyze, secure, and optimize your Dockerfiles with AI-powered fixes
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button className="btn-secondary" onClick={() => fileInputRef.current?.click()}>
            <Upload className="w-4 h-4" />
            Upload
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".dockerfile,Dockerfile,.txt"
            onChange={handleFileUpload}
            className="hidden"
          />
          <button className="btn-secondary" onClick={handleDownload}>
            <Download className="w-4 h-4" />
            Download
          </button>
          <button className="btn-secondary" onClick={handleCopy}>
            <Copy className="w-4 h-4" />
            Copy
          </button>
          <button className="btn-secondary" onClick={handleReset}>
            <RotateCcw className="w-4 h-4" />
            Reset
          </button>
        </div>
      </div>

      {/* Toolbar */}
      <div className="card p-4">
        <div className="flex flex-wrap items-center gap-4">
          {/* View Mode Tabs */}
          <div className="tabs">
            <button
              className={clsx('tab', viewMode === 'editor' && 'tab-active')}
              onClick={() => setViewMode('editor')}
            >
              <FileText className="w-4 h-4" />
              Editor
            </button>
            {analysis && (
              <>
                <button
                  className={clsx('tab', viewMode === 'side-by-side' && 'tab-active')}
                  onClick={() => setViewMode('side-by-side')}
                >
                  <ChevronLeft className="w-4 h-4" />
                  <ChevronRight className="w-4 h-4" />
                  Diff
                </button>
                <button
                  className={clsx('tab', viewMode === 'diff' && 'tab-active')}
                  onClick={() => setViewMode('diff')}
                >
                  <Search className="w-4 h-4" />
                  Findings
                </button>
              </>
            )}
          </div>

          <div className="flex-1" />

          {/* Filters */}
          {analysis && (
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                <Filter className="w-4 h-4 text-foreground-muted" />
                <select
                  className="input py-1.5 px-3 text-sm w-auto"
                  multiple
                  value={filterSeverity}
                  onChange={(e) => {
                    const selected = Array.from(e.target.selectedOptions).map(o => o.value as Severity);
                    setFilterSeverity(selected);
                  }}
                >
                  {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(s => (
                    <option key={s} value={s} className="capitalize">
                      {s} ({severityCounts[s] || 0})
                    </option>
                  ))}
                </select>
              </div>

              {issueTypes.length > 0 && (
                <div className="flex items-center gap-2">
                  <Settings className="w-4 h-4 text-foreground-muted" />
                  <select
                    className="input py-1.5 px-3 text-sm w-auto"
                    multiple
                    value={filterType}
                    onChange={(e) => {
                      const selected = Array.from(e.target.selectedOptions).map(o => o.value);
                      setFilterType(selected);
                    }}
                  >
                    {issueTypes.map(t => (
                      <option key={t} value={t} className="capitalize">
                        {t.replace('_', ' ')}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              <label className="flex items-center gap-2 text-sm text-foreground-secondary">
                <input
                  type="checkbox"
                  checked={showOnlyFixable}
                  onChange={(e) => setShowOnlyFixable(e.target.checked)}
                  className="rounded border-border bg-background-tertiary text-accent-blue focus:ring-accent-blue"
                />
                Fixable only
              </label>
            </div>
          )}

          {/* Action Buttons */}
          <div className="flex items-center gap-2">
            <button
              className="btn-primary"
              onClick={handleAnalyze}
              disabled={loading || !dockerfile.trim()}
            >
              {loading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                  Analyzing...
                </>
              ) : (
                <>
                  <Shield className="w-4 h-4" />
                  Analyze
                </>
              )}
            </button>

            {analysis && !fixedDockerfile && (
              <button
                className="btn-primary"
                onClick={handleFix}
                disabled={fixing}
              >
                {fixing ? (
                  <>
                    <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    Fixing...
                  </>
                ) : (
                  <>
                    <Sparkles className="w-4 h-4" />
                    AI Fix
                  </>
                )}
              </button>
            )}

            {fixedDockerfile && viewMode !== 'editor' && (
              <button className="btn-secondary" onClick={handleApplyFixed}>
                <CheckCircle className="w-4 h-4" />
                Apply Fix
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Main Content */}
      {viewMode === 'editor' && (
        <div className="card p-0 overflow-hidden">
          <CodeEditor
            value={dockerfile}
            onChange={(value: string | undefined) => setDockerfile(value || '')}
            language="dockerfile"
            fileName="Dockerfile"
            maxHeight={500}
            placeholder="Paste or write your Dockerfile here..."
          />
        </div>
      )}

      {viewMode === 'side-by-side' && fixedDockerfile && analysis && (
        <div className="card p-0 overflow-hidden">
          {analysis.explanation && (
            <div className="p-4 bg-background-tertiary/50 border-b border-border">
              <div className="flex items-start gap-3">
                <Info className="w-5 h-5 text-accent-blue flex-shrink-0 mt-0.5" />
                <div className="prose prose-sm text-foreground-secondary max-w-none">
                  {analysis.explanation.split('\n').map((para, i) => (
                    <p key={i} className="mb-2">{para}</p>
                  ))}
                </div>
              </div>
              {analysis.securityImprovements && analysis.securityImprovements.length > 0 && (
                <div className="mt-3">
                  <p className="text-sm font-medium text-foreground mb-2">Security Improvements:</p>
                  <ul className="list-disc list-inside text-sm text-foreground-secondary space-y-1">
                    {analysis.securityImprovements.map((imp, i) => (
                      <li key={i} className="flex items-center gap-2">
                        <CheckCircle className="w-4 h-4 text-accent-green flex-shrink-0" />
                        {imp}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          )}
          <DiffViewer
            original={dockerfile}
            fixed={fixedDockerfile}
            changes={analysis.changes || []}
            onApplyFixed={handleApplyFixed}
            onReset={handleReset}
          />
        </div>
      )}

      {viewMode === 'diff' && analysis && (
        <div className="card p-0 overflow-hidden">
          <FindingList
            findings={sortedIssues.map(f => ({
              id: f.id as Finding['id'],
              scanId: 'dockerfile' as Finding['scanId'],
              type: f.type as Finding['type'],
              severity: f.severity,
              title: f.message,
              description: f.suggestion || f.message,
              file: 'Dockerfile',
              line: f.line,
              ruleId: f.rule,
              fixable: f.fixable,
              remediation: f.fixable ? {
                available: true,
                type: 'patch' as const,
                description: f.suggestion || 'AI will generate a fix',
                steps: ['Run AI Fix to generate corrected Dockerfile'],
                confidence: 85,
                fixedContent: fixedDockerfile || undefined
              } : undefined,
              status: 'open' as const,
              createdAt: new Date().toISOString() as Finding['createdAt']
            }))}
            expandedIds={expandedFindings}
            onToggleExpand={(finding: any) => toggleExpand(finding.id)}
            showActions={false}
            emptyMessage="No issues found matching current filters"
          />
        </div>
      )}

      {/* Summary Stats */}
      {analysis && (
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          {(['critical', 'high', 'medium', 'low', 'info'] as Severity[]).map(sev => (
            <div
              key={sev}
              className={clsx('card p-4 text-center', `border-l-4 border-severity-${sev}`)}
            >
              <p className="text-3xl font-bold" style={{ color: `var(--color-severity-${sev})` }}>
                {severityCounts[sev] || 0}
              </p>
              <p className="text-sm text-foreground-secondary capitalize">{sev}</p>
            </div>
          ))}
        </div>
      )}

      {/* Help Section */}
      <div className="card">
        <h3 className="font-semibold text-foreground mb-4 flex items-center gap-2">
          <HelpCircle className="w-5 h-5 text-accent-blue" />
          What gets checked
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 text-sm text-foreground-secondary">
          {[
            'Syntax errors & invalid instructions',
            'Running as root user',
            'Large/unoptimized base images',
            'Missing health checks',
            'Missing dependency pinning',
            'Secrets in Dockerfile',
            'Package manager issues',
            'Cache inefficiencies',
            'Missing security labels',
            'Insecure permissions',
            'Outdated package versions',
            'Unnecessary packages'
          ].map((item, i) => (
            <div key={i} className="flex items-center gap-2">
              <CheckCircle className="w-4 h-4 text-accent-green flex-shrink-0" />
              {item}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

