        const a = document.createElement('a');
        a.href = url;
        a.download = `devsecops-export-${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        URL.revokeObjectURL(url);
        toast.success('Data exported');
      }
    } catch (err) {
      toast.error('Export failed');
      console.error(err);
    }
  };

