/**
 * Google Apps Script - Gemini AI Bridge for DevSecOps AI Platform
 *
 * INSTRUCTIONS:
 * 1. Go to https://script.google.com/
 * 2. Click "New Project"
 * 3. Replace all code with this file's content
 * 4. Replace YOUR_GEMINI_API_KEY_HERE with your actual Gemini API key
 * 5. Click "Deploy" → "New deployment" → "Web app"
 * 6. Set "Execute as: Me" and "Who has access: Anyone"
 * 7. Copy the Web App URL and add to your .env as AI_APPS_SCRIPT_URL
 *
 * GET YOUR GEMINI API KEY: https://makersuite.google.com/app/apikey
 */

// ============================================
// CONFIGURATION - REPLACE WITH YOUR API KEY
// ============================================
const GEMINI_API_KEY = 'YOUR_GEMINI_API_KEY_HERE';
const GEMINI_MODEL = 'gemini-1.5-pro'; // or 'gemini-1.5-flash'
const GEMINI_API_URL = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;

// ============================================
// MAIN ENTRY POINT - doPost handles all requests
// ============================================
function doPost(e) {
  try {
    // Parse request body
    let requestData = {};
    if (e.postData && e.postData.contents) {
      requestData = JSON.parse(e.postData.contents);
    }

    const { prompt, temperature, maxTokens, model, systemPrompt, context } = requestData;

    // Validate required fields
    if (!prompt) {
      return createResponse({ error: 'Missing required field: prompt' }, 400);
    }

    // Build the full prompt with system prompt and context
    let fullPrompt = prompt;
    if (systemPrompt) {
      fullPrompt = systemPrompt + '\n\n' + fullPrompt;
    }
    if (context && context.additional) {
      fullPrompt += '\n\nAdditional Context:\n' + context.additional;
    }

    // Call Gemini API
    const geminiResponse = callGeminiAPI(fullPrompt, temperature, maxTokens);

    // Return in format expected by the frontend
    return createResponse({
      response: geminiResponse,
      model: model || GEMINI_MODEL,
      usage: {
        promptTokens: estimateTokens(fullPrompt),
        completionTokens: estimateTokens(geminiResponse),
        totalTokens: estimateTokens(fullPrompt) + estimateTokens(geminiResponse)
      }
    });

  } catch (error) {
    console.error('Apps Script Error:', error);
    return createResponse({ error: error.toString() }, 500);
  }
}

// ============================================
// GEMINI API CALL
// ============================================
function callGeminiAPI(prompt, temperature, maxTokens) {
  const payload = {
    contents: [{
      parts: [{ text: prompt }]
    }],
    generationConfig: {
      temperature: temperature ?? 0.2,
      maxOutputTokens: maxTokens ?? 8192,
      topP: 0.8,
      topK: 40
    },
    safetySettings: [
      { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' }
    ]
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  const url = `${GEMINI_API_URL}?key=${GEMINI_API_KEY}`;
  const response = UrlFetchApp.fetch(url, options);
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();

  if (responseCode !== 200) {
    throw new Error(`Gemini API error (${responseCode}): ${responseText}`);
  }

  const data = JSON.parse(responseText);

  // Extract text from Gemini response
  if (data.candidates && data.candidates.length > 0) {
    const candidate = data.candidates[0];
    if (candidate.content && candidate.content.parts && candidate.content.parts.length > 0) {
      return candidate.content.parts[0].text || '';
    }
  }

  // Fallback
  return 'No response generated';
}

// ============================================
// HEALTH CHECK - GET endpoint for monitoring
// ============================================
function doGet(e) {
  return createResponse({
    status: 'ok',
    service: 'DevSecOps AI Bridge',
    model: GEMINI_MODEL,
    timestamp: new Date().toISOString()
  });
}

// ============================================
// HELPER FUNCTIONS
// ============================================
function createResponse(data, statusCode = 200) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function estimateTokens(text) {
  // Rough estimation: ~4 chars per token
  return Math.ceil((text || '').length / 4);
}

/**
 * OPTIONAL: Test function - run this in Apps Script editor to verify setup
 * Open Apps Script editor, select testConnection from dropdown, click Run
 */
function testConnection() {
  const result = callGeminiAPI('Say "OK" if you can hear me.', 0.1, 10);
  console.log('Test result:', result);
  return result;
}

