1	import { Queue, Worker, Job, QueueEvents } from 'bullmq';
2	import { config } from '../config';
3	import { prisma } from '../database';
4	import { aiService } from '../ai';
5	import { logger } from '../utils/logger';
6	import { JobType, JobStatus } from '@devsecops/shared/types';
7	
8	// Import scanner modules
9	import { scanDockerfile, fixDockerfile, scanDockerImage, fixDockerImage } from '../../modules/dockerfile/scanners';
10	import { scanKubernetes, fixKubernetes, generateKubernetes } from '../../modules/kubernetes/scanners';
11	import { scanJenkinsfile, fixJenkinsfile, generateJenkinsfile } from '../../modules/jenkins/scanners';
12	import { scanGitHubRepo, fixGitHubCode } from '../../modules/github/scanners';
13	import { scanDependencies, remediateDependency, generateSBOM } from '../../modules/dependencies/scanners';
14	import { investigateLogs, searchLogs, parseLogFile } from '../../modules/logs/scanners';
15	
16	interface JobData {
17	  type: JobType;
18	  input: Record<string, unknown>;
19	  userId: string;
20	  scanId?: string;
21	}
22	
23	const queue = new Queue<JobData>('devsecops-jobs', {
24	  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
25	  defaultJobOptions: {
26	    removeOnComplete: 100,
27	    removeOnFail: 50,
28	    attempts: 3,
29	    backoff: { type: 'exponential', delay: 5000 }
30	  }
31	});
32	
33	const queueEvents = new QueueEvents('devsecops-jobs', {
34	  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') }
35	});
36	
37	queueEvents.on('completed', async ({ jobId, returnvalue }) => {
38	  await updateJobStatus(jobId, 'completed', 100, 'Completed', returnvalue as any);
39	});
40	
41	queueEvents.on('failed', async ({ jobId, failedReason }) => {
42	  await updateJobStatus(jobId, 'failed', 0, 'Failed', undefined, failedReason);
43	});
44	
45	queueEvents.on('progress', async ({ jobId, data }) => {
46	  if (data && typeof data === 'object' && 'progress' in data) {
47	    const progressData = data as { progress: number; currentStep?: string };
48	    await updateJobProgress(jobId, progressData.progress, progressData.currentStep || '');
49	  }
50	});
51	
52	export async function initializeQueue(): Promise<void> {
53	  // Create workers for each job type
54	  const worker = new Worker<JobData>(
55	    'devsecops-jobs',
56	    async (job) => await processJob(job),
57	    {
58	      connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
59	      concurrency: config.QUEUE_CONCURRENCY
60	    }
61	  );
62	
63	  worker.on('error', (err) => logger.error({ err }, 'Queue worker error'));
64	  logger.info('Job queue workers started');
65	}
66	
67	export async function shutdownQueue(): Promise<void> {
68	  await queue.close();
69	  await queueEvents.close();
70	}
71	
72	export async function createJob(data: JobData, priority: 'low' | 'normal' | 'high' = 'normal'): Promise<string> {
73	  const job = await queue.add(data.type, data, {
74	    priority: priority === 'high' ? 10 : priority === 'low' ? 1 : 5
75	  });
76	  return job.id!;
77	}
78	
79	export async function getJobStatus(jobId: string): Promise<any> {
80	  const job = await queue.getJob(jobId);
81	  if (!job) return null;
82	
83	  const state = await job.getState();
84	  const progress = job.progress;
85	
86	  return {
87	    id: job.id,
88	    type: job.name,
89	    status: state,
90	    progress: typeof progress === 'number' ? progress : 0,
91	    data: job.data,
92	    returnvalue: job.returnvalue,
93	    failedReason: job.failedReason,
94	    createdAt: new Date(job.timestamp).toISOString(),
95	    processedAt: job.processedOn ? new Date(job.processedOn).toISOString() : null,
96	    finishedAt: job.finishedOn ? new Date(job.finishedOn).toISOString() : null
97	  };
98	}
99	
100	export async function cancelJob(jobId: string): Promise<boolean> {
101	  const job = await queue.getJob(jobId);
102	  if (job) {
103	    await job.remove();
104	    await updateJobStatus(jobId, 'cancelled', 0, 'Cancelled');
105	    return true;
106	  }
107	  return false;
108	}
109	
110	async function updateJobStatus(
111	  jobId: string,
112	  status: JobStatus,
113	  progress: number,
114	  currentStep: string,
115	  output?: any,
116	  error?: string
117	): Promise<void> {
118	  await prisma.job.updateMany({
119	    where: { id: jobId },
120	    data: {
121	      status,
122	      progress,
123	      currentStep,
124	      output,
125	      error,
126	      completedAt: ['completed', 'failed', 'cancelled'].includes(status) ? new Date() : null
127	    }
128	  });
129	}
130	
131	async function updateJobProgress(jobId: string, progress: number, currentStep: string): Promise<void> {
132	  await prisma.job.updateMany({
133	    where: { id: jobId },
134	    data: { progress, currentStep }
135	  });
136	}
137	
138	async function processJob(job: Job<JobData>): Promise<any> {
139	  const { type, input, userId, scanId: scanIdFromJob } = job.data;
140	  const scanId = scanIdFromJob || '';
141	
142	  await prisma.job.update({
143	    where: { id: job.id },
144	    data: { status: 'running', startedAt: new Date() }
145	  });
146	
147	  try {
148	    let result: any;
149	    const i = input as Record<string, unknown>;
150	
151	    const content = String(i.content ?? '');
152	    const imageName = String(i.imageName ?? '');
153	    const dockerfile = String(i.dockerfile ?? '');
154	    const repoUrl = String(i.repoUrl ?? '');
155	    const branch = String(i.branch ?? 'main');
156	    const token = String(i.token ?? '');
157	    const fileContent = String(i.fileContent ?? '');
158	    const surroundingContext = String(i.surroundingContext ?? '');
159	    const question = String(i.question ?? '');
160	    const query = String(i.query ?? '');
161	    const filePath = String(i.filePath ?? '');
162	    const scanIdParam = String(i.scanId ?? '');
163	    const packageName = String(i.packageName ?? '');
164	    const currentVersion = String(i.currentVersion ?? '');
165	    const format = String(i.format ?? 'cyclonedx') as 'cyclonedx' | 'spdx';
166	
167	    switch (type) {
168	      case 'dockerfile_scan':
169	        result = await scanDockerfile(content, job, scanId);
170	        break;
171	      case 'dockerfile_fix':
172	        result = await fixDockerfile(content, (i.findings as any[]) || [], job);
173	        break;
174	      case 'docker_image_scan':
175	        result = await scanDockerImage(imageName, job, scanId);
176	        break;
177	      case 'docker_image_fix':
178	        result = await fixDockerImage(dockerfile, (i.vulnerabilities as any[]) || [], job);
179	        break;
180	      case 'kubernetes_scan':
181	        result = await scanKubernetes(content, job, scanId);
182	        break;
183	      case 'kubernetes_fix':
184	        result = await fixKubernetes(content, (i.findings as any[]) || [], job);
185	        break;
186	      case 'kubernetes_generate':
187	        result = await generateKubernetes(i.spec as any, job);
188	        break;
189	      case 'jenkinsfile_scan':
190	        result = await scanJenkinsfile(content, job, scanId);
191	        break;
192	      case 'jenkinsfile_fix':
193	        result = await fixJenkinsfile(content, (i.findings as any[]) || [], job);
194	        break;
195	      case 'jenkinsfile_generate':
196	        result = await generateJenkinsfile(i.spec as any, job);
197	        break;
198	      case 'github_repo_scan':
199	        result = await scanGitHubRepo(repoUrl, branch, token, job, scanId);
200	        break;
201	      case 'github_code_fix':
202	        result = await fixGitHubCode(i.finding as any, fileContent, surroundingContext, job);
203	        break;
204	      case 'log_investigation':
205	        result = await investigateLogs(question, (i.logEntries as any[]) || [], i.context, job);
206	        break;
207	      case 'log_search':
208	        result = await searchLogs(query, (i.logFiles as string[]) || [], i.options as { caseSensitive?: boolean; regex?: boolean; before?: number; after?: number } || {}, job);
209	        break;
210	      case 'log_parse':
211	        result = await parseLogFile(filePath, job);
212	        break;
213	      case 'dependency_scan':
214	        result = await scanDependencies(i as any, job, scanId);
215	        break;
216	      case 'dependency_fix':
217	        result = await remediateDependency(scanIdParam, packageName, currentVersion, job);
218	        break;
219	      case 'sbom_generation':
220	        result = await generateSBOM(scanIdParam, format, job);
221	        break;
222	      default:
223	        throw new Error(`Unknown job type: ${type}`);
224	    }
225	
226	    // Create scan record if applicable
227	    if (scanId) {
228	      await prisma.scan.update({
229	        where: { id: scanId },
230	        data: {
231	          status: 'completed',
232	          summary: result.summary,
233	          completedAt: new Date()
234	        }
235	      });
236	    }
237	
238	    return result;
239	  } catch (error) {
240	    logger.error({ err: error, jobId: job.id, type }, 'Job processing failed');
241	
242	    if (scanId) {
243	      await prisma.scan.update({
244	        where: { id: scanId },
245	        data: { status: 'failed', completedAt: new Date() }
246	      });
247	    }
248	
249	    throw error;
250	  }
251	}

