1	import axios from 'axios';
2	
3	export const api = axios.create({
4	  baseURL: '/api',
5	  headers: {
6	    'Content-Type': 'application/json'
7	  },
8	  withCredentials: true
9	});
10	
11	api.interceptors.response.use(
12	  (response) => response,
13	  async (error) => {
14	    const originalRequest = error.config;
15	
16	    if (error.response?.status === 401 && !originalRequest._retry) {
17	      originalRequest._retry = true;
18	
19	      try {
20	        const refreshToken = localStorage.getItem('auth_tokens');
21	        if (refreshToken) {
22	          const { refreshToken: token } = JSON.parse(refreshToken);
23	          const response = await axios.post('/api/auth/refresh', { refreshToken: token });
24	          const { accessToken, refreshToken: newRefreshToken } = response.data.data;
25	
26	          const newTokens = { accessToken, refreshToken: newRefreshToken };
27	          localStorage.setItem('auth_tokens', JSON.stringify(newTokens));
28	          api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;
29	
30	          return api(originalRequest);
31	        }
32	      } catch {
33	        localStorage.removeItem('auth_tokens');
34	        delete api.defaults.headers.common['Authorization'];
35	        window.location.href = '/login';
36	      }
37	    }
38	
39	    return Promise.reject(error);
40	  }
41	);
42	
43	// Auth
44	export const authApi = {
45	  login: (credentials: { email: string; password: string; rememberMe?: boolean }) =>
46	    api.post('/auth/login', credentials),
47	  register: (data: { email: string; password: string; name: string }) =>
48	    api.post('/auth/register', data),
49	  logout: () => api.post('/auth/logout'),
50	  me: () => api.get('/auth/me'),
51	  refresh: (refreshToken: string) => api.post('/auth/refresh', { refreshToken }),
52	  updateMe: (data: Partial<{ name: string; avatarUrl: string; theme: string; sidebarCollapsed: boolean; language: string }>) =>
53	    api.patch('/auth/me', data),
54	  changePassword: (data: { currentPassword: string; newPassword: string }) =>
55	    api.post('/auth/change-password', data)
56	};
57	
58	// Dockerfile
59	export const dockerfileApi = {
60	  analyze: (content: string) => api.post('/dockerfile/analyze', { content }),
61	  fix: (content: string, issues?: any[], options?: any) => api.post('/dockerfile/fix', { content, issues, options }),
62	  validate: (content: string) => api.post('/dockerfile/validate', { content })
63	};
64	
65	// Docker Image
66	export const dockerApi = {
67	  scan: (image: string) => api.post('/docker/scan', { image }),
68	  fix: (image: string, vulnerabilities: any[], dockerfile?: string, options?: any) =>
69	    api.post('/docker/fix', { image, vulnerabilities, dockerfile, options }),
70	  build: (dockerfile: string, tag: string, options?: any) => api.post('/docker/build', { dockerfile, tag, options }),
71	  push: (image: string, registry?: string) => api.post('/docker/push', { image, registry }),
72	  pull: (image: string) => api.post('/docker/pull', { image }),
73	  listImages: () => api.get('/docker/images'),
74	  removeImage: (image: string) => api.delete('/docker/images', { data: { image } })
75	};
76	
77	// Kubernetes
78	export const kubernetesApi = {
79	  analyze: (content: string) => api.post('/kubernetes/analyze', { content }),
80	  fix: (content: string, issues?: any[], options?: any) => api.post('/kubernetes/fix', { content, issues, options }),
81	  generate: (resourceType: string, config: any) => api.post('/kubernetes/generate', { resourceType, config }),
82	  validate: (content: string) => api.post('/kubernetes/validate', { content }),
83	  apply: (content: string, cluster?: string) => api.post('/kubernetes/apply', { content, cluster })
84	};
85	
86	// Jenkins
87	export const jenkinsApi = {
88	  analyze: (content: string) => api.post('/jenkins/analyze', { content }),
89	  fix: (content: string, issues?: any[], options?: any) => api.post('/jenkins/fix', { content, issues, options }),
90	  generate: (config: any) => api.post('/jenkins/generate', { config }),
91	  validate: (content: string) => api.post('/jenkins/validate', { content }),
92	  servers: {
93	    list: () => api.get('/jenkins/servers'),
94	    add: (data: { name: string; url: string; credentials: any }) => api.post('/jenkins/servers', data),
95	    test: (id: string) => api.post(`/jenkins/servers/${id}/test`),
96	    remove: (id: string) => api.delete(`/jenkins/servers/${id}`),
97	    jobs: (id: string) => api.get(`/jenkins/servers/${id}/jobs`),
98	    trigger: (id: string, jobName: string, params?: any) => api.post(`/jenkins/servers/${id}/jobs/${jobName}/trigger`, params),
99	    buildLog: (id: string, jobName: string, buildNumber: number) => api.get(`/jenkins/servers/${id}/jobs/${jobName}/builds/${buildNumber}/log`)
100	  }
101	};
102	
103	// GitHub
104	export const githubApi = {
105	  connect: (token: string) => api.post('/github/connect', { token }),
106	  disconnect: () => api.delete('/github/connect'),
107	  repositories: () => api.get('/github/repositories'),
108	  scan: (repoUrl: string, branch: string, scanTypes?: string[]) => api.post('/github/scan', { repoUrl, branch, scanTypes }),
109	  scanStatus: (scanId: string) => api.get(`/github/scans/${scanId}`),
110	  scanResults: (scanId: string) => api.get(`/github/scans/${scanId}/results`),
111	  fix: (findingId: string, repoId: string, branch: string, fixType: string) =>
112	    api.post('/github/fix', { findingId, repoId, branch, fixType }),
113	  createPR: (data: { repoId: string; branch: string; title: string; body: string; changes: any[] }) =>
114	    api.post('/github/pr', data)
115	};
116	
117	// Logs
118	export const logsApi = {
119	  upload: (file: File, onProgress?: (progress: number) => void) => {
120	    const formData = new FormData();
121	    formData.append('file', file);
122	    return api.post('/logs/upload', formData, {
123	      headers: { 'Content-Type': 'multipart/form-data' },
124	      onUploadProgress: (e) => onProgress?.(Math.round((e.loaded * 100) / (e.total || 1)))
125	    });
126	  },
127	  list: () => api.get('/logs'),
128	  delete: (id: string) => api.delete(`/logs/${id}`),
129	  search: (query: string, logFileIds: string[], timeRange?: any, level?: string[], service?: string[]) =>
130	    api.post('/logs/search', { query, logFileIds, timeRange, level, service }),
131	  investigate: (question: string, logFileIds: string[], timeRange?: any) =>
132	    api.post('/logs/investigate', { question, logFileIds, timeRange }),
133	  getEntries: (id: string, params?: { limit?: number; offset?: number; level?: string }) =>
134	    api.get(`/logs/${id}/entries`, { params })
135	};
136	
137	// Dependencies
