import axios from 'axios';

export const api = axios.create({
  baseURL: '/api',
  headers: {
    'Content-Type': 'application/json'
  },
  withCredentials: true
});

api.interceptors.response.use(
  (response) => response,
  async (error) => {
    const originalRequest = error.config;

    if (error.response?.status === 401 && !originalRequest._retry) {
      originalRequest._retry = true;

      try {
        const refreshToken = localStorage.getItem('auth_tokens');
        if (refreshToken) {
          const { refreshToken: token } = JSON.parse(refreshToken);
          const response = await axios.post('/api/auth/refresh', { refreshToken: token });
          const { accessToken, refreshToken: newRefreshToken } = response.data.data;

          const newTokens = { accessToken, refreshToken: newRefreshToken };
          localStorage.setItem('auth_tokens', JSON.stringify(newTokens));
          api.defaults.headers.common['Authorization'] = `Bearer ${accessToken}`;

          return api(originalRequest);
        }
      } catch {
        localStorage.removeItem('auth_tokens');
        delete api.defaults.headers.common['Authorization'];
        window.location.href = '/login';
      }
    }

    return Promise.reject(error);
  }
);

// Auth
export const authApi = {
  login: (credentials: { email: string; password: string; rememberMe?: boolean }) =>
    api.post('/auth/login', credentials),
  register: (data: { email: string; password: string; name: string }) =>
    api.post('/auth/register', data),
  logout: () => api.post('/auth/logout'),
  me: () => api.get('/auth/me'),

