1	import { FastifyInstance } from 'fastify';
2	import { prisma } from '../../shared/database';
3	import { auditLog } from '../../shared/utils/audit';
4	
5	const listSchema = {
6	  type: 'object',
7	  properties: {
8	    page: { type: 'number', default: 1 },
9	    pageSize: { type: 'number', default: 20 },
10	    status: { type: 'array', items: { type: 'string', enum: ['queued', 'running', 'analyzing', 'fixing', 'completed', 'failed', 'cancelled'] } },
11	    type: { type: 'array', items: { type: 'string' } }
12	  }
