15	export async function jobsRoutes(app: FastifyInstance) {
16	  // List jobs
17	  app.get('/', {
18	    preHandler: [app.authenticate],
19	    schema: { querystring: listSchema }
20	  }, async (request, reply) => {
21	    const userId = (request as any).user.userId;
22	    const { page, pageSize, status, type } = request.query as any;
23	
24	    const where: any = { userId };
25	    if (status?.length) where.status = { in: status };
26	    if (type?.length) where.type = { in: type };
27	
28	    const [jobs, total] = await Promise.all([
29	      prisma.job.findMany({
30	        where,
31	        orderBy: { createdAt: 'desc' },
32	        take: pageSize,
33	        skip: (page - 1) * pageSize
34	      }),
35	      prisma.job.count({ where })
36	    ]);
37	
38	    return {
39	      success: true,
40	      data: {
41	        jobs,
42	        total,
43	        totalPages: Math.ceil(total / pageSize),
44	        page,
45	        pageSize
46	      }
47	    };
48	  });
49	
50	  // Get job details
51	  app.get('/:id', {
52	    preHandler: [app.authenticate]
53	  }, async (request, reply) => {
54	    const userId = (request as any).user.userId;
55	    const { id } = request.params as { id: string };
56	
57	    const job = await prisma.job.findUnique({
58	      where: { id }
59	    });
60	
61	    if (!job || job.userId !== userId) {
62	      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Job not found', statusCode: 404 } });
63	    }
64	
65	    return { success: true, data: job };
66	  });
67	
68	  // Cancel job
69	  app.post('/:id/cancel', {
70	    preHandler: [app.authenticate]
71	  }, async (request, reply) => {
72	    const userId = (request as any).user.userId;
73	    const { id } = request.params as { id: string };
74	
75	    const job = await prisma.job.findUnique({ where: { id } });
76	    if (!job || job.userId !== userId) {
77	      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Job not found', statusCode: 404 } });
78	    }
79	
80	    if (job.status === 'completed' || job.status === 'failed' || job.status === 'cancelled') {
81	      return reply.code(400).send({ success: false, error: { code: 'INVALID_STATE', message: 'Cannot cancel completed job', statusCode: 400 } });
82	    }
83	
84	    // In production, would cancel the BullMQ job
85	    await prisma.job.update({
86	      where: { id },
87	      data: { status: 'cancelled', completedAt: new Date(), error: 'Cancelled by user' }
88	    });
89	
90	    await auditLog(request, 'JOB_CANCELLED', 'job', id);
91	
92	    return { success: true, message: 'Job cancelled' };
93	  });
94	
95	  // Retry failed job
96	  app.post('/:id/retry', {
97	    preHandler: [app.authenticate]
98	  }, async (request, reply) => {
99	    const userId = (request as any).user.userId;
100	    const { id } = request.params as { id: string };
101	
102	    const job = await prisma.job.findUnique({ where: { id } });
103	    if (!job || job.userId !== userId) {
104	      return reply.code(404).send({ success: false, error: { code: 'NOT_FOUND', message: 'Job not found', statusCode: 404 } });
105	    }
106	
107	    if (job.status !== 'failed') {
108	      return reply.code(400).send({ success: false, error: { code: 'INVALID_STATE', message: 'Can only retry failed jobs', statusCode: 400 } });
109	    }
110	
111	    // Reset job status to queued
112	    await prisma.job.update({
113	      where: { id },
114	      data: { status: 'queued', progress: 0, error: null, startedAt: null, completedAt: null }
115	    });
116	
117	    // In production, would re-queue the job
118	    await auditLog(request, 'JOB_RETRIED', 'job', id);
119	
120	    return { success: true, message: 'Job queued for retry' };
121	  });
122	
123	  // Get job stats
124	  app.get('/stats', {
125	    preHandler: [app.authenticate]
126	  }, async (request, reply) => {
127	    const userId = (request as any).user.userId;
128	
129	    const [total, byStatus, byType, running] = await Promise.all([
130	      prisma.job.count({ where: { userId } }),
131	      prisma.job.groupBy({ by: ['status'], where: { userId }, _count: true }),
132	      prisma.job.groupBy({ by: ['type'], where: { userId }, _count: true }),
133	      prisma.job.count({ where: { userId, status: { in: ['queued', 'running', 'analyzing', 'fixing'] } } })
134	    ]);
135	
136	    return {
137	      success: true,
138	      data: {
139	        total,
140	        running,
141	        byStatus: byStatus.map(s => ({ status: s.status, count: s._count })),
142	        byType: byType.map(t => ({ type: t.type, count: t._count }))
143	      }
144	    };
145	  });
146	}

