async function analyzeDockerfileSync(content: string): Promise<any> {
  // Run the sync scan using the scanner directly (no queue)
  const mockJob = {
    id: 'sync-scan',
    updateProgress: async () => {},
    data: { type: 'dockerfile_scan', input: { content }, userId: '', scanId: '' }
