/**
 * Google Apps Script - Gemini AI Bridge for DevSecOps AI Platform
 *
 * INSTRUCTIONS:
 * 1. Go to https://script.google.com/
 * 2. Click "New Project"
 * 3. Replace all code with this file's content
 * 4. Replace YOUR_GEMINI_API_KEY_HERE with your actual Gemini API key
 * 5. Click "Deploy" → "New deployment" → "Web app"
 * 6. Set "Execute as: Me" and "Who has access: Anyone"
 * 7. Copy the Web App URL and add to your .env as AI_APPS_SCRIPT_URL
 *
 * GET YOUR GEMINI API KEY: https://makersuite.google.com/app/apikey
 */

// ============================================
// CONFIGURATION - REPLACE WITH YOUR API KEY
// ============================================
const GEMINI_API_KEY = 'YOUR_GEMINI_API_KEY_HERE';
const GEMINI_MODEL = 'gemini-1.5-flash'; // Use flash model for higher free tier quota (1500 RPM vs 20 for pro)
const GEMINI_API_URL = `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent`;

// ============================================
// MAIN ENTRY POINT - doPost handles all requests
// ============================================
function doPost(e) {
  try {
    // Parse request body
    let requestData = {};
    if (e.postData && e.postData.contents) {
      requestData = JSON.parse(e.postData.contents);
    }

    const { prompt, temperature, maxTokens, model, systemPrompt, context } = requestData;

    // Validate required fields
    if (!prompt) {
      return createResponse({ error: 'Missing required field: prompt' }, 400);
    }

    // Build the full prompt with system prompt and context
    let fullPrompt = prompt;
    if (systemPrompt) {
      fullPrompt = systemPrompt + '\n\n' + fullPrompt;
    }
    if (context && context.additional) {
      fullPrompt += '\n\nAdditional Context:\n' + context.additional;
    }

    // Call Gemini API
    const geminiResponse = callGeminiAPI(fullPrompt, temperature, maxTokens);

    // Return in format expected by the frontend
    return createResponse({
      response: geminiResponse,
      model: model || GEMINI_MODEL,
      usage: {
        promptTokens: estimateTokens(fullPrompt),
        completionTokens: estimateTokens(geminiResponse),
        totalTokens: estimateTokens(fullPrompt) + estimateTokens(geminiResponse)
      }
    });

  } catch (error) {
    console.error('Apps Script Error:', error);
    return createResponse({ error: error.toString() }, 500);
  }
}

// ============================================
// GEMINI API CALL
// ============================================
function callGeminiAPI(prompt, temperature, maxTokens) {
  const payload = {
    contents: [{
      parts: [{ text: prompt }]
    }],
    generationConfig: {
      temperature: temperature ?? 0.2,
      maxOutputTokens: maxTokens ?? 8192,
      topP: 0.8,
      topK: 40
    },
    safetySettings: [
      { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' },
      { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_MEDIUM_AND_ABOVE' }
    ]
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  const url = `${GEMINI_API_URL}?key=${GEMINI_API_KEY}`;
  const response = UrlFetchApp.fetch(url, options);
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();

  if (responseCode !== 200) {
    throw new Error(`Gemini API error (${responseCode}): ${responseText}`);
  }

  const data = JSON.parse(responseText);

  // Extract text from Gemini response
  if (data.candidates && data.candidates.length > 0) {
    const candidate = data.candidates[0];
    if (candidate.content && candidate.content.parts && candidate.content.parts.length > 0) {
      return candidate.content.parts[0].text || '';
    }
  }

  // Fallback
  return 'No response generated';
}

// ============================================
// HEALTH CHECK - GET endpoint for monitoring
// ============================================
function doGet(e) {
  return createResponse({
    status: 'ok',
    service: 'DevSecOps AI Bridge',
    model: GEMINI_MODEL,
    timestamp: new Date().toISOString()
  });
}

// ============================================
// HELPER FUNCTIONS
// ============================================
function createResponse(data, statusCode = 200) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function estimateTokens(text) {
  // Rough estimation: ~4 chars per token
  return Math.ceil((text || '').length / 4);
}

/**
 * OPTIONAL: Test function - run this in Apps Script editor to verify setup
 * Open Apps Script editor, select testConnection from dropdown, click Run
 */
function testConnection() {
  const result = callGeminiAPI('Say "OK" if you can hear me.', 0.1, 10);
  console.log('Test result:', result);
  return result;
}

import { Queue, Worker, Job, QueueEvents } from 'bullmq';
import { config } from '../config';
import { prisma } from '../database';
import { aiService } from '../ai';
import { logger } from '../utils/logger';
import { JobType, JobStatus } from '@devsecops/shared/types';

// Import scanner modules
import { scanDockerfile, fixDockerfile, scanDockerImage, fixDockerImage } from '../../modules/dockerfile/scanners';
import { scanKubernetes, fixKubernetes, generateKubernetes } from '../../modules/kubernetes/scanners';
import { scanJenkinsfile, fixJenkinsfile, generateJenkinsfile } from '../../modules/jenkins/scanners';
import { scanGitHubRepo, fixGitHubCode } from '../../modules/github/scanners';
import { scanDependencies, remediateDependency, generateSBOM } from '../../modules/dependencies/scanners';
import { investigateLogs, searchLogs, parseLogFile } from '../../modules/logs/scanners';

interface JobData {
  type: JobType;
  input: Record<string, unknown>;
  userId: string;
  scanId?: string;
  jobId?: string;
}

const queue = new Queue<JobData>('devsecops-jobs', {
  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
  defaultJobOptions: {
    removeOnComplete: 100,
    removeOnFail: 50,
    attempts: 3,
    backoff: { type: 'exponential', delay: 5000 }
  }
});

const queueEvents = new QueueEvents('devsecops-jobs', {
  connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') }
});

queueEvents.on('completed', async ({ jobId, returnvalue }) => {
  console.log('Queue event: completed', jobId);
  await updateJobStatus(jobId, 'completed', 100, 'Completed', returnvalue as any);
});

queueEvents.on('failed', async ({ jobId, failedReason }) => {
  console.log('Queue event: failed', jobId, failedReason);
  await updateJobStatus(jobId, 'failed', 0, 'Failed', undefined, failedReason);
});

queueEvents.on('progress', async ({ jobId, data }) => {
  if (data && typeof data === 'object' && 'progress' in data) {
    const progressData = data as { progress: number; currentStep?: string };
    await updateJobProgress(jobId, progressData.progress, progressData.currentStep || '');
  }
});

export async function initializeQueue(): Promise<void> {
  // Create workers for each job type
  const worker = new Worker<JobData>(
    'devsecops-jobs',
    async (job) => await processJob(job),
    {
      connection: { host: new URL(config.REDIS_URL).hostname, port: parseInt(new URL(config.REDIS_URL).port || '6379') },
      concurrency: config.QUEUE_CONCURRENCY
    }
  );

  worker.on('error', (err) => logger.error({ err }, 'Queue worker error'));
  logger.info('Job queue workers started');
}

export async function shutdownQueue(): Promise<void> {
  await queue.close();
  await queueEvents.close();
}

export async function createJob(data: JobData, priority: 'low' | 'normal' | 'high' = 'normal'): Promise<string> {
  // Create Prisma Job record first
  const prismaJob = await prisma.job.create({
    data: {
      type: data.type,
      status: 'queued',
      input: JSON.stringify(data.input),
      userId: data.userId,
      scanId: data.scanId
    }
  });

  // Add to BullMQ queue with the Prisma job ID
  const job = await queue.add(data.type, { ...data, jobId: prismaJob.id }, {
    priority: priority === 'high' ? 10 : priority === 'low' ? 1 : 5,
    jobId: prismaJob.id
  });

  return job.id!;
}

export async function getJobStatus(jobId: string): Promise<any> {
  const job = await queue.getJob(jobId);
  if (!job) return null;

  const state = await job.getState();
  const progress = job.progress;

  return {
    id: job.id,
    type: job.name,
    status: state,
    progress: typeof progress === 'number' ? progress : 0,
    data: job.data,
    returnvalue: job.returnvalue,
    failedReason: job.failedReason,
    createdAt: new Date(job.timestamp).toISOString(),
    processedAt: job.processedOn ? new Date(job.processedOn).toISOString() : null,
    finishedAt: job.finishedOn ? new Date(job.finishedOn).toISOString() : null
  };
}

export async function cancelJob(jobId: string): Promise<boolean> {
  const job = await queue.getJob(jobId);
  if (job) {
    await job.remove();
    await updateJobStatus(jobId, 'cancelled', 0, 'Cancelled');
    return true;
  }
  return false;
}

async function updateJobStatus(
  jobId: string,
  status: JobStatus,
  progress: number,
  currentStep: string,
  output?: any,
  error?: string
): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: {
      status,
      progress,
      currentStep,
      output,
      error,
      completedAt: ['completed', 'failed', 'cancelled'].includes(status) ? new Date() : null
    }
  });
}

async function updateJobProgress(jobId: string, progress: number, currentStep: string): Promise<void> {
  await prisma.job.updateMany({
    where: { id: jobId },
    data: { progress, currentStep }
  });
}

async function processJob(job: Job<JobData>): Promise<any> {
  const { type, input, userId, scanId: scanIdFromJob, jobId: prismaJobId } = job.data as JobData & { jobId?: string };
  const scanId = scanIdFromJob || '';
  const jobId = prismaJobId || job.id!;

  await prisma.job.update({
    where: { id: jobId },
    data: { status: 'running', startedAt: new Date() }
  });

  try {
    let result: any;
    const i = input as Record<string, unknown>;

    const content = String(i.content ?? '');
    const imageName = String(i.imageName ?? '');
    const dockerfile = String(i.dockerfile ?? '');
    const repoUrl = String(i.repoUrl ?? '');
    const branch = String(i.branch ?? 'main');
    const token = String(i.token ?? '');
    const fileContent = String(i.fileContent ?? '');
    const surroundingContext = String(i.surroundingContext ?? '');
    const question = String(i.question ?? '');
    const query = String(i.query ?? '');
    const filePath = String(i.filePath ?? '');
    const scanIdParam = String(i.scanId ?? '');
    const packageName = String(i.packageName ?? '');
    const currentVersion = String(i.currentVersion ?? '');
    const format = String(i.format ?? 'cyclonedx') as 'cyclonedx' | 'spdx';

    switch (type) {
      case 'dockerfile_scan':
        result = await scanDockerfile(content, job, scanId);
        break;
      case 'dockerfile_fix':
        result = await fixDockerfile(content, (i.findings as any[]) || [], job);
        break;
      case 'docker_image_scan':
        result = await scanDockerImage(imageName, job, scanId);
        break;
      case 'docker_image_fix':
        result = await fixDockerImage(dockerfile, (i.vulnerabilities as any[]) || [], job);
        break;
      case 'kubernetes_scan':
        result = await scanKubernetes(content, job, scanId);
        break;
      case 'kubernetes_fix':
        result = await fixKubernetes(content, (i.findings as any[]) || [], job);
        break;
      case 'kubernetes_generate':
        result = await generateKubernetes(i.spec as any, job);
        break;
      case 'jenkinsfile_scan':
        result = await scanJenkinsfile(content, job, scanId);
        break;
      case 'jenkinsfile_fix':
        result = await fixJenkinsfile(content, (i.findings as any[]) || [], job);
        break;
      case 'jenkinsfile_generate':
        result = await generateJenkinsfile(i.spec as any, job);
        break;
      case 'github_repo_scan':
        result = await scanGitHubRepo(repoUrl, branch, token, job, scanId);
        break;
      case 'github_code_fix':
        result = await fixGitHubCode(i.finding as any, fileContent, surroundingContext, job);
        break;
      case 'log_investigation':
        result = await investigateLogs(question, (i.logEntries as any[]) || [], i.context, job);
        break;
      case 'log_search':
        result = await searchLogs(query, (i.logFiles as string[]) || [], i.options as { caseSensitive?: boolean; regex?: boolean; before?: number; after?: number } || {}, job);
        break;
      case 'log_parse':
        result = await parseLogFile(filePath, job);
        break;
      case 'dependency_scan':
        result = await scanDependencies(i as any, job, scanId);
        break;
      case 'dependency_fix':
        result = await remediateDependency(scanIdParam, packageName, currentVersion, job);
        break;
      case 'sbom_generation':
        result = await generateSBOM(scanIdParam, format, job);
        break;
      default:
        throw new Error(`Unknown job type: ${type}`);
    }

    // Create scan record if applicable
    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: {
          status: 'completed',
          summary: result.summary,
          completedAt: new Date()
        }
      });
    }

    return result;
  } catch (error) {
    logger.error({ err: error, jobId: job.id, type }, 'Job processing failed');

    if (scanId) {
      await prisma.scan.update({
        where: { id: scanId },
        data: { status: 'failed', completedAt: new Date() }
      });
    }

    throw error;
  }
}

import { BaseAIProvider } from '../base';
import { AIRequest, AIResponse, AIModel, DockerfileFixResponse, KubernetesFixResponse, JenkinsfileFixResponse, LogInvestigationResponse, DependencyFixResponse, GitHubCodeFixResponse } from '../types';
import { AIProviderConfig } from '@devsecops/shared/types';

export class AppsScriptProvider extends BaseAIProvider {
  name = 'Google Apps Script (Gemini Bridge)';
  type = 'apps_script';
  private endpoint: string = '';
  private apiKey: string = '';

  protected async onInitialize(): Promise<void> {
    this.endpoint = this.config.endpoint as string || process.env.AI_APPS_SCRIPT_URL || '';
    this.apiKey = this.config.apiKey as string || '';
    if (!this.endpoint) {
      throw new Error('Apps Script endpoint not configured');
    }
  }

  protected getDefaultModels(): AIModel[] {
    return [
      {
        id: 'gemini-1.5-flash',
        name: 'Gemini 1.5 Flash (via Apps Script)',
        maxTokens: 8192,
        supportsStreaming: false,
        supportsTools: false
      },
      {
        id: 'gemini-1.5-pro',
        name: 'Gemini 1.5 Pro (via Apps Script)',
        maxTokens: 32768,
        supportsStreaming: false,
        supportsTools: false
      }
    ];
  }

  async complete(request: AIRequest): Promise<AIResponse> {
    const model = request.model || 'gemini-1.5-flash';
    const systemPrompt = request.systemPrompt || '';
    const fullPrompt = systemPrompt ? `${systemPrompt}\n\n${request.prompt}` : request.prompt;

    const payload = {
      prompt: fullPrompt,
      temperature: request.temperature ?? 0.2,
      maxTokens: request.maxTokens ?? 8192,
      model,
      context: request.context
    };

    try {
      const response = await fetch(this.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(this.apiKey && { 'Authorization': `Bearer ${this.apiKey}` })
        },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        const errorText = await response.text();
        throw new Error(`Apps Script error: ${response.status} ${errorText}`);
      }

      const data = await response.json() as Record<string, unknown>;

      // The Apps Script returns the response in a specific format
      const content = (data.response as string) || (data.content as string) || (data.text as string) || JSON.stringify(data);

      return this.createResponse(content, model, undefined, {
        promptTokens: this.estimateTokens(fullPrompt),
        completionTokens: this.estimateTokens(content),
        totalTokens: this.estimateTokens(fullPrompt) + this.estimateTokens(content)
      });
    } catch (error) {
      console.error('Apps Script AI error:', error);
      throw new Error(`AI request failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  async stream(request: AIRequest, onChunk: (chunk: string) => void): Promise<AIResponse> {
    // Apps Script doesn't support streaming, fall back to complete
    const response = await this.complete(request);
    onChunk(response.content);
    return response;
  }

  // Structured responses for specific tasks
  async fixDockerfile(dockerfile: string, issues: any[], options?: any): Promise<DockerfileFixResponse> {
    const systemPrompt = `You are an expert Dockerfile security and best practices analyzer.
Analyze the provided Dockerfile and return a structured JSON response with:
1. fixedDockerfile - the corrected Dockerfile
2. issues - array of issues found (id, type, severity, line, message, rule, fixable, suggestion)
3. changes - array of changes made (type, originalLine, fixedLine, originalContent, fixedContent, description)
4. securityImprovements - array of security improvements made
5. explanation - human-readable explanation of all fixes

Types: syntax, security, best_practice, performance, style
Severities: critical, high, medium, low, info
Return ONLY valid JSON.`;

    const userPrompt = `Dockerfile to analyze and fix:
\`\`\`dockerfile
${dockerfile}
\`\`\`

${issues.length > 0 ? `Pre-detected issues: ${JSON.stringify(issues, null, 2)}` : ''}

Options: ${JSON.stringify(options || {})}`;

    const response = await this.complete({
      prompt: userPrompt,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 16384
    });

    const structured = this.parseStructuredResponse<DockerfileFixResponse>(response.content, {
      parse: (data: any) => data // We'll validate manually
    });

    if (structured) return structured;

    // Fallback: return minimal response
    return {
      fixedDockerfile: dockerfile,
      issues: [],
      changes: [],
      securityImprovements: [],
      explanation: 'AI response could not be parsed as structured data'
    };
  }

  async fixKubernetes(yaml: string, issues: any[], options?: any): Promise<KubernetesFixResponse> {
    const systemPrompt = `You are an expert Kubernetes YAML analyzer and fixer.
Analyze the provided YAML and return structured JSON with:
1. fixedYaml - corrected YAML
2. issues - array of issues (id, resource, type, severity, path, message, rule, fixable, suggestion)
3. changes - array of changes (type, originalLine, fixedLine, originalContent, fixedContent, description)
4. explanation - human-readable explanation

Types: schema, security, best_practice, performance, reliability
Severities: critical, high, medium, low, info
Return ONLY valid JSON.`;

    const response = await this.complete({
      prompt: `YAML to analyze and fix:\n\`\`\`yaml\n${yaml}\n\`\`\`\n\nIssues: ${JSON.stringify(issues)}\nOptions: ${JSON.stringify(options || {})}`,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 16384
    });

    const structured = this.parseStructuredResponse<KubernetesFixResponse>(response.content, { parse: (d: any) => d });
    return structured || { fixedYaml: yaml, issues: [], changes: [], explanation: 'Could not parse AI response' };
  }

  async fixJenkinsfile(jenkinsfile: string, issues: any[], options?: any): Promise<JenkinsfileFixResponse> {
    const systemPrompt = `You are an expert Jenkins pipeline analyzer.
Analyze the Jenkinsfile and return structured JSON with:
1. fixedJenkinsfile - corrected Jenkinsfile
2. issues - array of issues (id, type, severity, line, message, rule, fixable, suggestion)
3. changes - array of changes
4. explanation - human-readable explanation

Types: syntax, security, best_practice, performance, reliability
Severities: critical, high, medium, low, info
Return ONLY valid JSON.`;

    const response = await this.complete({
      prompt: `Jenkinsfile to analyze and fix:\n\`\`\`groovy\n${jenkinsfile}\n\`\`\`\n\nIssues: ${JSON.stringify(issues)}\nOptions: ${JSON.stringify(options || {})}`,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 16384
    });

    const structured = this.parseStructuredResponse<JenkinsfileFixResponse>(response.content, { parse: (d: any) => d });
    return structured || { fixedJenkinsfile: jenkinsfile, issues: [], changes: [], explanation: 'Could not parse AI response' };
  }

  async investigateLogs(question: string, logEntries: any[], context?: any): Promise<LogInvestigationResponse> {
    const systemPrompt = `You are an expert log analyst and incident investigator.
Analyze the provided logs and answer the question with structured JSON:
1. rootCause - the root cause of the issue
2. evidence - array of relevant log entries with relevance score and explanation
3. timeline - array of timeline events
4. affectedServices - array of affected service names
5. errorPatterns - array of error patterns found
6. recommendedActions - array of recommended actions
7. confidence - confidence score 0-100
8. analyzedEntries - number of entries analyzed

Return ONLY valid JSON.`;

    // Limit log entries to avoid token limits
    const limitedEntries = logEntries.slice(0, 100);

    const response = await this.complete({
      prompt: `Question: ${question}\n\nLog entries (${limitedEntries.length} of ${logEntries.length}):\n${JSON.stringify(limitedEntries, null, 2)}\n\nContext: ${JSON.stringify(context || {})}`,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 16384
    });

    const structured = this.parseStructuredResponse<LogInvestigationResponse>(response.content, { parse: (d: any) => d });
    return structured || {
      rootCause: 'Could not analyze logs',
      evidence: [],
      timeline: [],
      affectedServices: [],
      errorPatterns: [],
      recommendedActions: ['Check logs manually'],
      confidence: 0,
      analyzedEntries: 0
    };
  }

  async fixDependency(pkg: string, currentVersion: string, targetVersion: string, vulnerabilities: any[], manifestContent: string): Promise<DependencyFixResponse> {
    const systemPrompt = `You are an expert dependency security analyst.
Analyze the vulnerability and provide a structured fix recommendation:
1. explanation - why this is vulnerable and how the fix works
2. targetVersion - recommended version
3. breakingChanges - whether update may break things
4. filesToChange - list of files that need modification
5. upgradePath - step-by-step upgrade instructions
6. confidence - confidence score 0-100

Return ONLY valid JSON.`;

    const response = await this.complete({
      prompt: `Package: ${pkg}\nCurrent: ${currentVersion}\nTarget: ${targetVersion}\nVulnerabilities: ${JSON.stringify(vulnerabilities)}\nManifest:\n${manifestContent}`,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 8192
    });

    const structured = this.parseStructuredResponse<DependencyFixResponse>(response.content, { parse: (d: any) => d });
    return structured || {
      explanation: 'Could not analyze',
      targetVersion,
      breakingChanges: false,
      filesToChange: [],
      upgradePath: [],
      confidence: 0
    };
  }

  async fixGitHubCode(finding: any, fileContent: string, surroundingContext: string): Promise<GitHubCodeFixResponse> {
    const systemPrompt = `You are an expert secure code reviewer.
Generate a safe patch for the security finding:
1. patch - unified diff format patch
2. explanation - what the fix does
3. confidence - confidence score 0-100
4. breakingChanges - potential breaking changes

Return ONLY valid JSON.`;

    const response = await this.complete({
      prompt: `Finding: ${JSON.stringify(finding)}\n\nFile content:\n${fileContent}\n\nSurrounding context:\n${surroundingContext}`,
      systemPrompt,
      temperature: 0.1,
      maxTokens: 8192
    });

    const structured = this.parseStructuredResponse<GitHubCodeFixResponse>(response.content, { parse: (d: any) => d });
    return structured || {
      patch: '',
      explanation: 'Could not generate fix',
      confidence: 0,
      breakingChanges: []
    };
  }

  private estimateTokens(text: string): number {
    // Rough estimation: ~4 chars per token
    return Math.ceil(text.length / 4);
  }
}

