      }
    });

  } catch (error) {
    console.error('Apps Script Error:', error);
    return createResponse({ error: error.toString() }, 500);
  }
}

// ============================================
// OPENROUTER API CALL
// ============================================
function callOpenRouterAPI(prompt, temperature, maxTokens, model) {
  const payload = {
    model: model || OPENROUTER_MODEL,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ],
    temperature: temperature ?? 0.2,
    max_tokens: maxTokens ?? 8192,
    top_p: 0.8,
    frequency_penalty: 0,
    presence_penalty: 0
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
      'HTTP Referer': OPENROUTER_REFERER,
      'X-Title': OPENROUTER_TITLE
    },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  const response = UrlFetchApp.fetch(OPENROUTER_API_URL, options);
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();

  if (responseCode !== 200) {
    throw new Error(`OpenRouter API error (${responseCode}): ${responseText}`);
  }

  const data = JSON.parse(responseText);

  // Extract text from OpenRouter response (OpenAI-compatible format)
  if (data.choices && data.choices.length > 0) {
    const choice = data.choices[0];
    if (choice.message && choice.message.content) {
      return choice.message.content;
    }
    // Fallback for older format
    if (choice.text) {
      return choice.text;
    }
  }

  // Fallback
  return 'No response generated';
}

// ============================================
// HEALTH CHECK - GET endpoint for monitoring
// ============================================
function doGet(e) {
  return createResponse({
    status: 'ok',
    service: 'DevSecOps AI Bridge (OpenRouter)',
    model: OPENROUTER_MODEL,
    timestamp: new Date().toISOString()
  });
}

// ============================================
// HELPER FUNCTIONS
// ============================================
function createResponse(data, statusCode = 200) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function estimateTokens(text) {
  // Rough estimation: ~4 chars per token
  return Math.ceil((text || '').length / 4);
}

/**
 * OPTIONAL: Test function - run this in Apps Script editor to verify setup
 * Open Apps Script editor, select testConnection from dropdown, click Run
 */
function testConnection() {
  const result = callOpenRouterAPI('Say "OK" if you can hear me.', 0.1, 10);
  console.log('Test result:', result);
  return result;
}

