async function fixDockerfileSync(content: string, issues: any[], options?: any): Promise<any> {
  // Use AI to generate a fixed Dockerfile
  const prompt = `
You are a Docker security expert. Fix the following Dockerfile issues and return ONLY the fixed Dockerfile.

Original Dockerfile:
\`\`\`dockerfile
${content}
\`\`\`

Issues to fix:
${issues.map((i: any, idx: number) => `${idx + 1}. [${i.severity.toUpperCase()}] Line ${i.line}: ${i.message}${i.suggestion ? ` - Suggestion: ${i.suggestion}` : ''}`).join('\n')}

Return ONLY the fixed Dockerfile content, no explanations, no markdown formatting.
`;

  try {
    const aiResult = await aiService.ask({ prompt, temperature: 0.1, maxTokens: 4096 });

    // Extract fixed dockerfile from AI response
    const fixedDockerfile = aiResult.response.trim().replace(/^```dockerfile\n/, '').replace(/^```\n/, '').replace(/\n```$/, '');

    // Generate changes summary
    const changes = issues.filter(i => i.fixable).map((issue: any) => ({
      findingId: issue.id,
      type: 'ai_fix',
      description: `Fixed: ${issue.message}`,
      line: issue.line
    }));

    return {
      fixedDockerfile,
      changes,
      securityImprovements: issues
        .filter((i: any) => i.fixable)
        .map((i: any) => `Resolved ${i.severity} issue: ${i.message}`),
      explanation: `AI analyzed ${issues.length} issues and applied fixes. ${issues.filter((i: any) => i.fixable).length} issues were fixable and have been addressed.`
    };
  } catch (error) {
    console.error('AI fix failed, returning basic fixes:', error);

    // Fallback: basic fixes
    let fixedDockerfile = content;
    const changes: any[] = [];

    for (const issue of issues) {
      if (issue.fixable && issue.suggestion) {
        // This is a simplified version - real implementation would use more sophisticated parsing
      }
    }

    return {
      fixedDockerfile,
      changes,
      securityImprovements: [],
      explanation: 'AI fix unavailable, returned original Dockerfile'
    };
  }
}

