/**
 * Google Apps Script - OpenRouter AI Bridge for DevSecOps AI Platform
 *
 * INSTRUCTIONS:
 * 1. Go to https://script.google.com/
 * 2. Click "New Project"
 * 3. Replace all code with this file's content
 * 4. Replace YOUR_OPENROUTER_API_KEY_HERE with your actual OpenRouter API key
 * 5. Click "Deploy" → "New deployment" → "Web app"
 * 6. Set "Execute as: Me" and "Who has access: Anyone"
 * 7. Copy the Web App URL and add to your .env as AI_APPS_SCRIPT_URL
 *
 * GET YOUR OPENROUTER API KEY: https://openrouter.ai/keys
 * FREE MODELS AVAILABLE: https://openrouter.ai/models?max_price=0
 */

// ============================================
// CONFIGURATION - REPLACE WITH YOUR API KEY
// ============================================
const OPENROUTER_API_KEY = 'YOUR_OPENROUTER_API_KEY_HERE';
// Free models (choose one):
// 'meta-llama/llama-3.2-3b-instruct:free' - Meta Llama 3.2 3B (free)
// 'microsoft/phi-3-mini-128k-instruct:free' - Microsoft Phi-3 Mini (free)
// 'google/gemma-2-9b-it:free' - Google Gemma 2 9B (free)
// 'mistralai/mistral-7b-instruct:free' - Mistral 7B (free)
// 'qwen/qwen-2.5-7b-instruct:free' - Qwen 2.5 7B (free)
const OPENROUTER_MODEL = 'meta-llama/llama-3.2-3b-instruct:free';
const OPENROUTER_API_URL = 'https://openrouter.ai/api/v1/chat/completions';
const OPENROUTER_REFERER = 'https://devsecops-ai-platform.example.com'; // Optional: for tracking
const OPENROUTER_TITLE = 'DevSecOps AI Platform'; // Optional: for tracking

// ============================================
// MAIN ENTRY POINT - doPost handles all requests
// ============================================
function doPost(e) {
  try {
    // Parse request body
    let requestData = {};
    if (e.postData && e.postData.contents) {
      requestData = JSON.parse(e.postData.contents);
    }

    const { prompt, temperature, maxTokens, model, systemPrompt, context } = requestData;

    // Validate required fields
    if (!prompt) {
      return createResponse({ error: 'Missing required field: prompt' }, 400);
    }

    // Build the full prompt with system prompt and context
    let fullPrompt = prompt;
    if (systemPrompt) {
      fullPrompt = systemPrompt + '\n\n' + fullPrompt;
    }
    if (context && context.additional) {
      fullPrompt += '\n\nAdditional Context:\n' + context.additional;
    }

    // Call OpenRouter API
    const openRouterResponse = callOpenRouterAPI(fullPrompt, temperature, maxTokens, model);

    // Return in format expected by the frontend
    return createResponse({
      response: openRouterResponse,
      model: model || OPENROUTER_MODEL,
      usage: {
        promptTokens: estimateTokens(fullPrompt),
        completionTokens: estimateTokens(openRouterResponse),
        totalTokens: estimateTokens(fullPrompt) + estimateTokens(openRouterResponse)
      }
    });

  } catch (error) {
    console.error('Apps Script Error:', error);
    return createResponse({ error: error.toString() }, 500);
  }
}

// ============================================
// GET ENDPOINT - for testing and health checks
// Supports query parameters: ?prompt=...&model=...&temperature=...&maxTokens=...&systemPrompt=...&context=...
// ============================================
function doGet(e) {
  try {
    // Check if this is a health check (no prompt)
    if (!e.parameter || !e.parameter.prompt) {
      return createResponse({
        status: 'ok',
        service: 'DevSecOps AI Bridge (OpenRouter)',
        model: OPENROUTER_MODEL,
        timestamp: new Date().toISOString()
      });
    }

    // Parse query parameters
    const prompt = e.parameter.prompt;
    const temperature = e.parameter.temperature ? parseFloat(e.parameter.temperature) : undefined;
    const maxTokens = e.parameter.maxTokens ? parseInt(e.parameter.maxTokens, 10) : undefined;
    const model = e.parameter.model;
    const systemPrompt = e.parameter.systemPrompt;
    const context = e.parameter.context ? { additional: e.parameter.context } : undefined;

    // Build the full prompt with system prompt and context
    let fullPrompt = prompt;
    if (systemPrompt) {
      fullPrompt = systemPrompt + '\n\n' + fullPrompt;
    }
    if (context && context.additional) {
      fullPrompt += '\n\nAdditional Context:\n' + context.additional;
    }

    // Call OpenRouter API
    const openRouterResponse = callOpenRouterAPI(fullPrompt, temperature, maxTokens, model);

    // Return in format expected by the frontend
    return createResponse({
      response: openRouterResponse,
      model: model || OPENROUTER_MODEL,
      usage: {
        promptTokens: estimateTokens(fullPrompt),
        completionTokens: estimateTokens(openRouterResponse),
        totalTokens: estimateTokens(fullPrompt) + estimateTokens(openRouterResponse)
      }
    });

  } catch (error) {
    console.error('Apps Script Error:', error);
    return createResponse({ error: error.toString() }, 500);
  }
}

// ============================================
// OPENROUTER API CALL
// ============================================
function callOpenRouterAPI(prompt, temperature, maxTokens, model) {
  const payload = {
    model: model || OPENROUTER_MODEL,
    messages: [
      {
        role: 'user',
        content: prompt
      }
    ],
    temperature: temperature ?? 0.2,
    max_tokens: maxTokens ?? 8192,
    top_p: 0.8,
    frequency_penalty: 0,
    presence_penalty: 0
  };

  const options = {
    method: 'post',
    contentType: 'application/json',
    headers: {
      'Authorization': `Bearer ${OPENROUTER_API_KEY}`,
      'HTTP Referer': OPENROUTER_REFERER,
      'X-Title': OPENROUTER_TITLE
    },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  const response = UrlFetchApp.fetch(OPENROUTER_API_URL, options);
  const responseCode = response.getResponseCode();
  const responseText = response.getContentText();

  if (responseCode !== 200) {
    throw new Error(`OpenRouter API error (${responseCode}): ${responseText}`);
  }

  const data = JSON.parse(responseText);

  // Extract text from OpenRouter response (OpenAI-compatible format)
  if (data.choices && data.choices.length > 0) {
    const choice = data.choices[0];
    if (choice.message && choice.message.content) {
      return choice.message.content;
    }
    // Fallback for older format
    if (choice.text) {
      return choice.text;
    }
  }

  // Fallback
  return 'No response generated';
}

// ============================================
// HEALTH CHECK - GET endpoint for monitoring
// ============================================
function doGet(e) {
  return createResponse({
    status: 'ok',
    service: 'DevSecOps AI Bridge (OpenRouter)',
    model: OPENROUTER_MODEL,
    timestamp: new Date().toISOString()
  });
}

// ============================================
// HELPER FUNCTIONS
// ============================================
function createResponse(data, statusCode = 200) {
  return ContentService
    .createTextOutput(JSON.stringify(data))
    .setMimeType(ContentService.MimeType.JSON);
}

function estimateTokens(text) {
  // Rough estimation: ~4 chars per token
  return Math.ceil((text || '').length / 4);
}

/**
 * OPTIONAL: Test function - run this in Apps Script editor to verify setup
 * Open Apps Script editor, select testConnection from dropdown, click Run
 */
function testConnection() {
  const result = callOpenRouterAPI('Say "OK" if you can hear me.', 0.1, 10);
  console.log('Test result:', result);
  return result;
}

